INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u2-C1','kor',6,1,'u2',1,'고쳐쓰기의 뜻 — 쓴 글을 점검해 하고 싶은 말이 더 잘 전달되도록 필요한 곳만 손보는 일로, 처음 쓴 글을 버리고 처음부터 다시 쓰는 일이나 글씨를 예쁘게 다시 옮겨 적는 일이 아니다',ARRAY['6국03-06 쓰기']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u2-C2','kor',6,1,'u2',1,'고쳐쓰기의 네 가지 일 — 주제에서 벗어난 내용 빼기 · 부족한 내용 더하기 · 어색한 표현을 알맞은 말로 바꾸기 · 순서가 뒤엉킨 부분 옮기기를 필요한 곳에만 하며, 친구 글을 고칠 때에는 다시 짜기까지 다섯 가지로 볼 수 있다',ARRAY['6국04-06 문법']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u2-C3','kor',6,1,'u2',1,'세 수준으로 보기와 큰 것부터 — 고쳐 쓸 때에는 글 수준(제목과 내용 · 처음 · 가운데 · 끝의 흐름) · 문단 수준(중심 문장 · 어울리지 않는 뒷받침 문장) · 문장 수준(호응 · 띄어쓰기)의 세 크기로 보며, 글 → 문단 → 문장의 차례로 큰 것부터 살펴야 헛수고가 줄어든다',ARRAY['6국04-06 문법']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u2-C4','kor',6,1,'u2',1,'고쳐 쓴 글을 나누는 까닭 — 고쳐 쓴 글을 게시판 등에 올려 다른 사람과 나누면 내가 못 본 곳을 친구가 짚어 주고, 읽는 사람의 반응을 바로 알 수 있으며, 읽는 사람이 있다고 생각하면 문장을 더 꼼꼼히 보게 되어 고쳐쓰기에 큰 도움이 된다',ARRAY['6국03-06 쓰기']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u2-C5','kor',6,1,'u2',1,'친구 글에 의견을 말하는 방법 — 같은 내용이라도 말하는 방식에 따라 듣는 사람의 마음이 달라지므로, 잘한 곳을 먼저 말하고 고칠 곳은 반드시 까닭과 함께 말해(잘한 곳 → 고칠 곳 → 까닭) 글쓴이가 다시 고쳐 쓰고 싶어지게 한다',ARRAY['6국03-06 쓰기']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u2-C6','kor',6,1,'u2',1,'온라인에 글을 올릴 때 지킬 것 — 여러 사람이 읽고 의견을 주고 고치기 쉬우며 사진 · 영상도 함께 올릴 수 있지만, 한 번 올린 글은 널리 퍼지므로 줄임말 · 은어 · 비속어를 쓰지 않고 자료를 옮길 때에는 출처를 밝히며 읽는 사람이 누구인지 떠올리며 쓴다',ARRAY['6국03-06 쓰기']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u2-C7','kor',6,1,'u2',1,'고쳐쓰기는 혼나는 일이 아니다 — 고쳐 쓰라는 말은 내 글이 잘못됐다는 뜻이 아니라 여기만 손보면 하고 싶은 말이 더 잘 전해진다는 뜻이며, 완벽한 글을 만드는 일이 아니므로 한 군데를 고쳤으면 그만큼 나아진 것이고 작게 고친 것도 잘 고친 것이다',ARRAY['6국03-06 쓰기']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u2-C8','kor',6,1,'u2',2,'제목이 내용을 나타내는가 — 글 수준에서 제목에 글의 내용과 중심 생각, 글쓴이가 느낀 것이 드러나는지 보며(「모래성 이야기」 → 「무너져도 다시 손을 대는 힘」), 글을 다 쓴 뒤 가장 하고 싶었던 말을 한 줄로 적어 제목으로 옮겨 본다',ARRAY['6국04-06 문법']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u2-C9','kor',6,1,'u2',2,'처음 · 가운데 · 끝의 흐름 — 감상문은 처음(무엇을 보았는지 · 왜 보게 되었는지) → 가운데(간단한 줄거리 · 인상 깊은 장면과 그때의 생각) → 끝(느낀 점이나 다짐)으로 이어지며, 차례가 뒤엉켰으면 내용은 그대로 두고 문단의 차례만 옮겨도 글이 훨씬 잘 읽힌다',ARRAY['6국04-06 문법']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u2-C10','kor',6,1,'u2',2,'중심 내용은 근거가 있으면 여럿 — 같은 글의 중심 내용도 사람마다 조금씩 다르게 말할 수 있어(다시 시작하는 힘 · 함께하면 더 오래 버틴다), 물어야 할 것은 「정답인가」가 아니라 글에서 근거를 댈 수 있는가이다',ARRAY['6국04-06 문법']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u2-C11','kor',6,1,'u2',2,'중심 문장과 뒷받침 문장 — 문단에는 하고 싶은 말을 담은 중심 문장(보통 하나)과 그것을 자세히 설명하거나 예를 드는 뒷받침 문장이 있으며, 문단을 고칠 때에는 먼저 중심 문장을 찾고 뒷받침 문장 가운데 중심 문장과 상관없는 것이 있는지 본다',ARRAY['6국04-06 문법']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u2-C12','kor',6,1,'u2',2,'거리가 먼 문장은 빼거나 고쳐 쓴다 — 중심 문장과 아무 관련이 없으면 지우고(우리 집 강아지도 모래를 좋아한다 → 삭제), 관련은 있는데 표현이 어긋났으면 바꾸어(여름 내내 쌓았다 → 여름 내내 모래성을 쌓았다) 무조건 지우지 않고 지울지 고칠지부터 정한다',ARRAY['6국04-06 문법']::text[],12) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u2-C13','kor',6,1,'u2',2,'문장 성분과 호응 — 주어(무엇이 · 누가) · 목적어(무엇을 · 누구를) · 서술어(어찌하다 · 어떠하다)가 서로 어울리는 것을 호응이라 하며, 내용이 아무리 좋아도 호응이 어긋나면 뜻이 제대로 전해지지 않으므로 고쳐 쓸 때에는 내용과 형식을 함께 본다',ARRAY['6국04-04 문법']::text[],13) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u2-C14','kor',6,1,'u2',2,'호응이 어긋나는 네 가지 — 높임(선생님이 소개했다 → 선생님께서 소개해 주셨다) · 피동과 사동(성이 파도에 무너뜨렸다 → 무너졌다) · 시제(어제 볼 것이다 → 어제 보았다) · 부정(전혀 지루했다 → 전혀 지루하지 않았다)에서 자주 어긋나며, 서술어를 짚고 앞의 말과 어울리는지 소리 내어 읽어 찾는다',ARRAY['6국04-04 문법']::text[],14) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u2-C15','kor',6,1,'u2',2,'세 수준은 따로 도는 절차가 아니다 — 큰 흐름을 손보다 보면 문단이, 문단을 손보다 보면 문장이 보이므로 어느 수준에서 발견하든 그때그때 함께 고치며, 고칠 때 쓰는 부호(∨ 띄어 쓸 때 · ⌒ 붙여 쓸 때 · ⊂ 내용을 더 넣을 때)를 쓰면 지우고 다시 옮겨 쓸 필요가 없다',ARRAY['6국04-06 문법']::text[],15) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u2-C16','kor',6,1,'u2',4,'띄어쓰기는 뜻을 가르는 일 — 같은 글자도 어디서 띄느냐에 따라 전혀 다른 말이 되므로(오늘 밤 나무를 심자 · 오늘 밤나무를 심자 / 큰 집 · 큰집 / 잘 못했다 · 잘못했다), 띄어쓰기는 글씨를 예쁘게 쓰는 일이 아니라 읽는 사람이 글쓴이의 뜻을 알아내게 하는 일이다',ARRAY['6국04-06 문법']::text[],16) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u2-C17','kor',6,1,'u2',4,'수와 세는 말은 띄어 쓴다 — 권 · 마리 · 원 · 그루 · 장 · 잔 · 자루 · 개처럼 세는 말(단위를 나타내는 말)은 앞의 수와 띄어 쓴다(책 세 권 · 나무 두 그루 · 삼천 원 · 종이 스물네 장)',ARRAY['6국04-06 문법']::text[],17) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u2-C18','kor',6,1,'u2',4,'잇거나 나열하는 말은 띄어 쓴다 — 및 · 대 · 겸 · 등처럼 두 말 사이를 잇거나 나열하는 말은 앞뒤를 모두 띄어 쓴다(학생 및 학부모 · 청군 대 백군 · 서점 겸 찻집 · 연필이나 볼펜 등)',ARRAY['6국04-06 문법']::text[],18) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u2-C19','kor',6,1,'u2',4,'조사는 붙이고 홀로 못 쓰는 이름씨는 띄운다 — 이/가 · 을/를 · 은/는 · 에서 · 에게 · 도 · 만 · 처럼 같은 조사는 앞말에 붙여 쓰고(나무처럼), 것 · 수 · 데 · 지 · 만큼처럼 홀로 못 쓰는 이름씨는 띄어 쓰며(할 수 있다), 헷갈리면 앞말에 얹혀 가는 말인지 따로 뜻을 가진 말인지 물어본다',ARRAY['6국04-06 문법']::text[],19) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u2-C20','kor',6,1,'u2',4,'내 띄어쓰기 습관을 점검하기 — 띄어 쓸 곳은 ∨ 부호로 표시해 두고 마지막에 한 번에 옮기면 고칠 곳이 많아도 처음부터 다시 쓸 필요가 없으며, 내가 자주 놓치는 띄어쓰기 한 가지를 스스로 정해 다음 글부터 챙긴다',ARRAY['6국04-06 문법']::text[],20) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u2-C21','kor',6,1,'u2',5,'감상문과 줄거리 요약 — 줄거리 요약은 무슨 일이 일어났는지만 적어 누가 써도 거의 같은 글이 되지만, 감상문은 본 것에 더해 내가 무엇을 느끼고 생각했는지를 적어 쓴 사람마다 다른 글이 된다',ARRAY['6국03-06 쓰기']::text[],21) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u2-C22','kor',6,1,'u2',5,'인상 깊은 장면과 그 까닭 — 감상문의 출발점은 마음에 남은 한 장면이며, 「이 장면이 좋았다」로 끝내지 않고 왜 그 장면이 남았는지(각자 우산을 쓰는데도 둘이 더 가까워 보여서 · 도움을 받는 게 왜 어려웠을지 생각하게 돼서)까지 적어야 감상문이 된다',ARRAY['6국03-06 쓰기']::text[],22) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u2-C23','kor',6,1,'u2',5,'감상문에 담을 내용과 짜임 — 보게 된 동기 · 간단한 줄거리 · 인상 깊은 장면과 까닭 · 느낀 점이나 다짐을 담고, 처음(무엇을 · 어떻게 보게 되었는지) → 가운데(줄거리는 짧게, 장면과 생각은 길게 — 가장 긺) → 끝(느낀 점과 앞으로 하고 싶은 일)으로 짜며, 모든 장면이나 상관없는 자잘한 것은 넣지 않는다',ARRAY['6국03-06 쓰기']::text[],23) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u2-C24','kor',6,1,'u2',5,'고칠 차례 — 큰 것부터, 고르게 — 초고를 고칠 때에는 제목과 글 전체의 흐름부터 잡고(문장을 다 다듬었는데 그 문장이 통째로 빠져야 하면 헛수고) 문단 → 문장 차례로 고르게 살피며, 맞춤법 · 띄어쓰기는 마지막에 하는 일이라 그것만 바로잡거나 낱말 몇 개만 바꾸는 것으로 고쳐쓰기가 끝나지 않는다',ARRAY['6국04-06 문법']::text[],24) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u2-C25','kor',6,1,'u2',7,'명확한 문장의 세 가지 조건 — 한 문장에는 한 가지만 담고(길면 나눔) · 주어 · 목적어 · 서술어 가운데 빠진 것이 없게 하고 · 겹치는 표현은 하나로 줄이면(되풀이되던 「번호」 → 숫자 · 표시) 글자 수는 줄어도 뜻은 더 또렷해져 읽는 사람이 두 번 읽지 않아도 된다',ARRAY['6국04-04 문법']::text[],25) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u2-C26','kor',6,1,'u2',7,'말과 달리 글에서는 필수 성분을 갖춘다 — 말할 때에는 서로 아는 것이 많아 주어와 목적어를 빼도 통하지만(여기 있어. 아까 찾던 거.), 읽는 사람은 그 자리에 없었으므로 글에서는 주어 · 목적어 · 서술어 같은 필수 성분을 갖춰야 뜻이 전해진다',ARRAY['6국04-04 문법']::text[],26) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u2-C27','kor',6,1,'u2',7,'주제와 제목 정하기 — 좋은 주제는 친구들이 궁금해할 만하고 내가 끝까지 자료를 모을 수 있는 것이며(너무 넓거나 자료를 거의 찾을 수 없는 것은 어렵다), 제목은 내용과 일치하고 짧으면서 읽는 사람의 관심을 끌어야 하므로 주제를 정한 다음에 정한다',ARRAY['6국03-06 쓰기']::text[],27) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u2-C28','kor',6,1,'u2',7,'믿을 수 있는 자료와 출처 — 자료는 누가 만들었는지(믿을 수 있는가) · 언제 만들었는지(지금도 맞는가) · 어디서 가져왔는지(출처를 밝혔는가)를 확인하며, 누가 언제 썼는지 알 수 없는 글이나 어디선가 들었다는 이야기처럼 확인하지 않은 자료는 쓰지 않는다',ARRAY['6국03-06 쓰기']::text[],28) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u2-C29','kor',6,1,'u2',7,'설명하는 글의 짜임 — 처음(무엇을 설명할지 밝히고 관심을 끎) → 가운데(설명하려는 내용을 알기 쉽고 자세하게 — 무엇을 나타내는지 · 나누는 방법의 예 · 찾는 차례) → 끝(전체 내용을 간추리고 마무리)으로 짜며, 쓰기 전에 세 칸을 한 줄씩 채워 두면 글이 흩어지지 않는다',ARRAY['6국03-06 쓰기']::text[],29) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u2-C30','kor',6,1,'u2',7,'찾은 자료는 내 말로 바꾸어 쓴다 — 찾은 자료를 그대로 붙여 넣는 것은 글쓰기가 아니며 읽고 이해한 뒤 내 말로 다시 쓰고, 읽는 사람이 아는 말로 풀어 쓰며 줄임말 · 은어 · 비속어를 쓰지 않고 가져온 곳을 함께 적으며, 디지털 매체로 쓸 때에는 자주 저장하고 내용과 이어지는 그림만 넣는다',ARRAY['6국03-06 쓰기']::text[],30) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u2-C31','kor',6,1,'u2',9,'친구 글에 대한 의견의 네 갈래 — 친구 글은 먼저 무슨 말을 하려는 글인지 한 줄로 잡은 뒤, 새롭게 안 점(몰랐는데 알게 된 것) · 궁금한 점(더 알고 싶은 것) · 좋은 점(잘 쓴 곳과 까닭) · 고쳤으면 하는 점(고칠 곳과 까닭)으로 나누어 「그냥 좋아」나 「별로야」로 끝나지 않게 한다',ARRAY['6국03-06 쓰기']::text[],31) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u2-C32','kor',6,1,'u2',9,'의견은 골라서 받아들인다 — 의견은 받는 것이고 고르는 것은 글쓴이이므로 친구의 의견을 모두 따를 필요는 없으며, 「이 의견을 따르면 내가 하려던 말이 더 잘 전해지는가?」를 기준으로 고르고 따르지 않기로 했다면 그 까닭을 스스로 말할 수 있으면 된다',ARRAY['6국03-06 쓰기']::text[],32) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u2-C33','kor',6,1,'u2',9,'공유하는 차례와 좋은 점 — 고쳐 쓴 마지막 글을 올리고 → 제대로 올라갔는지 확인하고 → 친구 글에 댓글을 달고 → 내 글에 달린 댓글을 읽고 다시 점검하며, 댓글에는 읽었다는 것과 어떻게 했는지를 답글로 알린다; 공유하면 혼자서는 놓친 곳 · 내 글이 어떻게 읽히는지 · 새로운 생각을 얻는다',ARRAY['6국03-06 쓰기']::text[],33) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u2-C34','kor',6,1,'u2',9,'맞춤법 검사기와 인공 지능 도구 — 띄어쓰기와 맞춤법을 빠르게 짚어 주고 내가 자주 틀리는 곳을 알게 해 주지만, 글의 중심 생각은 도구가 정해 주지 못하고 고칠지 말지는 글쓴이가 정하며, 도구가 고친 곳도 왜 그렇게 고쳤는지 확인하고 받아들인다',ARRAY['6국04-06 문법']::text[],34) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u2-C35','kor',6,1,'u2',9,'사진과 영상도 글의 한 부분 — 글에 넣은 사진 · 영상이 설명하는 내용을 바로 보여 주는지(책등의 숫자가 보이는 서가 사진) 겉도는지(도서관 건물 바깥 풍경) 점검하며, 내용과 이어지지 않으면 보기 좋아도 빼는 것이 고쳐쓰기다',ARRAY['6국03-06 쓰기']::text[],35) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u2-C36','kor',6,1,'u2',12,'소개하는 글 — 고르기와 짜임 — 물건 · 작품(감상문 형식) · 알게 된 것(설명하는 형식) 가운데 쓸 말이 세 문단쯤 나오는 것을 고르고, 처음(무엇을 소개할지 · 왜 골랐는지) → 가운데(어떤 것인지 자세히 · 나와 얽힌 그것만의 이야기) → 끝(소개를 맺으며 앞으로 하고 싶은 일)으로 쓴다',ARRAY['6국03-06 쓰기']::text[],36) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u2-C37','kor',6,1,'u2',12,'소개는 자랑이 아니다 — 「내 자전거가 제일 좋다」처럼 쓰면 읽는 사람이 알 수 있는 것이 없으므로 「손잡이가 손 모양대로 닳아서 잡으면 손이 딱 맞는다」처럼 읽는 사람이 그려 볼 수 있게 쓰며, 친구 글에는 잘한 곳을 짚고 부족한 곳은 까닭과 함께 알려 주며 글을 조금씩 나아지게 한다',ARRAY['6국03-06 쓰기']::text[],37) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u2-C38','kor',6,1,'u2',12,'시간 표현 · 주어와 서술어의 짝 — 어제 · 지난주 · 아까는 「보았다」, 오늘 · 지금은 「본다」, 내일 · 다음 주는 「볼 것이다」처럼 시간을 나타내는 말이 앞에 나오면 서술어가 끌려가고, 주어가 「내 생각은」이면 「~것이다」로, 주어가 스스로 한 일이 아니면 「~되다 · ~히다」로 받는다(화면이 어둠으로 채워졌다)',ARRAY['6국04-04 문법']::text[],38) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u2-C39','kor',6,1,'u2',12,'주동과 피동 — 주체가 스스로 하는 일은 주동(내가 문을 닫다 · 그림을 걸다 · 책을 놓다), 다른 힘에 의해 그리 되는 일은 피동(문이 닫히다 · 그림이 걸리다 · 책이 놓이다)으로 쓰며, 스스로 하는 일에는 -히- · -리- · -이-를 붙이지 않는다 (기초 다지기)',ARRAY['기초 다지기(주동과 피동)']::text[],39) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u2-X01','kor',6,'u2',ARRAY['K6-1-u2-C1']::text[],'고쳐쓰기를 처음 쓴 글을 버리고 처음부터 다시 쓰는 일이나 글씨를 예쁘게 다시 옮겨 적는 일로 여긴다','필요한 곳만 손보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u2-X02','kor',6,'u2',ARRAY['K6-1-u2-C7']::text[],'고쳐 쓰라는 말을 내 글이 잘못됐다는 뜻으로 여겨 통째로 다시 쓰거나, 완벽하게 고쳐야 하며 작게 고친 것은 소용없다고 여긴다','작게 고친 것도 잘 고친 것') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u2-X03','kor',6,'u2',ARRAY['K6-1-u2-C2']::text[],'빼기 · 더하기 · 바꾸기 · 옮기기를 서로 헷갈리거나, 고칠 필요가 없는 곳까지 손본다','필요한 곳에 알맞은 손질') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u2-X04','kor',6,'u2',ARRAY['K6-1-u2-C3']::text[],'살필 일이 글 · 문단 · 문장 가운데 어느 수준의 일인지 헷갈린다','글 전체? 문단 하나? 한 문장?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u2-X05','kor',6,'u2',ARRAY['K6-1-u2-C3','K6-1-u2-C24']::text[],'띄어쓰기 · 맞춤법부터 손대거나, 그것만 바로잡고 낱말 몇 개만 바꾸면 고쳐쓰기가 끝났다고 여긴다','큰 것부터, 맞춤법은 마지막') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u2-X06','kor',6,'u2',ARRAY['K6-1-u2-C5']::text[],'고칠 곳만 늘어놓거나 「다시 써」처럼 글쓴이를 위축시키는 말로 의견을 말한다','잘한 곳을 먼저') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u2-X07','kor',6,'u2',ARRAY['K6-1-u2-C5','K6-1-u2-C31']::text[],'「다 좋아, 고칠 곳 하나도 없어」처럼 막연한 칭찬만 해 글쓴이에게 쓸모 있는 말을 주지 못한다','어디가 왜 좋은지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u2-X08','kor',6,'u2',ARRAY['K6-1-u2-C5']::text[],'고칠 곳을 까닭 없이 「여기 고쳐」라고만 말한다','고칠 곳은 까닭과 함께') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u2-X09','kor',6,'u2',ARRAY['K6-1-u2-C6','K6-1-u2-C30']::text[],'온라인에 줄임말 · 은어 · 비속어를 쓰거나, 남의 자료를 출처를 밝히지 않고 옮긴다','한 번 올린 글은 널리 퍼져요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u2-X10','kor',6,'u2',ARRAY['K6-1-u2-C4','K6-1-u2-C33']::text[],'글을 나누는 것을 칭찬받는 일로 여기거나, 나누면 더 고치지 않아도 된다고 여긴다','못 본 곳을 알게 되는 일') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u2-X11','kor',6,'u2',ARRAY['K6-1-u2-C8','K6-1-u2-C27']::text[],'제목은 글감이나 줄거리만 알리면 된다고 여겨 중심 생각이나 느낀 것을 담지 않는다','가장 하고 싶었던 말') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u2-X12','kor',6,'u2',ARRAY['K6-1-u2-C9','K6-1-u2-C23','K6-1-u2-C29']::text[],'처음 · 가운데 · 끝에 들어갈 내용을 뒤섞거나 문단의 차례를 뒤엉킨 채 둔다','처음 · 가운데 · 끝') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u2-X13','kor',6,'u2',ARRAY['K6-1-u2-C10']::text[],'글의 중심 내용은 정답이 하나뿐이라고 여기거나, 근거 없이 중심 내용을 정한다','근거를 댈 수 있는가') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u2-X14','kor',6,'u2',ARRAY['K6-1-u2-C11']::text[],'중심 문장과 뒷받침 문장을 서로 헷갈린다','하고 싶은 말 / 자세히 설명') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u2-X15','kor',6,'u2',ARRAY['K6-1-u2-C11','K6-1-u2-C12']::text[],'주제나 중심 문장과 상관없는 문장을 그대로 둔다','중심 문장과 이어지나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u2-X16','kor',6,'u2',ARRAY['K6-1-u2-C12']::text[],'중심 문장과 관련은 있는데 표현만 어긋난 문장까지 무조건 지운다','뺄지 고칠지부터') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u2-X17','kor',6,'u2',ARRAY['K6-1-u2-C13']::text[],'내용만 좋으면 문장 성분의 호응이 어긋나도 뜻이 전해진다고 여긴다','내용과 형식을 함께') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u2-X18','kor',6,'u2',ARRAY['K6-1-u2-C14']::text[],'웃어른이 주어인데 높임 표현으로 받지 않는다(선생님이 소개했다 · 아버지가 물려줬다)','께서 · ~시다') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u2-X19','kor',6,'u2',ARRAY['K6-1-u2-C14','K6-1-u2-C39']::text[],'당하는 말을 써야 할 곳에 시키거나 스스로 하는 말을 쓴다(성이 파도에 무너뜨렸다)','누가 한 일인가?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u2-X20','kor',6,'u2',ARRAY['K6-1-u2-C14','K6-1-u2-C38']::text[],'시간을 나타내는 말과 서술어의 때를 어긋나게 쓴다(어제 볼 것이다)','어제 → 보았다') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u2-X21','kor',6,'u2',ARRAY['K6-1-u2-C14']::text[],'「전혀 · 조금도 · 별로」 같은 말 뒤에 부정하는 서술어를 쓰지 않는다(전혀 지루했다)','전혀 → ~지 않다') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u2-X22','kor',6,'u2',ARRAY['K6-1-u2-C15']::text[],'글 · 문단 · 문장 수준을 따로따로 세 번 차례대로 도는 절차로 여겨 발견한 것을 미뤄 둔다','보이는 그때그때 함께') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u2-X23','kor',6,'u2',ARRAY['K6-1-u2-C15','K6-1-u2-C20']::text[],'고칠 때 쓰는 부호(∨ · ⌒ · ⊂)의 쓰임을 서로 헷갈린다','띄움 · 붙임 · 더 넣음') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u2-X24','kor',6,'u2',ARRAY['K6-1-u2-C16']::text[],'띄어쓰기를 뜻과 상관없는 글씨 문제로 여겨 조금 틀려도 읽는 사람이 다 알아듣는다고 여긴다','한 칸이 뜻을 갈라요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u2-X25','kor',6,'u2',ARRAY['K6-1-u2-C17']::text[],'권 · 마리 · 장 · 개 같은 세는 말을 앞의 수에 붙여 쓴다','수 ∨ 세는 말') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u2-X26','kor',6,'u2',ARRAY['K6-1-u2-C18']::text[],'및 · 대 · 겸 · 등 같은 잇거나 나열하는 말을 앞말이나 뒷말에 붙여 쓴다','잇는 말 앞뒤를 띄워요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u2-X27','kor',6,'u2',ARRAY['K6-1-u2-C19']::text[],'이/가 · 을/를 · 처럼 · 에게 같은 조사를 앞말과 띄어 쓴다','조사는 앞말에 얹혀 가요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u2-X28','kor',6,'u2',ARRAY['K6-1-u2-C19']::text[],'것 · 수 · 데 · 지 · 만큼 같은 홀로 못 쓰는 이름씨를 앞말에 붙여 쓴다','할 ∨ 수 ∨ 있다') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u2-X29','kor',6,'u2',ARRAY['K6-1-u2-C20']::text[],'띄어 쓸 곳이 많으면 지우고 처음부터 옮겨 쓰거나, 내가 자주 놓치는 곳을 정해 두지 않고 규칙만 외우면 된다고 여긴다','∨ 로 표시 · 내 버릇 한 가지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u2-X30','kor',6,'u2',ARRAY['K6-1-u2-C21']::text[],'감상문을 무슨 일이 일어났는지만 적는 줄거리 요약으로 여긴다','내가 느끼고 생각한 것') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u2-X31','kor',6,'u2',ARRAY['K6-1-u2-C22']::text[],'인상 깊은 장면을 고르고 「좋았다 · 재미있었다」로 끝내 왜 그 장면이 남았는지 쓰지 않는다','왜 그 장면이 남았나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u2-X32','kor',6,'u2',ARRAY['K6-1-u2-C23']::text[],'감상문에 모든 장면이나 옷 색깔 같은 상관없는 자잘한 것을 넣고, 줄거리를 길게 늘어놓는다','줄거리는 짧게, 생각은 길게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u2-X33','kor',6,'u2',ARRAY['K6-1-u2-C25']::text[],'한 문장에 여러 가지를 이어 붙여 길게 쓴다','한 문장에 한 가지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u2-X34','kor',6,'u2',ARRAY['K6-1-u2-C26','K6-1-u2-C25']::text[],'글에서도 말할 때처럼 주어 · 목적어 · 서술어를 빼고 쓴다','읽는 사람은 그 자리에 없었어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u2-X35','kor',6,'u2',ARRAY['K6-1-u2-C25']::text[],'같은 낱말이나 겹치는 표현을 되풀이해 쓴다','겹치는 것은 하나로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u2-X36','kor',6,'u2',ARRAY['K6-1-u2-C27','K6-1-u2-C36']::text[],'너무 넓거나 쓸 말 · 자료가 거의 없는 주제를 고르거나, 내용과 다른 제목을 단다','끝까지 쓸 수 있는 주제') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u2-X37','kor',6,'u2',ARRAY['K6-1-u2-C28']::text[],'누가 언제 만들었는지 모르는 자료나 어디선가 들은 이야기를 확인하지 않고 쓴다','누가 · 언제 · 어디서') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u2-X38','kor',6,'u2',ARRAY['K6-1-u2-C30']::text[],'찾은 자료를 이해하지 않고 그대로 옮겨 붙여도 내 글이 된다고 여긴다','내 말로 바꾸어 쓰기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u2-X39','kor',6,'u2',ARRAY['K6-1-u2-C31']::text[],'친구의 말이 새롭게 안 점 · 궁금한 점 · 좋은 점 · 고쳤으면 하는 점 가운데 어느 갈래인지 헷갈린다','알게 됨? 궁금함? 잘함? 고칠 곳?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u2-X40','kor',6,'u2',ARRAY['K6-1-u2-C32']::text[],'친구가 말한 의견은 모두 따라 고쳐야 한다고 여긴다','고르는 것은 글쓴이') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u2-X41','kor',6,'u2',ARRAY['K6-1-u2-C33']::text[],'글을 올린 뒤 확인하지 않거나, 달린 댓글을 읽고 답글을 달거나 다시 점검하지 않고 끝낸다','올리고 → 확인 → 댓글 → 다시 점검') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u2-X42','kor',6,'u2',ARRAY['K6-1-u2-C34']::text[],'맞춤법 검사기나 인공 지능 도구가 고친 곳을 까닭 확인 없이 받아들이거나, 도구가 중심 생각까지 정해 준다고 여긴다','고칠지 말지는 글쓴이가') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u2-X43','kor',6,'u2',ARRAY['K6-1-u2-C35','K6-1-u2-C30']::text[],'보기 좋은 사진 · 영상을 글의 내용과 상관없이 넣는다','내용과 이어지나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u2-X44','kor',6,'u2',ARRAY['K6-1-u2-C37']::text[],'소개하는 글을 자랑하는 글로 여겨 「제일 좋다」처럼 읽는 사람이 그려 볼 수 없는 말을 쓴다','그려 볼 수 있게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u2-X45','kor',6,'u2',ARRAY['K6-1-u2-C36','K6-1-u2-C37']::text[],'소개할 것만의 이야기 없이 누구에게나 있는 말(자전거는 바퀴가 두 개인 탈것)로 소개한다','그것만의 이야기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u2-X46','kor',6,'u2',ARRAY['K6-1-u2-C38']::text[],'주어와 서술어의 짝을 어긋나게 쓴다(내 생각은 판단하면 안 된다 · 화면이 어둠으로 채웠다)','주어에 맞는 서술어') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u2-X47','kor',6,'u2',ARRAY['K6-1-u2-C39']::text[],'스스로 하는 일과 다른 힘에 의해 그리 되는 일의 말을 헷갈린다(내가 창문을 닫혔다 · 바람에 창문이 닫았다)','스스로? 다른 힘?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L01_basic#1','kor',6,1,'u2','L01','g6_1_kor_u2_L01_basic','lesson_basic','K6-1-u2-C1',1,'mc','auto','「고쳐쓰기」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u2-X01']::text[],false,'{"seq":1,"concept":"K6-1-u2-C1","difficulty":1,"kind":"mc","stem":"「고쳐쓰기」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"쓴 글을 점검해 더 잘 전달되도록 손보는 일","correct":true},{"t":"처음 쓴 글을 버리고 처음부터 다시 쓰는 일","mis":"K6-1-u2-X01"},{"t":"글씨를 예쁘게 다시 옮겨 적는 일","mis":"K6-1-u2-X01"},{"t":"친구 글을 그대로 베껴 쓰는 일","mis":"K6-1-u2-X01"}],"explanation":["다시 쓰기나 옮겨 적기가 아니에요.","점검한 내용을 바탕으로 해요.","필요한 곳만 손보아 글을 낫게 만들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L01_basic#2','kor',6,1,'u2','L01','g6_1_kor_u2_L01_basic','lesson_basic','K6-1-u2-C15',1,'mc','auto','「사물함을 정리하면 좋은 점」에서 글의 주제와 어울리지 않는 문장은 어느 것인가요?',ARRAY['K6-1-u2-X15']::text[],false,'{"seq":2,"concept":"K6-1-u2-C15","difficulty":1,"kind":"mc","stem":"「사물함을 정리하면 좋은 점」에서 글의 주제와 어울리지 않는 문장은 어느 것인가요?","options":[{"t":"우리 학교 급식실은 이번 달에 새로 바뀌었습니다.","correct":true},{"t":"종이류를 한곳에 모아 두면 구겨지는 일도 줄어듭니다.","mis":"K6-1-u2-X15"},{"t":"사물함이 어지러우면 필요한 물건을 찾는 데 시간이 오래 걸립니다.","mis":"K6-1-u2-X15"},{"t":"사물함을 자주 비우면 잃어버린 물건도 빨리 찾습니다.","mis":"K6-1-u2-X15"}],"explanation":["글의 주제는 사물함 정리예요.","급식실 이야기는 주제에서 벗어나요.","주제에서 벗어난 문장은 빼요."],"asset":{"type":"passage","lines":["사물함이 어지러우면 필요한 물건을 찾는 데 시간이 오래 걸립니다.","수업이 시작되었는데도 교과서를 못 찾아 허둥대기 쉽습니다.","종이류를 한곳에 모아 두면 구겨지는 일도 줄어듭니다.","우리 학교 급식실은 이번 달에 새로 바뀌었습니다.","사물함을 자주 비우면 잃어버린 물건도 빨리 찾습니다.","그러므로 일주일에 한 번은 사물함을 정리한다."],"title":"설명 글 「사물함을 정리하면 좋은 점」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L01_basic#3','kor',6,1,'u2','L01','g6_1_kor_u2_L01_basic','lesson_basic','K6-1-u2-C2',1,'match','auto','고칠 일과 그에 알맞은 손질을 이으세요.','{}'::text[],false,'{"seq":3,"concept":"K6-1-u2-C2","difficulty":1,"kind":"match","stem":"고칠 일과 그에 알맞은 손질을 이으세요.","pairs":[{"l":"주제에서 벗어난 내용","r":"빼기"},{"l":"부족한 내용","r":"더하기"},{"l":"순서가 뒤엉킨 부분","r":"옮기기"}],"mis":"K6-1-u2-X03","explanation":["벗어난 것은 빼요.","모자란 것은 더해요.","뒤엉킨 것은 옮겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L01_basic#4','kor',6,1,'u2','L01','g6_1_kor_u2_L01_basic','lesson_basic','K6-1-u2-C4',1,'ox','auto','고쳐 쓴 글을 다른 사람과 나누면 내가 못 본 곳을 알게 될 수 있어요.',ARRAY['K6-1-u2-X10']::text[],false,'{"seq":4,"concept":"K6-1-u2-C4","difficulty":1,"kind":"ox","stem":"고쳐 쓴 글을 다른 사람과 나누면 내가 못 본 곳을 알게 될 수 있어요.","answer":"O","reason_options":[{"t":"친구가 내가 놓친 곳을 짚어 주고 읽는 사람의 반응을 알 수 있기 때문에","correct":true},{"t":"나누면 무조건 칭찬을 받기 때문에","mis":"K6-1-u2-X10"}],"mis":"K6-1-u2-X10","explanation":["세아는 못 본 곳을 친구가 짚어 줬어요.","읽는 사람의 반응을 바로 알 수 있어요.","고쳐쓰기에 큰 도움이 돼요."],"asset":{"type":"speech","turns":[{"who":"세아","text":"학급 게시판에 올린 내 글에 댓글이 세 개 달렸어. 내가 못 본 곳을 친구가 짚어 줬어."},{"who":"민석","text":"나도 올려 봤는데, 읽는 사람이 있다고 생각하니까 문장을 더 꼼꼼히 보게 되더라."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L01_basic#5','kor',6,1,'u2','L01','g6_1_kor_u2_L01_basic','lesson_basic','K6-1-u2-C2',2,'mc','auto','「사물함을 정리하면 좋은 점」의 마지막 문장이 어색한 까닭은 무엇인가요?',ARRAY['K6-1-u2-X15','K6-1-u2-X04','K6-1-u2-X11']::text[],false,'{"seq":5,"concept":"K6-1-u2-C2","difficulty":2,"kind":"mc","stem":"「사물함을 정리하면 좋은 점」의 마지막 문장이 어색한 까닭은 무엇인가요?","options":[{"t":"앞 문장들은 「~습니다」로 썼는데 마지막만 「정리한다」로 말투가 어긋나서","correct":true},{"t":"사물함 이야기가 아니어서","mis":"K6-1-u2-X15"},{"t":"문장이 너무 짧아서","mis":"K6-1-u2-X04"},{"t":"제목과 같은 낱말을 써서","mis":"K6-1-u2-X11"}],"explanation":["마지막 문장도 사물함 이야기예요.","말투가 앞 문장들과 달라요.","「정리합시다」처럼 말투를 맞춰요."],"asset":{"type":"passage","lines":["사물함이 어지러우면 필요한 물건을 찾는 데 시간이 오래 걸립니다.","수업이 시작되었는데도 교과서를 못 찾아 허둥대기 쉽습니다.","종이류를 한곳에 모아 두면 구겨지는 일도 줄어듭니다.","우리 학교 급식실은 이번 달에 새로 바뀌었습니다.","사물함을 자주 비우면 잃어버린 물건도 빨리 찾습니다.","그러므로 일주일에 한 번은 사물함을 정리한다."],"title":"설명 글 「사물함을 정리하면 좋은 점」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L01_basic#6','kor',6,1,'u2','L01','g6_1_kor_u2_L01_basic','lesson_basic','K6-1-u2-C3',2,'match','auto','살필 내용과 수준을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K6-1-u2-C3","difficulty":2,"kind":"match","stem":"살필 내용과 수준을 알맞게 이으세요.","pairs":[{"l":"제목이 내용을 잘 나타내는가","r":"글 수준"},{"l":"뒷받침 문장이 중심 문장과 어울리는가","r":"문단 수준"},{"l":"주어와 서술어가 호응하는가","r":"문장 수준"}],"mis":"K6-1-u2-X04","explanation":["제목은 글 전체를 봐야 알아요.","뒷받침 문장은 문단 하나를 보면 알아요.","호응은 한 문장만 봐도 알아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L01_basic#7','kor',6,1,'u2','L01','g6_1_kor_u2_L01_basic','lesson_basic','K6-1-u2-C5',2,'mc','auto','친구 글에 남길 댓글로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u2-X06','K6-1-u2-X07','K6-1-u2-X08']::text[],false,'{"seq":7,"concept":"K6-1-u2-C5","difficulty":2,"kind":"mc","stem":"친구 글에 남길 댓글로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「첫 문단이 눈에 잘 들어왔어. 셋째 문장은 주제와 조금 멀어 보여.」","correct":true},{"t":"「무슨 말인지 하나도 모르겠어. 다시 써.」","mis":"K6-1-u2-X06"},{"t":"「그냥 다 좋아. 고칠 곳이 하나도 없어.」","mis":"K6-1-u2-X07"},{"t":"「셋째 문장 고쳐.」","mis":"K6-1-u2-X08"}],"explanation":["다시 쓰라는 말은 글쓴이를 위축시켜요.","막연한 칭찬은 쓸모가 적어요.","잘한 곳을 먼저, 고칠 곳은 까닭과 함께 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L01_basic#8','kor',6,1,'u2','L01','g6_1_kor_u2_L01_basic','lesson_basic','K6-1-u2-C6',2,'ox','auto','온라인 게시판에 글을 올릴 때에는 줄임말이나 은어를 써도 괜찮아요.',ARRAY['K6-1-u2-X09']::text[],false,'{"seq":8,"concept":"K6-1-u2-C6","difficulty":2,"kind":"ox","stem":"온라인 게시판에 글을 올릴 때에는 줄임말이나 은어를 써도 괜찮아요.","answer":"X","reason_options":[{"t":"한 번 올린 글은 널리 퍼지고 읽는 사람이 여럿이기 때문에","correct":true},{"t":"친구끼리는 줄임말이 더 빨리 통하기 때문에","mis":"K6-1-u2-X09"}],"mis":"K6-1-u2-X09","explanation":["올린 글은 여러 사람이 읽어요.","한 번 올리면 널리 퍼져요.","줄임말 · 은어 · 비속어를 쓰지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L01_basic#9','kor',6,1,'u2','L01','g6_1_kor_u2_L01_basic','lesson_basic','K6-1-u2-C3',2,'mc','auto','고쳐 쓸 때 살피는 차례로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u2-X05','K6-1-u2-X04']::text[],false,'{"seq":9,"concept":"K6-1-u2-C3","difficulty":2,"kind":"mc","stem":"고쳐 쓸 때 살피는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"글 → 문단 → 문장","correct":true},{"t":"문장 → 문단 → 글","mis":"K6-1-u2-X05"},{"t":"띄어쓰기 → 글씨 → 제목","mis":"K6-1-u2-X05"},{"t":"문단 → 글 → 문장","mis":"K6-1-u2-X04"}],"explanation":["큰 것부터 봐요.","작은 것부터 고치면 헛수고가 생겨요.","글 → 문단 → 문장 차례예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L01_basic#10','kor',6,1,'u2','L01','g6_1_kor_u2_L01_basic','lesson_basic','K6-1-u2-C7',3,'mc','auto','「고쳐 쓰라는 말은 내 글이 잘못됐다는 뜻이야.」라고 생각하는 친구에게 해 줄 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u2-X02','K6-1-u2-X01']::text[],false,'{"seq":10,"concept":"K6-1-u2-C7","difficulty":3,"kind":"mc","stem":"「고쳐 쓰라는 말은 내 글이 잘못됐다는 뜻이야.」라고 생각하는 친구에게 해 줄 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「여기만 손보면 네가 하고 싶은 말이 더 잘 전해진다는 뜻이야. 작게 고친 것도 잘 고친 거야.」","correct":true},{"t":"「맞아, 그러니까 글을 통째로 다시 써.」","mis":"K6-1-u2-X02"},{"t":"「고칠 곳이 있으면 처음부터 새로 쓰는 게 빨라.」","mis":"K6-1-u2-X01"},{"t":"「완벽하게 고치지 못할 거면 손대지 마.」","mis":"K6-1-u2-X02"}],"explanation":["고쳐쓰기는 혼나는 일이 아니에요.","다시 쓰기가 아니에요.","필요한 곳만 손봐도 글이 나아져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L01_challenge#1','kor',6,1,'u2','L01','g6_1_kor_u2_L01_challenge','lesson_challenge','K6-1-u2-C2',2,'mc','auto','「사물함을 정리하면 좋은 점」에서 급식실 문장에 해야 할 손질은 무엇인가요?',ARRAY['K6-1-u2-X03','K6-1-u2-X01']::text[],false,'{"seq":1,"concept":"K6-1-u2-C2","difficulty":2,"kind":"mc","stem":"「사물함을 정리하면 좋은 점」에서 급식실 문장에 해야 할 손질은 무엇인가요?","options":[{"t":"빼기","correct":true},{"t":"더하기","mis":"K6-1-u2-X03"},{"t":"옮기기","mis":"K6-1-u2-X03"},{"t":"글씨 다시 쓰기","mis":"K6-1-u2-X01"}],"explanation":["급식실 문장은 주제와 상관없어요.","옮겨도 주제와 맞지 않아요.","주제에서 벗어난 내용은 빼요."],"asset":{"type":"passage","lines":["사물함이 어지러우면 필요한 물건을 찾는 데 시간이 오래 걸립니다.","수업이 시작되었는데도 교과서를 못 찾아 허둥대기 쉽습니다.","종이류를 한곳에 모아 두면 구겨지는 일도 줄어듭니다.","우리 학교 급식실은 이번 달에 새로 바뀌었습니다.","사물함을 자주 비우면 잃어버린 물건도 빨리 찾습니다.","그러므로 일주일에 한 번은 사물함을 정리한다."],"title":"설명 글 「사물함을 정리하면 좋은 점」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L01_challenge#2','kor',6,1,'u2','L01','g6_1_kor_u2_L01_challenge','lesson_challenge','K6-1-u2-C1',2,'ox','auto','고쳐쓰기를 할 때에는 처음 쓴 글을 버리고 처음부터 새로 써야 해요.',ARRAY['K6-1-u2-X01']::text[],false,'{"seq":2,"concept":"K6-1-u2-C1","difficulty":2,"kind":"ox","stem":"고쳐쓰기를 할 때에는 처음 쓴 글을 버리고 처음부터 새로 써야 해요.","answer":"X","reason_options":[{"t":"고쳐쓰기는 점검한 내용을 바탕으로 필요한 곳만 손보는 일이기 때문에","correct":true},{"t":"처음 쓴 글에는 좋은 곳이 하나도 없기 때문에","mis":"K6-1-u2-X01"}],"mis":"K6-1-u2-X01","explanation":["고쳐쓰기는 다시 쓰기가 아니에요.","처음 쓴 글에도 살릴 곳이 있어요.","필요한 곳만 손봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L01_challenge#3','kor',6,1,'u2','L01','g6_1_kor_u2_L01_challenge','lesson_challenge','K6-1-u2-C3',3,'error','auto','고쳐 쓸 때 살피는 수준을 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-1-u2-X04']::text[],false,'{"seq":3,"concept":"K6-1-u2-C3","difficulty":3,"kind":"error","stem":"고쳐 쓸 때 살피는 수준을 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"규리 — 「제목이 내용과 어울리는지는 한 문장만 보면 알 수 있어.」","correct":true,"mis_target":"K6-1-u2-X04"},{"t":"하율 — 「처음 · 가운데 · 끝의 흐름은 글 전체를 봐야 해.」","mis":"K6-1-u2-X04"},{"t":"서진 — 「띄어쓰기는 문장 수준에서 살펴.」","mis":"K6-1-u2-X04"}],"explanation":["하율과 서진은 바르게 말했어요.","제목과 내용은 글 전체를 봐야 알아요.","규리는 글 수준의 일을 문장 수준으로 보았어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L01_challenge#4','kor',6,1,'u2','L01','g6_1_kor_u2_L01_challenge','lesson_challenge','K6-1-u2-C4',3,'mc','auto','민석이가 「읽는 사람이 있다고 생각하니까 문장을 더 꼼꼼히 보게 되더라.」라고 한 말에서 알 수 있는 것은 무엇인가요?',ARRAY['K6-1-u2-X10','K6-1-u2-X05']::text[],false,'{"seq":4,"concept":"K6-1-u2-C4","difficulty":3,"kind":"mc","stem":"민석이가 「읽는 사람이 있다고 생각하니까 문장을 더 꼼꼼히 보게 되더라.」라고 한 말에서 알 수 있는 것은 무엇인가요?","options":[{"t":"글을 나누면 읽는 사람을 떠올리게 되어 고쳐쓰기에 도움이 된다","correct":true},{"t":"글을 나누면 더 고치지 않아도 된다","mis":"K6-1-u2-X10"},{"t":"글을 나누는 것은 칭찬을 받으려는 것이다","mis":"K6-1-u2-X10"},{"t":"읽는 사람이 없으면 띄어쓰기만 보면 된다","mis":"K6-1-u2-X05"}],"explanation":["읽는 사람을 떠올리면 문장을 더 꼼꼼히 봐요.","나눈 뒤에도 다시 점검해요.","나누는 것은 고쳐쓰기를 돕는 일이에요."],"asset":{"type":"speech","turns":[{"who":"세아","text":"학급 게시판에 올린 내 글에 댓글이 세 개 달렸어. 내가 못 본 곳을 친구가 짚어 줬어."},{"who":"민석","text":"나도 올려 봤는데, 읽는 사람이 있다고 생각하니까 문장을 더 꼼꼼히 보게 되더라."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L01_challenge#5','kor',6,1,'u2','L01','g6_1_kor_u2_L01_challenge','lesson_challenge','K6-1-u2-C5',3,'mc','auto','같은 내용이라도 댓글의 말하는 방식이 중요한 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u2-X06','K6-1-u2-X07','K6-1-u2-X08']::text[],false,'{"seq":5,"concept":"K6-1-u2-C5","difficulty":3,"kind":"mc","stem":"같은 내용이라도 댓글의 말하는 방식이 중요한 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"말하는 방식에 따라 글쓴이가 다시 고쳐 쓰고 싶어질 수도, 쓰기 싫어질 수도 있기 때문에","correct":true},{"t":"고칠 곳은 많이 늘어놓을수록 도움이 되기 때문에","mis":"K6-1-u2-X06"},{"t":"칭찬만 하면 글쓴이가 기뻐하기 때문에","mis":"K6-1-u2-X07"},{"t":"까닭은 말하지 않아도 글쓴이가 알기 때문에","mis":"K6-1-u2-X08"}],"explanation":["고칠 곳만 늘어놓으면 위축돼요.","막연한 칭찬은 도움이 적어요.","방식에 따라 다시 쓰고 싶은 마음이 달라져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L01_challenge#6','kor',6,1,'u2','L01','g6_1_kor_u2_L01_challenge','lesson_challenge','K6-1-u2-C6',3,'match','auto','온라인에 글을 올릴 때의 일과 알맞은 것을 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K6-1-u2-C6","difficulty":3,"kind":"match","stem":"온라인에 글을 올릴 때의 일과 알맞은 것을 이으세요.","pairs":[{"l":"여러 사람이 읽고 의견을 준다","r":"좋은 점"},{"l":"한 번 올린 글은 널리 퍼진다","r":"주의할 점"},{"l":"자료를 옮길 때 출처를 밝힌다","r":"지킬 것"}],"mis":"K6-1-u2-X09","explanation":["의견을 받을 수 있는 것은 좋은 점이에요.","널리 퍼지는 것은 주의할 점이에요.","출처를 밝히는 것은 지킬 것이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L01_challenge#7','kor',6,1,'u2','L01','g6_1_kor_u2_L01_challenge','lesson_challenge','K6-1-u2-C7',3,'mc','auto','세 군데만 고쳤는데 「이 정도로는 소용없어.」라고 말하는 친구에게 알맞은 생각은 어느 것인가요?',ARRAY['K6-1-u2-X02','K6-1-u2-X01','K6-1-u2-X10']::text[],false,'{"seq":7,"concept":"K6-1-u2-C7","difficulty":3,"kind":"mc","stem":"세 군데만 고쳤는데 「이 정도로는 소용없어.」라고 말하는 친구에게 알맞은 생각은 어느 것인가요?","options":[{"t":"한 군데를 고쳤으면 그만큼 나아진 것이다","correct":true},{"t":"완벽하게 고치지 않으면 고친 것이 아니다","mis":"K6-1-u2-X02"},{"t":"다 지우고 처음부터 다시 써야 한다","mis":"K6-1-u2-X01"},{"t":"고칠 곳이 있으면 글을 올리지 않는다","mis":"K6-1-u2-X10"}],"explanation":["완벽한 글을 만드는 일이 아니에요.","작게 고친 것도 잘 고친 것이에요.","고친 만큼 글이 나아져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L01_challenge#8','kor',6,1,'u2','L01','g6_1_kor_u2_L01_challenge','lesson_challenge','K6-1-u2-C2',4,'mc','auto','「사물함을 정리하면 좋은 점」을 고칠 계획으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u2-X01','K6-1-u2-X03','K6-1-u2-X15']::text[],false,'{"seq":8,"concept":"K6-1-u2-C2","difficulty":4,"kind":"mc","stem":"「사물함을 정리하면 좋은 점」을 고칠 계획으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"급식실 문장은 빼고, 마지막 문장은 「정리합시다」로 바꾸어 말투를 맞춘다","correct":true},{"t":"글 전체를 지우고 다른 주제로 새로 쓴다","mis":"K6-1-u2-X01"},{"t":"급식실 문장을 맨 앞으로 옮긴다","mis":"K6-1-u2-X03"},{"t":"모든 문장을 「~한다」로 바꾸고 급식실 문장도 그대로 둔다","mis":"K6-1-u2-X15"}],"explanation":["필요한 곳만 손봐요.","벗어난 문장은 옮기지 않고 빼요.","어색한 말투는 바꾸어 맞춰요."],"asset":{"type":"passage","lines":["사물함이 어지러우면 필요한 물건을 찾는 데 시간이 오래 걸립니다.","수업이 시작되었는데도 교과서를 못 찾아 허둥대기 쉽습니다.","종이류를 한곳에 모아 두면 구겨지는 일도 줄어듭니다.","우리 학교 급식실은 이번 달에 새로 바뀌었습니다.","사물함을 자주 비우면 잃어버린 물건도 빨리 찾습니다.","그러므로 일주일에 한 번은 사물함을 정리한다."],"title":"설명 글 「사물함을 정리하면 좋은 점」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L01_challenge#9','kor',6,1,'u2','L01','g6_1_kor_u2_L01_challenge','lesson_challenge','K6-1-u2-C1',4,'essay','teacher','「고쳐쓰기」가 무엇인지 내 말로 설명하고, 고쳐쓰기가 「다시 쓰기」와 어떻게 다른지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-1-u2-C1","difficulty":4,"kind":"essay","stem":"「고쳐쓰기」가 무엇인지 내 말로 설명하고, 고쳐쓰기가 「다시 쓰기」와 어떻게 다른지 쓰세요.","answer_guide":{"answer":"예: 고쳐쓰기는 쓴 글을 다시 읽고 점검해서 하고 싶은 말이 더 잘 전해지도록 필요한 곳만 손보는 일이다. 주제에서 벗어난 것은 빼고, 부족한 것은 더하고, 어색한 표현은 바꾸고, 뒤엉킨 순서는 옮긴다. 다시 쓰기는 처음 쓴 글을 버리고 처음부터 새로 쓰는 것이지만 고쳐쓰기는 처음 쓴 글을 살리면서 고칠 곳만 손본다는 점이 다르다.","scoring_points":["고쳐쓰기를 점검해 필요한 곳만 손보는 일로 설명했는가","빼기 · 더하기 · 바꾸기 · 옮기기 가운데 한 가지 이상을 들었는가","다시 쓰기와의 차이를 썼는가"]},"explanation":["점검하고 손보는 일이에요.","네 가지 손질을 떠올려요.","처음 쓴 글을 살린다는 점이 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L01_challenge#10','kor',6,1,'u2','L01','g6_1_kor_u2_L01_challenge','lesson_challenge','K6-1-u2-C5',4,'essay','teacher','친구가 쓴 글에 고칠 곳이 보였어요. 친구가 다시 고쳐 쓰고 싶어지도록 댓글을 쓰고, 왜 그렇게 썼는지 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-1-u2-C5","difficulty":4,"kind":"essay","stem":"친구가 쓴 글에 고칠 곳이 보였어요. 친구가 다시 고쳐 쓰고 싶어지도록 댓글을 쓰고, 왜 그렇게 썼는지 까닭을 쓰세요.","answer_guide":{"answer":"예: 댓글 — 「사물함이 어지러울 때 생기는 일을 예로 들어서 바로 이해가 됐어. 급식실이 바뀌었다는 문장은 사물함 이야기와 멀어 보여서 빼면 더 좋겠어.」 까닭 — 잘한 곳을 먼저 말해야 글쓴이가 위축되지 않고, 고칠 곳은 까닭을 함께 말해야 어디를 왜 고칠지 알 수 있기 때문이다.","scoring_points":["잘한 곳을 먼저 말했는가","고칠 곳을 까닭과 함께 말했는가","그렇게 쓴 까닭을 썼는가"]},"explanation":["잘한 곳부터 짚어요.","고칠 곳은 까닭과 함께 말해요.","글쓴이의 마음을 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L02_basic#1','kor',6,1,'u2','L02','g6_1_kor_u2_L02_basic','lesson_basic','K6-1-u2-C8',1,'mc','auto','해준의 감상문에 어울리는 제목으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u2-X11','K6-1-u2-X15']::text[],false,'{"seq":1,"concept":"K6-1-u2-C8","difficulty":1,"kind":"mc","stem":"해준의 감상문에 어울리는 제목으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"무너져도 다시 손을 대는 힘","correct":true},{"t":"바닷가 여름 풍경 소개","mis":"K6-1-u2-X11"},{"t":"모래를 좋아하는 우리 집 강아지","mis":"K6-1-u2-X15"},{"t":"모래성 이야기 줄거리","mis":"K6-1-u2-X11"}],"explanation":["라 문단에서 새로 생각하게 된 것을 봐요.","줄거리나 풍경만 알리는 제목은 부족해요.","글쓴이가 느낀 것이 드러나야 해요."],"asset":{"type":"passage","lines":["가 가장 마음에 남은 곳은 마지막 장면이다. 큰 파도에 성이 무너뜨렸는데도","미르는 울지 않고 젖은 모래를 다시 끌어모은다. 나는 그 장면에서 전혀 지루했다.","나 미르는 여름 내내 쌓았다. 저녁마다 파도가 성을 지웠지만 다음 날 다시 시작했다.","새봄과 함께 물길을 파서 성을 사흘 동안 지켜 내기도 한다. 우리 집 강아지도 모래를 좋아한다.","다 선생님이 이 영화를 우리 반에 소개했다. 제목만 보고는 바다 풍경만 나오는","줄 알았는데, 무엇을 다시 시작하는 사람의 이야기였다.","라 나는 실패한 일을 다시 붙잡는 일이 어렵다고 생각해 왔다. 이 영화를 보고","다시 손을 대는 것도 하나의 힘이라고 생각하게 되었다. 나도 미르처럼 되고 싶다."],"title":"해준이 쓴 감상문 「모래성 이야기」 (가~라는 문단)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L02_basic#2','kor',6,1,'u2','L02','g6_1_kor_u2_L02_basic','lesson_basic','K6-1-u2-C11',1,'mc','auto','문단에서 하고 싶은 말을 담은 문장을 무엇이라고 하나요?',ARRAY['K6-1-u2-X14','K6-1-u2-X11']::text[],false,'{"seq":2,"concept":"K6-1-u2-C11","difficulty":1,"kind":"mc","stem":"문단에서 하고 싶은 말을 담은 문장을 무엇이라고 하나요?","options":[{"t":"중심 문장","correct":true},{"t":"뒷받침 문장","mis":"K6-1-u2-X14"},{"t":"제목","mis":"K6-1-u2-X11"},{"t":"끝 문장","mis":"K6-1-u2-X14"}],"explanation":["문단에는 하고 싶은 말이 있어요.","그 말을 담은 문장이 중심 문장이에요.","뒷받침 문장은 그것을 자세히 설명해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L02_basic#3','kor',6,1,'u2','L02','g6_1_kor_u2_L02_basic','lesson_basic','K6-1-u2-C15',1,'mc','auto','해준의 감상문 나 문단에서 빼야 할 문장은 어느 것인가요?',ARRAY['K6-1-u2-X15','K6-1-u2-X16']::text[],false,'{"seq":3,"concept":"K6-1-u2-C15","difficulty":1,"kind":"mc","stem":"해준의 감상문 나 문단에서 빼야 할 문장은 어느 것인가요?","options":[{"t":"우리 집 강아지도 모래를 좋아한다.","correct":true},{"t":"저녁마다 파도가 성을 지웠다.","mis":"K6-1-u2-X15"},{"t":"새봄과 함께 물길을 파서 성을 사흘 동안 지켜 내기도 한다.","mis":"K6-1-u2-X15"},{"t":"미르는 여름 내내 쌓았다.","mis":"K6-1-u2-X16"}],"explanation":["나 문단의 중심은 미르가 모래성을 쌓은 일이에요.","강아지 이야기는 상관이 없어요.","「여름 내내 쌓았다」는 지우지 말고 고쳐요."],"asset":{"type":"passage","lines":["가 가장 마음에 남은 곳은 마지막 장면이다. 큰 파도에 성이 무너뜨렸는데도","미르는 울지 않고 젖은 모래를 다시 끌어모은다. 나는 그 장면에서 전혀 지루했다.","나 미르는 여름 내내 쌓았다. 저녁마다 파도가 성을 지웠지만 다음 날 다시 시작했다.","새봄과 함께 물길을 파서 성을 사흘 동안 지켜 내기도 한다. 우리 집 강아지도 모래를 좋아한다.","다 선생님이 이 영화를 우리 반에 소개했다. 제목만 보고는 바다 풍경만 나오는","줄 알았는데, 무엇을 다시 시작하는 사람의 이야기였다.","라 나는 실패한 일을 다시 붙잡는 일이 어렵다고 생각해 왔다. 이 영화를 보고","다시 손을 대는 것도 하나의 힘이라고 생각하게 되었다. 나도 미르처럼 되고 싶다."],"title":"해준이 쓴 감상문 「모래성 이야기」 (가~라는 문단)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L02_basic#4','kor',6,1,'u2','L02','g6_1_kor_u2_L02_basic','lesson_basic','K6-1-u2-C13',1,'match','auto','문장 성분과 그 물음을 이으세요.','{}'::text[],false,'{"seq":4,"concept":"K6-1-u2-C13","difficulty":1,"kind":"match","stem":"문장 성분과 그 물음을 이으세요.","pairs":[{"l":"주어","r":"무엇이 · 누가"},{"l":"목적어","r":"무엇을 · 누구를"},{"l":"서술어","r":"어찌하다 · 어떠하다"}],"mis":"K6-1-u2-X17","explanation":["주어는 누가 · 무엇이에요.","목적어는 무엇을 · 누구를이에요.","서술어는 어찌하다 · 어떠하다예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L02_basic#5','kor',6,1,'u2','L02','g6_1_kor_u2_L02_basic','lesson_basic','K6-1-u2-C9',2,'match','auto','해준의 감상문 문단이 놓일 차례를 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K6-1-u2-C9","difficulty":2,"kind":"match","stem":"해준의 감상문 문단이 놓일 차례를 이으세요.","pairs":[{"l":"다 — 영화를 보게 된 동기와 첫인상","r":"처음"},{"l":"가 — 인상 깊은 장면","r":"가운데"},{"l":"라 — 느낀 점과 다짐","r":"끝"}],"mis":"K6-1-u2-X12","explanation":["보게 된 동기는 처음에 와요.","인상 깊은 장면은 가운데에 와요.","다짐은 끝에 와요."],"asset":{"type":"passage","lines":["가 가장 마음에 남은 곳은 마지막 장면이다. 큰 파도에 성이 무너뜨렸는데도","미르는 울지 않고 젖은 모래를 다시 끌어모은다. 나는 그 장면에서 전혀 지루했다.","나 미르는 여름 내내 쌓았다. 저녁마다 파도가 성을 지웠지만 다음 날 다시 시작했다.","새봄과 함께 물길을 파서 성을 사흘 동안 지켜 내기도 한다. 우리 집 강아지도 모래를 좋아한다.","다 선생님이 이 영화를 우리 반에 소개했다. 제목만 보고는 바다 풍경만 나오는","줄 알았는데, 무엇을 다시 시작하는 사람의 이야기였다.","라 나는 실패한 일을 다시 붙잡는 일이 어렵다고 생각해 왔다. 이 영화를 보고","다시 손을 대는 것도 하나의 힘이라고 생각하게 되었다. 나도 미르처럼 되고 싶다."],"title":"해준이 쓴 감상문 「모래성 이야기」 (가~라는 문단)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L02_basic#6','kor',6,1,'u2','L02','g6_1_kor_u2_L02_basic','lesson_basic','K6-1-u2-C14',2,'mc','auto','「선생님이 이 영화를 우리 반에 소개했다.」를 바르게 고친 것은 어느 것인가요?',ARRAY['K6-1-u2-X20','K6-1-u2-X17','K6-1-u2-X19']::text[],false,'{"seq":6,"concept":"K6-1-u2-C14","difficulty":2,"kind":"mc","stem":"「선생님이 이 영화를 우리 반에 소개했다.」를 바르게 고친 것은 어느 것인가요?","options":[{"t":"선생님께서 이 영화를 우리 반에 소개해 주셨다.","correct":true},{"t":"선생님이 이 영화를 우리 반에 소개한다.","mis":"K6-1-u2-X20"},{"t":"선생님을 이 영화가 우리 반에 소개했다.","mis":"K6-1-u2-X17"},{"t":"선생님이 이 영화를 우리 반에 소개될 것이다.","mis":"K6-1-u2-X19"}],"explanation":["선생님은 웃어른이에요.","높임 표현으로 받아야 해요.","께서 · ~시다로 고쳐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L02_basic#7','kor',6,1,'u2','L02','g6_1_kor_u2_L02_basic','lesson_basic','K6-1-u2-C14',2,'mc','auto','「큰 파도에 성이 무너뜨렸는데도」에서 어긋난 것은 무엇인가요?',ARRAY['K6-1-u2-X17','K6-1-u2-X18','K6-1-u2-X20']::text[],false,'{"seq":7,"concept":"K6-1-u2-C14","difficulty":2,"kind":"mc","stem":"「큰 파도에 성이 무너뜨렸는데도」에서 어긋난 것은 무엇인가요?","options":[{"t":"성이 스스로 한 일이 아니므로 「무너졌는데도」로 써야 한다","correct":true},{"t":"「큰 파도에」를 빼야 한다","mis":"K6-1-u2-X17"},{"t":"높임 표현을 써야 한다","mis":"K6-1-u2-X18"},{"t":"시간을 나타내는 말이 없다","mis":"K6-1-u2-X20"}],"explanation":["성은 파도 때문에 무너졌어요.","스스로 무너뜨린 것이 아니에요.","「무너졌는데도」로 고쳐요."],"asset":{"type":"passage","lines":["가 가장 마음에 남은 곳은 마지막 장면이다. 큰 파도에 성이 무너뜨렸는데도","미르는 울지 않고 젖은 모래를 다시 끌어모은다. 나는 그 장면에서 전혀 지루했다.","나 미르는 여름 내내 쌓았다. 저녁마다 파도가 성을 지웠지만 다음 날 다시 시작했다.","새봄과 함께 물길을 파서 성을 사흘 동안 지켜 내기도 한다. 우리 집 강아지도 모래를 좋아한다.","다 선생님이 이 영화를 우리 반에 소개했다. 제목만 보고는 바다 풍경만 나오는","줄 알았는데, 무엇을 다시 시작하는 사람의 이야기였다.","라 나는 실패한 일을 다시 붙잡는 일이 어렵다고 생각해 왔다. 이 영화를 보고","다시 손을 대는 것도 하나의 힘이라고 생각하게 되었다. 나도 미르처럼 되고 싶다."],"title":"해준이 쓴 감상문 「모래성 이야기」 (가~라는 문단)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L02_basic#8','kor',6,1,'u2','L02','g6_1_kor_u2_L02_basic','lesson_basic','K6-1-u2-C13',2,'ox','auto','내용이 좋으면 문장 성분의 호응이 조금 어긋나도 뜻은 제대로 전해져요.',ARRAY['K6-1-u2-X17']::text[],false,'{"seq":8,"concept":"K6-1-u2-C13","difficulty":2,"kind":"ox","stem":"내용이 좋으면 문장 성분의 호응이 조금 어긋나도 뜻은 제대로 전해져요.","answer":"X","reason_options":[{"t":"호응이 어긋나면 읽는 사람이 뜻을 제대로 알기 어렵기 때문에","correct":true},{"t":"내용이 형식보다 언제나 중요하기 때문에","mis":"K6-1-u2-X17"}],"mis":"K6-1-u2-X17","explanation":["호응은 형식의 문제예요.","형식이 어긋나면 뜻도 흐려져요.","내용과 형식을 함께 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L02_basic#9','kor',6,1,'u2','L02','g6_1_kor_u2_L02_basic','lesson_basic','K6-1-u2-C10',2,'ox','auto','세아와 민석이가 말한 중심 내용이 서로 다르면 둘 가운데 하나는 틀린 답이에요.',ARRAY['K6-1-u2-X13']::text[],false,'{"seq":9,"concept":"K6-1-u2-C10","difficulty":2,"kind":"ox","stem":"세아와 민석이가 말한 중심 내용이 서로 다르면 둘 가운데 하나는 틀린 답이에요.","answer":"X","reason_options":[{"t":"두 답 모두 글에서 근거를 댈 수 있으면 둘 다 좋은 답이기 때문에","correct":true},{"t":"중심 내용은 언제나 하나뿐이기 때문에","mis":"K6-1-u2-X13"}],"mis":"K6-1-u2-X13","explanation":["세아는 마지막 문단에서 근거를 찾았어요.","민석이는 사흘을 버틴 장면에서 찾았어요.","근거가 있으면 둘 다 좋은 답이에요."],"asset":{"type":"speech","turns":[{"who":"세아","text":"이 글의 중심 내용은 「다시 시작하는 힘」이라고 봤어. 마지막 문단에 그렇게 적혀 있잖아."},{"who":"민석","text":"나는 「함께하면 더 오래 버틴다」로 봤어. 새봄과 물길을 판 뒤에 사흘을 버텼다고 나오니까."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L02_basic#10','kor',6,1,'u2','L02','g6_1_kor_u2_L02_basic','lesson_basic','K6-1-u2-C14',3,'mc','auto','「나는 그 장면에서 전혀 지루했다.」를 바르게 고친 것은 어느 것인가요?',ARRAY['K6-1-u2-X20','K6-1-u2-X21','K6-1-u2-X34']::text[],false,'{"seq":10,"concept":"K6-1-u2-C14","difficulty":3,"kind":"mc","stem":"「나는 그 장면에서 전혀 지루했다.」를 바르게 고친 것은 어느 것인가요?","options":[{"t":"나는 그 장면에서 전혀 지루하지 않았다.","correct":true},{"t":"나는 그 장면에서 전혀 지루할 것이다.","mis":"K6-1-u2-X20"},{"t":"나는 그 장면에서 전혀 재미있었다.","mis":"K6-1-u2-X21"},{"t":"그 장면에서 전혀 지루했다.","mis":"K6-1-u2-X34"}],"explanation":["「전혀」 뒤에는 부정하는 말이 와요.","때나 낱말만 바꾸어도 어긋남은 그대로예요.","「지루하지 않았다」로 고쳐요."],"asset":{"type":"passage","lines":["가 가장 마음에 남은 곳은 마지막 장면이다. 큰 파도에 성이 무너뜨렸는데도","미르는 울지 않고 젖은 모래를 다시 끌어모은다. 나는 그 장면에서 전혀 지루했다.","나 미르는 여름 내내 쌓았다. 저녁마다 파도가 성을 지웠지만 다음 날 다시 시작했다.","새봄과 함께 물길을 파서 성을 사흘 동안 지켜 내기도 한다. 우리 집 강아지도 모래를 좋아한다.","다 선생님이 이 영화를 우리 반에 소개했다. 제목만 보고는 바다 풍경만 나오는","줄 알았는데, 무엇을 다시 시작하는 사람의 이야기였다.","라 나는 실패한 일을 다시 붙잡는 일이 어렵다고 생각해 왔다. 이 영화를 보고","다시 손을 대는 것도 하나의 힘이라고 생각하게 되었다. 나도 미르처럼 되고 싶다."],"title":"해준이 쓴 감상문 「모래성 이야기」 (가~라는 문단)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L02_challenge#1','kor',6,1,'u2','L02','g6_1_kor_u2_L02_challenge','lesson_challenge','K6-1-u2-C4',2,'mc','auto','해준의 감상문에서 「문단의 차례가 뒤엉켰다」는 문제는 어느 수준에서 찾을 수 있나요?',ARRAY['K6-1-u2-X04','K6-1-u2-X05']::text[],false,'{"seq":1,"concept":"K6-1-u2-C4","difficulty":2,"kind":"mc","stem":"해준의 감상문에서 「문단의 차례가 뒤엉켰다」는 문제는 어느 수준에서 찾을 수 있나요?","options":[{"t":"글 수준","correct":true},{"t":"문장 수준","mis":"K6-1-u2-X04"},{"t":"띄어쓰기 수준","mis":"K6-1-u2-X05"},{"t":"낱말 수준","mis":"K6-1-u2-X04"}],"explanation":["차례는 글 전체를 봐야 보여요.","한 문장만 봐서는 알 수 없어요.","글 수준의 문제예요."],"asset":{"type":"passage","lines":["가 가장 마음에 남은 곳은 마지막 장면이다. 큰 파도에 성이 무너뜨렸는데도","미르는 울지 않고 젖은 모래를 다시 끌어모은다. 나는 그 장면에서 전혀 지루했다.","나 미르는 여름 내내 쌓았다. 저녁마다 파도가 성을 지웠지만 다음 날 다시 시작했다.","새봄과 함께 물길을 파서 성을 사흘 동안 지켜 내기도 한다. 우리 집 강아지도 모래를 좋아한다.","다 선생님이 이 영화를 우리 반에 소개했다. 제목만 보고는 바다 풍경만 나오는","줄 알았는데, 무엇을 다시 시작하는 사람의 이야기였다.","라 나는 실패한 일을 다시 붙잡는 일이 어렵다고 생각해 왔다. 이 영화를 보고","다시 손을 대는 것도 하나의 힘이라고 생각하게 되었다. 나도 미르처럼 되고 싶다."],"title":"해준이 쓴 감상문 「모래성 이야기」 (가~라는 문단)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L02_challenge#2','kor',6,1,'u2','L02','g6_1_kor_u2_L02_challenge','lesson_challenge','K6-1-u2-C12',2,'mc','auto','「미르는 여름 내내 쌓았다.」는 어떻게 하는 것이 알맞은가요?',ARRAY['K6-1-u2-X16','K6-1-u2-X03','K6-1-u2-X34']::text[],false,'{"seq":2,"concept":"K6-1-u2-C12","difficulty":2,"kind":"mc","stem":"「미르는 여름 내내 쌓았다.」는 어떻게 하는 것이 알맞은가요?","options":[{"t":"「미르는 여름 내내 모래성을 쌓았다.」로 고쳐 쓴다","correct":true},{"t":"중심 문장과 상관없으니 지운다","mis":"K6-1-u2-X16"},{"t":"문단 맨 끝으로 옮긴다","mis":"K6-1-u2-X03"},{"t":"그대로 둔다","mis":"K6-1-u2-X34"}],"explanation":["미르가 모래성을 쌓은 일은 중심과 관련이 있어요.","무엇을 쌓았는지가 빠졌어요.","지우지 말고 고쳐 써요."],"asset":{"type":"passage","lines":["가 가장 마음에 남은 곳은 마지막 장면이다. 큰 파도에 성이 무너뜨렸는데도","미르는 울지 않고 젖은 모래를 다시 끌어모은다. 나는 그 장면에서 전혀 지루했다.","나 미르는 여름 내내 쌓았다. 저녁마다 파도가 성을 지웠지만 다음 날 다시 시작했다.","새봄과 함께 물길을 파서 성을 사흘 동안 지켜 내기도 한다. 우리 집 강아지도 모래를 좋아한다.","다 선생님이 이 영화를 우리 반에 소개했다. 제목만 보고는 바다 풍경만 나오는","줄 알았는데, 무엇을 다시 시작하는 사람의 이야기였다.","라 나는 실패한 일을 다시 붙잡는 일이 어렵다고 생각해 왔다. 이 영화를 보고","다시 손을 대는 것도 하나의 힘이라고 생각하게 되었다. 나도 미르처럼 되고 싶다."],"title":"해준이 쓴 감상문 「모래성 이야기」 (가~라는 문단)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L02_challenge#3','kor',6,1,'u2','L02','g6_1_kor_u2_L02_challenge','lesson_challenge','K6-1-u2-C10',3,'error','auto','해준의 감상문 중심 내용을 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-1-u2-X13']::text[],false,'{"seq":3,"concept":"K6-1-u2-C10","difficulty":3,"kind":"error","stem":"해준의 감상문 중심 내용을 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"도하 — 「민석이 답은 틀렸어. 중심 내용은 세아가 말한 것 하나뿐이야.」","correct":true,"mis_target":"K6-1-u2-X13"},{"t":"은채 — 「세아는 마지막 문단을 근거로 들었어.」","mis":"K6-1-u2-X13"},{"t":"라온 — 「민석이도 사흘을 버텼다는 부분을 근거로 들었어.」","mis":"K6-1-u2-X13"}],"explanation":["은채와 라온은 근거를 짚었어요.","두 답 모두 근거가 있어요.","도하는 정답이 하나뿐이라고 여겼어요."],"asset":{"type":"speech","turns":[{"who":"세아","text":"이 글의 중심 내용은 「다시 시작하는 힘」이라고 봤어. 마지막 문단에 그렇게 적혀 있잖아."},{"who":"민석","text":"나는 「함께하면 더 오래 버틴다」로 봤어. 새봄과 물길을 판 뒤에 사흘을 버텼다고 나오니까."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L02_challenge#4','kor',6,1,'u2','L02','g6_1_kor_u2_L02_challenge','lesson_challenge','K6-1-u2-C11',3,'mc','auto','나 문단의 중심 문장으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u2-X15','K6-1-u2-X14']::text[],false,'{"seq":4,"concept":"K6-1-u2-C11","difficulty":3,"kind":"mc","stem":"나 문단의 중심 문장으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"미르는 여름 내내 모래성을 쌓았다.","correct":true},{"t":"우리 집 강아지도 모래를 좋아한다.","mis":"K6-1-u2-X15"},{"t":"저녁마다 파도가 성을 지웠다.","mis":"K6-1-u2-X14"},{"t":"새봄과 함께 물길을 팠다.","mis":"K6-1-u2-X14"}],"explanation":["파도 · 물길 이야기는 자세히 설명하는 문장이에요.","강아지는 상관없는 문장이에요.","하고 싶은 말은 여름 내내 쌓은 일이에요."],"asset":{"type":"passage","lines":["가 가장 마음에 남은 곳은 마지막 장면이다. 큰 파도에 성이 무너뜨렸는데도","미르는 울지 않고 젖은 모래를 다시 끌어모은다. 나는 그 장면에서 전혀 지루했다.","나 미르는 여름 내내 쌓았다. 저녁마다 파도가 성을 지웠지만 다음 날 다시 시작했다.","새봄과 함께 물길을 파서 성을 사흘 동안 지켜 내기도 한다. 우리 집 강아지도 모래를 좋아한다.","다 선생님이 이 영화를 우리 반에 소개했다. 제목만 보고는 바다 풍경만 나오는","줄 알았는데, 무엇을 다시 시작하는 사람의 이야기였다.","라 나는 실패한 일을 다시 붙잡는 일이 어렵다고 생각해 왔다. 이 영화를 보고","다시 손을 대는 것도 하나의 힘이라고 생각하게 되었다. 나도 미르처럼 되고 싶다."],"title":"해준이 쓴 감상문 「모래성 이야기」 (가~라는 문단)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L02_challenge#5','kor',6,1,'u2','L02','g6_1_kor_u2_L02_challenge','lesson_challenge','K6-1-u2-C14',3,'match','auto','호응이 어긋난 문장과 어긋난 갈래를 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K6-1-u2-C14","difficulty":3,"kind":"match","stem":"호응이 어긋난 문장과 어긋난 갈래를 이으세요.","pairs":[{"l":"선생님이 소개했다","r":"높임"},{"l":"나는 어제 이 영화를 볼 것이다","r":"시제"},{"l":"나는 전혀 지루했다","r":"부정"}],"mis":"K6-1-u2-X04","explanation":["웃어른에게는 높임이에요.","어제에는 지난 때 서술어예요.","전혀 뒤에는 부정하는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L02_challenge#6','kor',6,1,'u2','L02','g6_1_kor_u2_L02_challenge','lesson_challenge','K6-1-u2-C15',3,'ox','auto','글 수준을 다 고친 뒤에만 문단을 보고, 문단을 다 고친 뒤에만 문장을 봐야 해요.',ARRAY['K6-1-u2-X22']::text[],false,'{"seq":6,"concept":"K6-1-u2-C15","difficulty":3,"kind":"ox","stem":"글 수준을 다 고친 뒤에만 문단을 보고, 문단을 다 고친 뒤에만 문장을 봐야 해요.","answer":"X","reason_options":[{"t":"어느 수준에서 발견하든 그때그때 함께 고치는 것이기 때문에","correct":true},{"t":"세 수준은 꼭 세 번 나누어 해야 하기 때문에","mis":"K6-1-u2-X22"}],"mis":"K6-1-u2-X22","explanation":["큰 것부터 보는 것은 맞아요.","하지만 따로 도는 절차는 아니에요.","보이는 그때그때 함께 고쳐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L02_challenge#7','kor',6,1,'u2','L02','g6_1_kor_u2_L02_challenge','lesson_challenge','K6-1-u2-C15',3,'match','auto','고칠 때 쓰는 부호와 쓰임을 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K6-1-u2-C15","difficulty":3,"kind":"match","stem":"고칠 때 쓰는 부호와 쓰임을 이으세요.","pairs":[{"l":"∨","r":"띄어 쓸 때"},{"l":"⌒","r":"붙여 쓸 때"},{"l":"⊂","r":"내용을 더 넣을 때"}],"mis":"K6-1-u2-X23","explanation":["∨ 는 띄울 곳에 써요.","⌒ 는 붙일 곳에 써요.","⊂ 는 내용을 더 넣을 곳에 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L02_challenge#8','kor',6,1,'u2','L02','g6_1_kor_u2_L02_challenge','lesson_challenge','K6-1-u2-C3',4,'mc','auto','해준의 감상문을 고칠 때 가장 알맞은 계획은 어느 것인가요?',ARRAY['K6-1-u2-X05','K6-1-u2-X01','K6-1-u2-X03']::text[],false,'{"seq":8,"concept":"K6-1-u2-C3","difficulty":4,"kind":"mc","stem":"해준의 감상문을 고칠 때 가장 알맞은 계획은 어느 것인가요?","options":[{"t":"제목과 문단 차례를 먼저 고치고, 나 문단의 강아지 문장을 뺀 뒤, 호응이 어긋난 문장을 고친다","correct":true},{"t":"호응이 어긋난 문장부터 고치고 차례와 제목은 그대로 둔다","mis":"K6-1-u2-X05"},{"t":"강아지 문장을 뺀 뒤 처음부터 다시 쓴다","mis":"K6-1-u2-X01"},{"t":"제목만 바꾸면 나머지는 고칠 필요가 없다","mis":"K6-1-u2-X03"}],"explanation":["큰 것부터 잡아요.","다시 쓰지 않아요.","글 → 문단 → 문장을 고르게 살펴요."],"asset":{"type":"passage","lines":["가 가장 마음에 남은 곳은 마지막 장면이다. 큰 파도에 성이 무너뜨렸는데도","미르는 울지 않고 젖은 모래를 다시 끌어모은다. 나는 그 장면에서 전혀 지루했다.","나 미르는 여름 내내 쌓았다. 저녁마다 파도가 성을 지웠지만 다음 날 다시 시작했다.","새봄과 함께 물길을 파서 성을 사흘 동안 지켜 내기도 한다. 우리 집 강아지도 모래를 좋아한다.","다 선생님이 이 영화를 우리 반에 소개했다. 제목만 보고는 바다 풍경만 나오는","줄 알았는데, 무엇을 다시 시작하는 사람의 이야기였다.","라 나는 실패한 일을 다시 붙잡는 일이 어렵다고 생각해 왔다. 이 영화를 보고","다시 손을 대는 것도 하나의 힘이라고 생각하게 되었다. 나도 미르처럼 되고 싶다."],"title":"해준이 쓴 감상문 「모래성 이야기」 (가~라는 문단)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L02_challenge#9','kor',6,1,'u2','L02','g6_1_kor_u2_L02_challenge','lesson_challenge','K6-1-u2-C8',4,'essay','teacher','해준의 감상문 제목 「모래성 이야기」가 왜 알맞지 않은지 쓰고, 새 제목을 지어 그렇게 지은 까닭을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-1-u2-C8","difficulty":4,"kind":"essay","stem":"해준의 감상문 제목 「모래성 이야기」가 왜 알맞지 않은지 쓰고, 새 제목을 지어 그렇게 지은 까닭을 쓰세요.","answer_guide":{"answer":"예: 「모래성 이야기」는 무엇을 보았는지만 알려 줄 뿐 해준이 느끼고 생각한 것이 담기지 않았다. 해준이 라 문단에서 다시 손을 대는 것도 하나의 힘이라고 생각하게 되었다고 했으므로, 새 제목은 「무너져도 다시 손을 대는 힘」으로 짓겠다. 글쓴이가 가장 하고 싶었던 말을 제목으로 옮겼기 때문이다.","scoring_points":["줄거리만 알리고 느낀 것이 없다는 점을 썼는가","글의 중심 생각이 드러나는 새 제목을 지었는가","글에서 까닭을 찾아 썼는가"]},"explanation":["제목에 무엇이 빠졌는지 봐요.","라 문단을 다시 읽어요.","하고 싶은 말을 제목으로 옮겨요."],"asset":{"type":"passage","lines":["가 가장 마음에 남은 곳은 마지막 장면이다. 큰 파도에 성이 무너뜨렸는데도","미르는 울지 않고 젖은 모래를 다시 끌어모은다. 나는 그 장면에서 전혀 지루했다.","나 미르는 여름 내내 쌓았다. 저녁마다 파도가 성을 지웠지만 다음 날 다시 시작했다.","새봄과 함께 물길을 파서 성을 사흘 동안 지켜 내기도 한다. 우리 집 강아지도 모래를 좋아한다.","다 선생님이 이 영화를 우리 반에 소개했다. 제목만 보고는 바다 풍경만 나오는","줄 알았는데, 무엇을 다시 시작하는 사람의 이야기였다.","라 나는 실패한 일을 다시 붙잡는 일이 어렵다고 생각해 왔다. 이 영화를 보고","다시 손을 대는 것도 하나의 힘이라고 생각하게 되었다. 나도 미르처럼 되고 싶다."],"title":"해준이 쓴 감상문 「모래성 이야기」 (가~라는 문단)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L02_challenge#10','kor',6,1,'u2','L02','g6_1_kor_u2_L02_challenge','lesson_challenge','K6-1-u2-C14',4,'essay','teacher','해준의 감상문에서 호응이 어긋난 문장 두 개를 찾아 바르게 고치고, 어떤 호응이 어긋났는지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-1-u2-C14","difficulty":4,"kind":"essay","stem":"해준의 감상문에서 호응이 어긋난 문장 두 개를 찾아 바르게 고치고, 어떤 호응이 어긋났는지 쓰세요.","answer_guide":{"answer":"예: 「큰 파도에 성이 무너뜨렸는데도」는 성이 스스로 한 일이 아니므로 「성이 무너졌는데도」로 고친다. 피동과 사동이 어긋났다. 「나는 그 장면에서 전혀 지루했다」는 「전혀」 뒤에 부정하는 말이 와야 하므로 「전혀 지루하지 않았다」로 고친다. 부정이 어긋났다. 「선생님이 이 영화를 우리 반에 소개했다」는 「선생님께서 소개해 주셨다」로 고친다. 높임이 어긋났다.","scoring_points":["어긋난 문장 두 개를 바르게 찾았는가","바르게 고쳐 썼는가","어긋난 갈래(높임 · 피동 · 시제 · 부정)를 썼는가"]},"explanation":["서술어를 짚어 앞말과 견주어요.","알맞게 고쳐 써요.","네 가지 갈래 가운데 무엇인지 써요."],"asset":{"type":"passage","lines":["가 가장 마음에 남은 곳은 마지막 장면이다. 큰 파도에 성이 무너뜨렸는데도","미르는 울지 않고 젖은 모래를 다시 끌어모은다. 나는 그 장면에서 전혀 지루했다.","나 미르는 여름 내내 쌓았다. 저녁마다 파도가 성을 지웠지만 다음 날 다시 시작했다.","새봄과 함께 물길을 파서 성을 사흘 동안 지켜 내기도 한다. 우리 집 강아지도 모래를 좋아한다.","다 선생님이 이 영화를 우리 반에 소개했다. 제목만 보고는 바다 풍경만 나오는","줄 알았는데, 무엇을 다시 시작하는 사람의 이야기였다.","라 나는 실패한 일을 다시 붙잡는 일이 어렵다고 생각해 왔다. 이 영화를 보고","다시 손을 대는 것도 하나의 힘이라고 생각하게 되었다. 나도 미르처럼 되고 싶다."],"title":"해준이 쓴 감상문 「모래성 이야기」 (가~라는 문단)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L04_basic#1','kor',6,1,'u2','L04','g6_1_kor_u2_L04_basic','lesson_basic','K6-1-u2-C16',1,'mc','auto','「오늘 밤나무를 심자」는 무슨 뜻인가요?',ARRAY['K6-1-u2-X24']::text[],false,'{"seq":1,"concept":"K6-1-u2-C16","difficulty":1,"kind":"mc","stem":"「오늘 밤나무를 심자」는 무슨 뜻인가요?","options":[{"t":"밤나무라는 나무를 오늘 심자","correct":true},{"t":"오늘 밤에 나무를 심자","mis":"K6-1-u2-X24"},{"t":"오늘 밤에 밤을 줍자","mis":"K6-1-u2-X24"},{"t":"어제 심은 나무를 오늘 뽑자","mis":"K6-1-u2-X24"}],"explanation":["「밤나무」가 붙어 있어요.","붙여 쓴 밤나무는 나무 이름이에요.","오늘 그 나무를 심자는 뜻이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L04_basic#2','kor',6,1,'u2','L04','g6_1_kor_u2_L04_basic','lesson_basic','K6-1-u2-C17',1,'mc','auto','세는 말을 바르게 띄어 쓴 것은 어느 것인가요?',ARRAY['K6-1-u2-X25','K6-1-u2-X24']::text[],false,'{"seq":2,"concept":"K6-1-u2-C17","difficulty":1,"kind":"mc","stem":"세는 말을 바르게 띄어 쓴 것은 어느 것인가요?","options":[{"t":"연필 다섯 자루","correct":true},{"t":"연필 다섯자루","mis":"K6-1-u2-X25"},{"t":"연필다섯 자루","mis":"K6-1-u2-X24"},{"t":"연필다섯자루","mis":"K6-1-u2-X25"}],"explanation":["「자루」는 세는 말이에요.","세는 말은 앞의 수와 띄어 써요.","연필 ∨ 다섯 ∨ 자루로 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L04_basic#3','kor',6,1,'u2','L04','g6_1_kor_u2_L04_basic','lesson_basic','K6-1-u2-C18',1,'mc','auto','잇는 말을 바르게 띄어 쓴 것은 어느 것인가요?',ARRAY['K6-1-u2-X26']::text[],false,'{"seq":3,"concept":"K6-1-u2-C18","difficulty":1,"kind":"mc","stem":"잇는 말을 바르게 띄어 쓴 것은 어느 것인가요?","options":[{"t":"학생 및 학부모","correct":true},{"t":"학생및학부모","mis":"K6-1-u2-X26"},{"t":"학생 및학부모","mis":"K6-1-u2-X26"},{"t":"학생및 학부모","mis":"K6-1-u2-X26"}],"explanation":["「및」은 두 말을 잇는 말이에요.","잇는 말은 앞뒤를 모두 띄어요.","학생 ∨ 및 ∨ 학부모로 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L04_basic#4','kor',6,1,'u2','L04','g6_1_kor_u2_L04_basic','lesson_basic','K6-1-u2-C19',1,'ox','auto','「나무처럼」의 「처럼」은 앞말에 붙여 써요.',ARRAY['K6-1-u2-X27']::text[],false,'{"seq":4,"concept":"K6-1-u2-C19","difficulty":1,"kind":"ox","stem":"「나무처럼」의 「처럼」은 앞말에 붙여 써요.","answer":"O","reason_options":[{"t":"「처럼」은 앞말에 얹혀 가는 조사이기 때문에","correct":true},{"t":"「처럼」은 따로 뜻을 가진 낱말이기 때문에","mis":"K6-1-u2-X27"}],"mis":"K6-1-u2-X27","explanation":["조사는 혼자 쓰이지 않아요.","앞말에 얹혀 가요.","「나무처럼」으로 붙여 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L04_basic#5','kor',6,1,'u2','L04','g6_1_kor_u2_L04_basic','lesson_basic','K6-1-u2-C18',2,'match','auto','붙여 쓴 말을 바르게 고친 것과 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K6-1-u2-C18","difficulty":2,"kind":"match","stem":"붙여 쓴 말을 바르게 고친 것과 이으세요.","pairs":[{"l":"청군대백군","r":"청군 대 백군"},{"l":"서점겸찻집","r":"서점 겸 찻집"},{"l":"교실및복도","r":"교실 및 복도"}],"mis":"K6-1-u2-X26","explanation":["대 · 겸 · 및은 잇는 말이에요.","잇는 말 앞뒤를 띄워요.","한 칸씩 띄우면 읽기 쉬워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L04_basic#6','kor',6,1,'u2','L04','g6_1_kor_u2_L04_basic','lesson_basic','K6-1-u2-C19',2,'mc','auto','「바꿀수있게」를 바르게 띄어 쓴 것은 어느 것인가요?',ARRAY['K6-1-u2-X28','K6-1-u2-X24']::text[],false,'{"seq":6,"concept":"K6-1-u2-C19","difficulty":2,"kind":"mc","stem":"「바꿀수있게」를 바르게 띄어 쓴 것은 어느 것인가요?","options":[{"t":"바꿀 수 있게","correct":true},{"t":"바꿀수 있게","mis":"K6-1-u2-X28"},{"t":"바꿀 수있게","mis":"K6-1-u2-X28"},{"t":"바 꿀 수 있 게","mis":"K6-1-u2-X24"}],"explanation":["「수」는 홀로 못 쓰는 이름씨예요.","홀로 못 쓰는 이름씨는 띄어 써요.","「있게」도 띄어 써요."],"asset":{"type":"passage","lines":["우리 반은 달마다 청소 당번을 새로 정합니다. 지난달에는 한줄로 앉은","차례대로 정했는데 창가 쪽만 힘든 곳을 맡아 불만이 나왔습니다.","그래서 이번에는 제비뽑기로 정하기로 했습니다.","먼저 종이 스물네장을 접어 상자에 넣었습니다.","청소 구역은 교실 및복도, 그리고 계단이었습니다.","뽑고 나서 서로 바꾸고 싶은 사람은 바꿀수있게 했습니다.","힘든 구역을 뽑은 친구에게는 다음 달에 먼저 고를 기회를 주기로 했습니다."],"title":"글 「청소 당번을 정하는 날」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L04_basic#7','kor',6,1,'u2','L04','g6_1_kor_u2_L04_basic','lesson_basic','K6-1-u2-C17',2,'mc','auto','「청소 당번을 정하는 날」에서 띄어쓰기가 잘못된 곳은 어느 것인가요?',ARRAY['K6-1-u2-X25','K6-1-u2-X27']::text[],false,'{"seq":7,"concept":"K6-1-u2-C17","difficulty":2,"kind":"mc","stem":"「청소 당번을 정하는 날」에서 띄어쓰기가 잘못된 곳은 어느 것인가요?","options":[{"t":"스물네장","correct":true},{"t":"제비뽑기로","mis":"K6-1-u2-X25"},{"t":"창가 쪽만","mis":"K6-1-u2-X27"},{"t":"다음 달에","mis":"K6-1-u2-X25"}],"explanation":["「장」은 종이를 세는 말이에요.","세는 말 앞은 띄어 써요.","스물네 ∨ 장으로 고쳐요."],"asset":{"type":"passage","lines":["우리 반은 달마다 청소 당번을 새로 정합니다. 지난달에는 한줄로 앉은","차례대로 정했는데 창가 쪽만 힘든 곳을 맡아 불만이 나왔습니다.","그래서 이번에는 제비뽑기로 정하기로 했습니다.","먼저 종이 스물네장을 접어 상자에 넣었습니다.","청소 구역은 교실 및복도, 그리고 계단이었습니다.","뽑고 나서 서로 바꾸고 싶은 사람은 바꿀수있게 했습니다.","힘든 구역을 뽑은 친구에게는 다음 달에 먼저 고를 기회를 주기로 했습니다."],"title":"글 「청소 당번을 정하는 날」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L04_basic#8','kor',6,1,'u2','L04','g6_1_kor_u2_L04_basic','lesson_basic','K6-1-u2-C16',2,'ox','auto','띄어쓰기는 글씨를 예쁘게 쓰려고 하는 일이에요.',ARRAY['K6-1-u2-X24']::text[],false,'{"seq":8,"concept":"K6-1-u2-C16","difficulty":2,"kind":"ox","stem":"띄어쓰기는 글씨를 예쁘게 쓰려고 하는 일이에요.","answer":"X","reason_options":[{"t":"어디서 띄느냐에 따라 뜻이 달라지므로 뜻을 가르는 일이기 때문에","correct":true},{"t":"띄어 쓰면 글자가 가지런해 보이기 때문에","mis":"K6-1-u2-X24"}],"mis":"K6-1-u2-X24","explanation":["「큰 집」과 「큰집」은 뜻이 달라요.","읽는 사람은 띄어쓰기로 뜻을 알아내요.","띄어쓰기는 뜻을 가르는 일이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L04_basic#9','kor',6,1,'u2','L04','g6_1_kor_u2_L04_basic','lesson_basic','K6-1-u2-C19',2,'match','auto','말과 띄어쓰기 방법을 이으세요.','{}'::text[],false,'{"seq":9,"concept":"K6-1-u2-C19","difficulty":2,"kind":"match","stem":"말과 띄어쓰기 방법을 이으세요.","pairs":[{"l":"을 · 에게 · 만","r":"앞말에 붙여 쓴다"},{"l":"것 · 수 · 데","r":"앞말과 띄어 쓴다"},{"l":"권 · 마리 · 그루","r":"앞의 수와 띄어 쓴다"}],"mis":"K6-1-u2-X27","explanation":["조사는 붙여 써요.","홀로 못 쓰는 이름씨는 띄어요.","세는 말도 수와 띄어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L04_basic#10','kor',6,1,'u2','L04','g6_1_kor_u2_L04_basic','lesson_basic','K6-1-u2-C20',3,'mc','auto','띄어 쓸 곳이 많은 글을 고칠 때 가장 알맞은 방법은 어느 것인가요?',ARRAY['K6-1-u2-X29','K6-1-u2-X23','K6-1-u2-X24']::text[],false,'{"seq":10,"concept":"K6-1-u2-C20","difficulty":3,"kind":"mc","stem":"띄어 쓸 곳이 많은 글을 고칠 때 가장 알맞은 방법은 어느 것인가요?","options":[{"t":"띄울 곳에 ∨ 부호로 표시해 두고 마지막에 한 번에 옮긴다","correct":true},{"t":"고칠 곳이 많으니 글을 처음부터 다시 쓴다","mis":"K6-1-u2-X29"},{"t":"띄울 곳에 ⌒ 부호를 표시한다","mis":"K6-1-u2-X23"},{"t":"띄어쓰기는 읽으면 다 아니까 그냥 둔다","mis":"K6-1-u2-X24"}],"explanation":["다시 쓰지 않아도 돼요.","⌒ 는 붙일 때 써요.","∨ 로 표시하고 한 번에 옮겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L04_challenge#1','kor',6,1,'u2','L04','g6_1_kor_u2_L04_challenge','lesson_challenge','K6-1-u2-C16',2,'mc','auto','「큰집에 다녀왔다」와 「큰 집에 다녀왔다」의 차이로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u2-X24']::text[],false,'{"seq":1,"concept":"K6-1-u2-C16","difficulty":2,"kind":"mc","stem":"「큰집에 다녀왔다」와 「큰 집에 다녀왔다」의 차이로 알맞은 것은 어느 것인가요?","options":[{"t":"앞은 친척 어른이 사는 집이고, 뒤는 크기가 큰 집이다","correct":true},{"t":"두 문장은 뜻이 같다","mis":"K6-1-u2-X24"},{"t":"앞은 틀리고 뒤만 맞다","mis":"K6-1-u2-X24"},{"t":"둘 다 띄어쓰기가 틀렸다","mis":"K6-1-u2-X24"}],"explanation":["띄어쓰기가 다르면 뜻도 달라요.","「큰집」은 한 낱말이에요.","「큰 집」은 크기가 큰 집이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L04_challenge#2','kor',6,1,'u2','L04','g6_1_kor_u2_L04_challenge','lesson_challenge','K6-1-u2-C20',2,'mc','auto','「스물네장」을 고칠 때 쓰는 부호 표시로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u2-X23','K6-1-u2-X25']::text[],false,'{"seq":2,"concept":"K6-1-u2-C20","difficulty":2,"kind":"mc","stem":"「스물네장」을 고칠 때 쓰는 부호 표시로 알맞은 것은 어느 것인가요?","options":[{"t":"스물네∨장","correct":true},{"t":"스물네⌒장","mis":"K6-1-u2-X23"},{"t":"스물⊂네장","mis":"K6-1-u2-X23"},{"t":"스∨물∨네∨장","mis":"K6-1-u2-X25"}],"explanation":["띄울 곳에는 ∨ 를 써요.","⌒ 는 붙일 때 써요.","세는 말 앞에만 ∨ 를 넣어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L04_challenge#3','kor',6,1,'u2','L04','g6_1_kor_u2_L04_challenge','lesson_challenge','K6-1-u2-C17',3,'error','auto','띄어쓰기를 바르게 했는지 살폈어요. 알맞지 않게 쓴 친구는 누구인가요?',ARRAY['K6-1-u2-X25']::text[],false,'{"seq":3,"concept":"K6-1-u2-C17","difficulty":3,"kind":"error","stem":"띄어쓰기를 바르게 했는지 살폈어요. 알맞지 않게 쓴 친구는 누구인가요?","options":[{"t":"하율 — 「사탕 여섯개를 샀다.」","correct":true,"mis_target":"K6-1-u2-X25"},{"t":"서진 — 「나무 두 그루를 심었다.」","mis":"K6-1-u2-X25"},{"t":"라온 — 「우유 한 잔을 마셨다.」","mis":"K6-1-u2-X25"}],"explanation":["그루 · 잔은 수와 띄었어요.","「개」도 세는 말이에요.","사탕 여섯 ∨ 개로 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L04_challenge#4','kor',6,1,'u2','L04','g6_1_kor_u2_L04_challenge','lesson_challenge','K6-1-u2-C19',3,'mc','auto','「먹을것을 챙겨 갈데가 있다.」를 바르게 고친 것은 어느 것인가요?',ARRAY['K6-1-u2-X27','K6-1-u2-X28']::text[],false,'{"seq":4,"concept":"K6-1-u2-C19","difficulty":3,"kind":"mc","stem":"「먹을것을 챙겨 갈데가 있다.」를 바르게 고친 것은 어느 것인가요?","options":[{"t":"먹을 것을 챙겨 갈 데가 있다.","correct":true},{"t":"먹을 것 을 챙겨 갈 데 가 있다.","mis":"K6-1-u2-X27"},{"t":"먹을것을 챙겨 갈 데가 있다.","mis":"K6-1-u2-X28"},{"t":"먹을 것을 챙겨 갈데가 있다.","mis":"K6-1-u2-X28"}],"explanation":["「것」 · 「데」는 홀로 못 쓰는 이름씨예요.","앞말과 띄어 써요.","뒤에 붙은 조사 「을」 · 「가」는 붙여 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L04_challenge#5','kor',6,1,'u2','L04','g6_1_kor_u2_L04_challenge','lesson_challenge','K6-1-u2-C18',3,'mc','auto','「청소 구역은 교실 및복도, 그리고 계단이었습니다.」를 바르게 고친 것은 어느 것인가요?',ARRAY['K6-1-u2-X26','K6-1-u2-X24']::text[],false,'{"seq":5,"concept":"K6-1-u2-C18","difficulty":3,"kind":"mc","stem":"「청소 구역은 교실 및복도, 그리고 계단이었습니다.」를 바르게 고친 것은 어느 것인가요?","options":[{"t":"청소 구역은 교실 및 복도, 그리고 계단이었습니다.","correct":true},{"t":"청소 구역은 교실및복도, 그리고 계단이었습니다.","mis":"K6-1-u2-X26"},{"t":"청소 구역은 교실 및복도, 그리고계단이었습니다.","mis":"K6-1-u2-X26"},{"t":"청소구역은교실및복도, 그리고 계단이었습니다.","mis":"K6-1-u2-X24"}],"explanation":["「및」은 잇는 말이에요.","잇는 말은 앞뒤를 띄어요.","교실 ∨ 및 ∨ 복도로 고쳐요."],"asset":{"type":"passage","lines":["우리 반은 달마다 청소 당번을 새로 정합니다. 지난달에는 한줄로 앉은","차례대로 정했는데 창가 쪽만 힘든 곳을 맡아 불만이 나왔습니다.","그래서 이번에는 제비뽑기로 정하기로 했습니다.","먼저 종이 스물네장을 접어 상자에 넣었습니다.","청소 구역은 교실 및복도, 그리고 계단이었습니다.","뽑고 나서 서로 바꾸고 싶은 사람은 바꿀수있게 했습니다.","힘든 구역을 뽑은 친구에게는 다음 달에 먼저 고를 기회를 주기로 했습니다."],"title":"글 「청소 당번을 정하는 날」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L04_challenge#6','kor',6,1,'u2','L04','g6_1_kor_u2_L04_challenge','lesson_challenge','K6-1-u2-C16',3,'ox','auto','「잘못했다」와 「잘 못했다」는 띄어쓰기만 다르고 뜻은 같아요.',ARRAY['K6-1-u2-X24']::text[],false,'{"seq":6,"concept":"K6-1-u2-C16","difficulty":3,"kind":"ox","stem":"「잘못했다」와 「잘 못했다」는 띄어쓰기만 다르고 뜻은 같아요.","answer":"X","reason_options":[{"t":"「잘못했다」는 틀리게 했다는 뜻이고 「잘 못했다」는 잘하지 못했다는 뜻이라 다르기 때문에","correct":true},{"t":"띄어쓰기는 뜻과 상관없기 때문에","mis":"K6-1-u2-X24"}],"mis":"K6-1-u2-X24","explanation":["붙이면 「잘못」이라는 한 낱말이에요.","띄우면 「잘」과 「못했다」예요.","한 칸이 뜻을 갈라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L04_challenge#7','kor',6,1,'u2','L04','g6_1_kor_u2_L04_challenge','lesson_challenge','K6-1-u2-C20',3,'mc','auto','「띄어쓰기는 좀 틀려도 읽으면 다 알잖아.」라고 생각하는 친구에게 알맞은 생각은 어느 것인가요?',ARRAY['K6-1-u2-X24','K6-1-u2-X29']::text[],false,'{"seq":7,"concept":"K6-1-u2-C20","difficulty":3,"kind":"mc","stem":"「띄어쓰기는 좀 틀려도 읽으면 다 알잖아.」라고 생각하는 친구에게 알맞은 생각은 어느 것인가요?","options":[{"t":"「내가 자주 틀리는 띄어쓰기 한 가지를 정해서 다음 글부터 챙겨 보자.」","correct":true},{"t":"「맞아, 띄어쓰기는 몰라도 된다.」","mis":"K6-1-u2-X24"},{"t":"「틀린 곳이 있으면 글을 처음부터 다시 쓰자.」","mis":"K6-1-u2-X29"},{"t":"「띄어쓰기 규칙만 외우면 버릇은 상관없다.」","mis":"K6-1-u2-X29"}],"explanation":["읽는 사람이 다르게 알아들을 수 있어요.","다시 쓰지 않아도 돼요.","내 버릇 한 가지를 정해 챙겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L04_challenge#8','kor',6,1,'u2','L04','g6_1_kor_u2_L04_challenge','lesson_challenge','K6-1-u2-C17',4,'mc','auto','「청소 당번을 정하는 날」에서 띄어쓰기가 잘못된 곳을 모두 바르게 고친 것은 어느 것인가요?',ARRAY['K6-1-u2-X25','K6-1-u2-X26','K6-1-u2-X28']::text[],false,'{"seq":8,"concept":"K6-1-u2-C17","difficulty":4,"kind":"mc","stem":"「청소 당번을 정하는 날」에서 띄어쓰기가 잘못된 곳을 모두 바르게 고친 것은 어느 것인가요?","options":[{"t":"한 줄로 · 스물네 장 · 교실 및 복도 · 바꿀 수 있게","correct":true},{"t":"한줄로 · 스물네장 · 교실 및 복도 · 바꿀 수 있게","mis":"K6-1-u2-X25"},{"t":"한 줄로 · 스물네 장 · 교실및복도 · 바꿀수있게","mis":"K6-1-u2-X26"},{"t":"한 줄로 · 스물 네 장 · 교실 및 복도 · 바꿀수 있게","mis":"K6-1-u2-X28"}],"explanation":["세는 말 줄 · 장 앞을 띄어요.","잇는 말 및 앞뒤를 띄어요.","홀로 못 쓰는 이름씨 수도 띄어요."],"asset":{"type":"passage","lines":["우리 반은 달마다 청소 당번을 새로 정합니다. 지난달에는 한줄로 앉은","차례대로 정했는데 창가 쪽만 힘든 곳을 맡아 불만이 나왔습니다.","그래서 이번에는 제비뽑기로 정하기로 했습니다.","먼저 종이 스물네장을 접어 상자에 넣었습니다.","청소 구역은 교실 및복도, 그리고 계단이었습니다.","뽑고 나서 서로 바꾸고 싶은 사람은 바꿀수있게 했습니다.","힘든 구역을 뽑은 친구에게는 다음 달에 먼저 고를 기회를 주기로 했습니다."],"title":"글 「청소 당번을 정하는 날」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L04_challenge#9','kor',6,1,'u2','L04','g6_1_kor_u2_L04_challenge','lesson_challenge','K6-1-u2-C16',4,'essay','teacher','띄어쓰기에 따라 뜻이 달라지는 예를 하나 들어 두 가지 뜻을 쓰고, 띄어쓰기가 왜 중요한지 설명하세요.','{}'::text[],false,'{"seq":9,"concept":"K6-1-u2-C16","difficulty":4,"kind":"essay","stem":"띄어쓰기에 따라 뜻이 달라지는 예를 하나 들어 두 가지 뜻을 쓰고, 띄어쓰기가 왜 중요한지 설명하세요.","answer_guide":{"answer":"예: 「오늘밤나무를심자」는 「오늘 밤 나무를 심자」로 띄우면 오늘 밤에 나무를 심자는 뜻이 되고, 「오늘 밤나무를 심자」로 띄우면 오늘 밤나무라는 나무를 심자는 뜻이 된다. 읽는 사람은 글쓴이의 마음을 볼 수 없으므로 띄어쓰기로 뜻을 알아낸다. 그래서 띄어쓰기를 틀리면 읽는 사람이 다르게 알아들을 수 있어 중요하다.","scoring_points":["띄어쓰기에 따라 뜻이 달라지는 예를 들었는가","두 가지 뜻을 바르게 썼는가","읽는 사람이 뜻을 알아내는 일과 이어 중요성을 썼는가"]},"explanation":["뜻이 갈리는 예를 떠올려요.","두 뜻을 견주어 써요.","읽는 사람의 처지에서 설명해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L04_challenge#10','kor',6,1,'u2','L04','g6_1_kor_u2_L04_challenge','lesson_challenge','K6-1-u2-C17',4,'essay','teacher','세는 말 · 잇는 말 · 홀로 못 쓰는 이름씨의 띄어쓰기 방법을 하나씩 예를 들어 설명하고, 내가 자주 틀리는 띄어쓰기 한 가지를 정해 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-1-u2-C17","difficulty":4,"kind":"essay","stem":"세는 말 · 잇는 말 · 홀로 못 쓰는 이름씨의 띄어쓰기 방법을 하나씩 예를 들어 설명하고, 내가 자주 틀리는 띄어쓰기 한 가지를 정해 쓰세요.","answer_guide":{"answer":"예: 세는 말은 앞의 수와 띄어 써서 「책 세 권」처럼 쓴다. 잇는 말은 앞뒤를 띄어 써서 「청군 대 백군」처럼 쓴다. 홀로 못 쓰는 이름씨는 앞말과 띄어 써서 「할 수 있다」처럼 쓴다. 나는 「할수있다」처럼 「수」를 자주 붙여 써서, 다음 글부터는 「수」 앞뒤를 꼭 확인하겠다.","scoring_points":["세 가지 띄어쓰기 방법을 예와 함께 썼는가","예가 규칙에 맞는가","내가 자주 틀리는 곳 한 가지를 정했는가"]},"explanation":["세 가지 규칙을 떠올려요.","알맞은 예를 들어요.","내 버릇 한 가지를 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L05_basic#1','kor',6,1,'u2','L05','g6_1_kor_u2_L05_basic','lesson_basic','K6-1-u2-C21',1,'mc','auto','감상문에 대한 설명으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u2-X30','K6-1-u2-X32']::text[],false,'{"seq":1,"concept":"K6-1-u2-C21","difficulty":1,"kind":"mc","stem":"감상문에 대한 설명으로 알맞은 것은 어느 것인가요?","options":[{"t":"본 것에 더해 내가 무엇을 느끼고 생각했는지를 적은 글","correct":true},{"t":"무슨 일이 일어났는지만 적은 글","mis":"K6-1-u2-X30"},{"t":"누가 써도 똑같아지는 글","mis":"K6-1-u2-X30"},{"t":"본 것의 모든 장면을 빠짐없이 적은 글","mis":"K6-1-u2-X32"}],"explanation":["일어난 일만 적으면 줄거리 요약이에요.","감상문은 쓴 사람마다 달라요.","느끼고 생각한 것을 적어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L05_basic#2','kor',6,1,'u2','L05','g6_1_kor_u2_L05_basic','lesson_basic','K6-1-u2-C22',1,'mc','auto','「우산 하나」에서 여울이 다음 날 아침에 한 일은 무엇인가요?',ARRAY['K6-1-u2-X31']::text[],false,'{"seq":2,"concept":"K6-1-u2-C22","difficulty":1,"kind":"mc","stem":"「우산 하나」에서 여울이 다음 날 아침에 한 일은 무엇인가요?","options":[{"t":"부러진 우산을 고쳐 태린의 사물함 앞에 놓아 두었다","correct":true},{"t":"새 우산을 사서 선물했다","mis":"K6-1-u2-X31"},{"t":"태린의 우산을 빌려 갔다","mis":"K6-1-u2-X31"},{"t":"태린과 우산을 같이 썼다","mis":"K6-1-u2-X31"}],"explanation":["사물함 앞에 낡은 우산이 놓여 있었어요.","실로 꿰맨 자국이 있었어요.","여울이 밤새 고쳐 온 것이에요."],"asset":{"type":"passage","lines":["전학 온 여울은 말수가 적습니다. 쉬는 시간에도 창밖만 봅니다.","비가 쏟아지던 날, 같은 반 태린이 우산을 같이 쓰자고 손짓합니다.","여울은 잠깐 멈추었다가 고개를 젓고 빗속으로 뛰어갑니다.","다음 날 아침, 태린의 사물함 앞에 낡은 우산 하나가 놓여 있습니다.","살이 부러졌던 자리를 실로 꿰맨 자국이 있습니다. 여울이 밤새 고쳐 온 것입니다.","마지막 장면에서 두 아이는 각자 우산을 펴 들고 나란히 걷습니다."],"title":"단편 영화 「우산 하나」 줄거리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L05_basic#3','kor',6,1,'u2','L05','g6_1_kor_u2_L05_basic','lesson_basic','K6-1-u2-C23',1,'mc','auto','감상문에 담을 내용으로 알맞지 않은 것은 어느 것인가요?',ARRAY['K6-1-u2-X32']::text[],false,'{"seq":3,"concept":"K6-1-u2-C23","difficulty":1,"kind":"mc","stem":"감상문에 담을 내용으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"등장인물의 옷 색깔 전부","correct":true},{"t":"보게 된 동기","mis":"K6-1-u2-X32"},{"t":"인상 깊은 장면과 까닭","mis":"K6-1-u2-X32"},{"t":"느낀 점이나 다짐","mis":"K6-1-u2-X32"}],"explanation":["동기 · 장면과 까닭 · 느낀 점은 담아요.","옷 색깔 전부는 상관없는 자잘한 것이에요.","본 것과 생각한 것을 함께 담아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L05_basic#4','kor',6,1,'u2','L05','g6_1_kor_u2_L05_basic','lesson_basic','K6-1-u2-C23',1,'ox','auto','감상문에서는 가운데 부분에 줄거리를 길게 쓰고 생각은 짧게 써요.',ARRAY['K6-1-u2-X32']::text[],false,'{"seq":4,"concept":"K6-1-u2-C23","difficulty":1,"kind":"ox","stem":"감상문에서는 가운데 부분에 줄거리를 길게 쓰고 생각은 짧게 써요.","answer":"X","reason_options":[{"t":"가운데에는 줄거리는 짧게, 인상 깊은 장면과 생각은 길게 쓰기 때문에","correct":true},{"t":"줄거리가 감상문에서 가장 중요하기 때문에","mis":"K6-1-u2-X32"}],"mis":"K6-1-u2-X32","explanation":["가운데가 가장 길어요.","하지만 줄거리는 짧게 써요.","장면과 생각을 길게 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L05_basic#5','kor',6,1,'u2','L05','g6_1_kor_u2_L05_basic','lesson_basic','K6-1-u2-C23',2,'match','auto','감상문 문장이 들어갈 곳을 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K6-1-u2-C23","difficulty":2,"kind":"match","stem":"감상문 문장이 들어갈 곳을 이으세요.","pairs":[{"l":"비 오는 날 이야기라는 말을 듣고 골라 보았다","r":"처음"},{"l":"여울이 고개를 젓고 뛰어가는 장면이 남았다","r":"가운데"},{"l":"나도 도움을 건넬 때 상대의 방식을 물어보겠다","r":"끝"}],"mis":"K6-1-u2-X12","explanation":["보게 된 동기는 처음이에요.","인상 깊은 장면은 가운데예요.","앞으로 할 일은 끝이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L05_basic#6','kor',6,1,'u2','L05','g6_1_kor_u2_L05_basic','lesson_basic','K6-1-u2-C22',2,'mc','auto','세아가 말한 인상 깊은 장면에서 「까닭」에 해당하는 부분은 어느 것인가요?',ARRAY['K6-1-u2-X31','K6-1-u2-X30']::text[],false,'{"seq":6,"concept":"K6-1-u2-C22","difficulty":2,"kind":"mc","stem":"세아가 말한 인상 깊은 장면에서 「까닭」에 해당하는 부분은 어느 것인가요?","options":[{"t":"각자 쓰는데도 둘이 더 가까워 보여서","correct":true},{"t":"마지막 장면이 남았어","mis":"K6-1-u2-X31"},{"t":"우산을 같이 쓰지 않고","mis":"K6-1-u2-X31"},{"t":"세아가 영화를 봤다","mis":"K6-1-u2-X30"}],"explanation":["「마지막 장면」은 고른 장면이에요.","「~여서」가 까닭을 알려 줘요.","왜 그 장면이 남았는지가 까닭이에요."],"asset":{"type":"speech","turns":[{"who":"세아","text":"마지막 장면이 남았어. 우산을 같이 쓰지 않고 각자 쓰는데도 둘이 더 가까워 보여서."},{"who":"민석","text":"나는 여울이 고개를 젓는 장면. 도움을 받는 게 왜 어려웠을지 생각하게 돼서."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L05_basic#7','kor',6,1,'u2','L05','g6_1_kor_u2_L05_basic','lesson_basic','K6-1-u2-C15',2,'mc','auto','태린의 초고에서 빼야 할 문장은 어느 것인가요?',ARRAY['K6-1-u2-X15']::text[],false,'{"seq":7,"concept":"K6-1-u2-C15","difficulty":2,"kind":"mc","stem":"태린의 초고에서 빼야 할 문장은 어느 것인가요?","options":[{"t":"요즘 우리 학교 앞 문구점이 문을 닫았다.","correct":true},{"t":"비 오는 날 이야기라고 해서 골랐다.","mis":"K6-1-u2-X15"},{"t":"다음 날 태린의 사물함 앞에 낡은 우산이 놓여 있었다.","mis":"K6-1-u2-X15"},{"t":"나는 그 장면을 오래 바라보았다.","mis":"K6-1-u2-X15"}],"explanation":["보게 된 동기와 줄거리는 감상문에 필요해요.","문구점 이야기는 영화와 상관없어요.","주제에서 벗어난 문장은 빼요."],"asset":{"type":"passage","lines":["비 오는 날 이야기라고 해서 골랐다. 전학 온 여울은 말이 거의 없다.","태린이 우산을 같이 쓰자고 했지만 여울은 뛰어가 버렸다.","요즘 우리 학교 앞 문구점이 문을 닫았다.","다음 날 태린의 사물함 앞에 낡은 우산이 놓여 있었다.","가장 마음에 남은 곳은 두 사람이 우산두개를 각각 펴 들고","나란히 걷는 장면이다. 나는 그 장면을 오래 바라보았다."],"title":"감상문 초고 「우산 하나를 봤다」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L05_basic#8','kor',6,1,'u2','L05','g6_1_kor_u2_L05_basic','lesson_basic','K6-1-u2-C24',2,'mc','auto','태린의 초고에서 가장 먼저 손볼 것은 어느 것인가요?',ARRAY['K6-1-u2-X05','K6-1-u2-X01']::text[],false,'{"seq":8,"concept":"K6-1-u2-C24","difficulty":2,"kind":"mc","stem":"태린의 초고에서 가장 먼저 손볼 것은 어느 것인가요?","options":[{"t":"제목과 글 전체의 흐름","correct":true},{"t":"띄어쓰기 한 곳","mis":"K6-1-u2-X05"},{"t":"글씨를 예쁘게 옮겨 쓰기","mis":"K6-1-u2-X01"},{"t":"맞춤법만 한 번에","mis":"K6-1-u2-X05"}],"explanation":["작은 것부터 고치면 헛수고가 생겨요.","옮겨 쓰기는 고쳐쓰기가 아니에요.","큰 것부터 잡아요."],"asset":{"type":"passage","lines":["비 오는 날 이야기라고 해서 골랐다. 전학 온 여울은 말이 거의 없다.","태린이 우산을 같이 쓰자고 했지만 여울은 뛰어가 버렸다.","요즘 우리 학교 앞 문구점이 문을 닫았다.","다음 날 태린의 사물함 앞에 낡은 우산이 놓여 있었다.","가장 마음에 남은 곳은 두 사람이 우산두개를 각각 펴 들고","나란히 걷는 장면이다. 나는 그 장면을 오래 바라보았다."],"title":"감상문 초고 「우산 하나를 봤다」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L05_basic#9','kor',6,1,'u2','L05','g6_1_kor_u2_L05_basic','lesson_basic','K6-1-u2-C17',2,'mc','auto','태린의 초고에서 「우산두개」를 바르게 고친 것은 어느 것인가요?',ARRAY['K6-1-u2-X25','K6-1-u2-X24']::text[],false,'{"seq":9,"concept":"K6-1-u2-C17","difficulty":2,"kind":"mc","stem":"태린의 초고에서 「우산두개」를 바르게 고친 것은 어느 것인가요?","options":[{"t":"우산 두 개","correct":true},{"t":"우산두 개","mis":"K6-1-u2-X25"},{"t":"우산 두개","mis":"K6-1-u2-X25"},{"t":"우 산 두 개","mis":"K6-1-u2-X24"}],"explanation":["「개」는 세는 말이에요.","세는 말은 수와 띄어요.","「우산」과 「두」도 띄어요."],"asset":{"type":"passage","lines":["비 오는 날 이야기라고 해서 골랐다. 전학 온 여울은 말이 거의 없다.","태린이 우산을 같이 쓰자고 했지만 여울은 뛰어가 버렸다.","요즘 우리 학교 앞 문구점이 문을 닫았다.","다음 날 태린의 사물함 앞에 낡은 우산이 놓여 있었다.","가장 마음에 남은 곳은 두 사람이 우산두개를 각각 펴 들고","나란히 걷는 장면이다. 나는 그 장면을 오래 바라보았다."],"title":"감상문 초고 「우산 하나를 봤다」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L05_basic#10','kor',6,1,'u2','L05','g6_1_kor_u2_L05_basic','lesson_basic','K6-1-u2-C7',3,'mc','auto','「고칠 곳이 너무 많아 보여서 아예 다시 쓸까 했어.」라는 민석이에게 해 줄 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u2-X01','K6-1-u2-X02','K6-1-u2-X05']::text[],false,'{"seq":10,"concept":"K6-1-u2-C7","difficulty":3,"kind":"mc","stem":"「고칠 곳이 너무 많아 보여서 아예 다시 쓸까 했어.」라는 민석이에게 해 줄 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「세 군데만 고쳐도 훨씬 잘 읽힐 수 있어. 완벽하게 고칠 필요는 없어.」","correct":true},{"t":"「맞아, 다시 쓰는 게 제일 좋아.」","mis":"K6-1-u2-X01"},{"t":"「완벽하게 고칠 수 없으면 손대지 마.」","mis":"K6-1-u2-X02"},{"t":"「띄어쓰기만 고치면 다 끝나.」","mis":"K6-1-u2-X05"}],"explanation":["다시 쓰지 않아도 돼요.","완벽할 필요가 없어요.","작게 고친 것도 잘 고친 것이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L05_challenge#1','kor',6,1,'u2','L05','g6_1_kor_u2_L05_challenge','lesson_challenge','K6-1-u2-C21',2,'mc','auto','줄거리 요약과 감상문을 견준 것으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u2-X30','K6-1-u2-X32']::text[],false,'{"seq":1,"concept":"K6-1-u2-C21","difficulty":2,"kind":"mc","stem":"줄거리 요약과 감상문을 견준 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"줄거리 요약은 누가 써도 비슷하지만 감상문은 쓴 사람마다 달라진다","correct":true},{"t":"두 글은 같은 글이다","mis":"K6-1-u2-X30"},{"t":"감상문에는 줄거리가 하나도 들어가지 않는다","mis":"K6-1-u2-X32"},{"t":"줄거리 요약이 감상문보다 생각이 더 많이 담긴다","mis":"K6-1-u2-X30"}],"explanation":["줄거리 요약은 일어난 일만 적어요.","감상문에도 간단한 줄거리는 들어가요.","감상문에는 내 생각이 담겨 사람마다 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L05_challenge#2','kor',6,1,'u2','L05','g6_1_kor_u2_L05_challenge','lesson_challenge','K6-1-u2-C8',2,'mc','auto','태린의 초고 제목 「우산 하나를 봤다」를 고친 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u2-X11','K6-1-u2-X36']::text[],false,'{"seq":2,"concept":"K6-1-u2-C8","difficulty":2,"kind":"mc","stem":"태린의 초고 제목 「우산 하나를 봤다」를 고친 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"각자 쓰는 우산, 나란한 걸음","correct":true},{"t":"우산 하나 줄거리","mis":"K6-1-u2-X11"},{"t":"비 오는 날","mis":"K6-1-u2-X11"},{"t":"학교 앞 문구점","mis":"K6-1-u2-X36"}],"explanation":["지금 제목에는 느낀 점이 없어요.","글감만 알리는 제목은 부족해요.","마음에 남은 장면과 생각을 담아요."],"asset":{"type":"passage","lines":["비 오는 날 이야기라고 해서 골랐다. 전학 온 여울은 말이 거의 없다.","태린이 우산을 같이 쓰자고 했지만 여울은 뛰어가 버렸다.","요즘 우리 학교 앞 문구점이 문을 닫았다.","다음 날 태린의 사물함 앞에 낡은 우산이 놓여 있었다.","가장 마음에 남은 곳은 두 사람이 우산두개를 각각 펴 들고","나란히 걷는 장면이다. 나는 그 장면을 오래 바라보았다."],"title":"감상문 초고 「우산 하나를 봤다」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L05_challenge#3','kor',6,1,'u2','L05','g6_1_kor_u2_L05_challenge','lesson_challenge','K6-1-u2-C22',3,'error','auto','감상문에 쓸 문장을 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-1-u2-X31']::text[],false,'{"seq":3,"concept":"K6-1-u2-C22","difficulty":3,"kind":"error","stem":"감상문에 쓸 문장을 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"하율 — 「마지막 장면이 좋았다. 끝.」","correct":true,"mis_target":"K6-1-u2-X31"},{"t":"서진 — 「여울이 고개를 젓는 장면에서 도움을 받는 게 왜 어려웠을지 생각했다.」","mis":"K6-1-u2-X31"},{"t":"라온 — 「꿰맨 우산을 보고, 받은 마음을 갚는 방법이 여러 가지라는 걸 알았다.」","mis":"K6-1-u2-X31"}],"explanation":["서진과 라온은 까닭을 붙였어요.","하율은 왜 좋았는지 쓰지 않았어요.","장면에는 까닭을 붙여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L05_challenge#4','kor',6,1,'u2','L05','g6_1_kor_u2_L05_challenge','lesson_challenge','K6-1-u2-C24',3,'mc','auto','감상문 초고를 고칠 때 「띄어쓰기부터 손대는 것」이 알맞지 않은 까닭은 무엇인가요?',ARRAY['K6-1-u2-X24','K6-1-u2-X40','K6-1-u2-X01']::text[],false,'{"seq":4,"concept":"K6-1-u2-C24","difficulty":3,"kind":"mc","stem":"감상문 초고를 고칠 때 「띄어쓰기부터 손대는 것」이 알맞지 않은 까닭은 무엇인가요?","options":[{"t":"띄어쓰기를 다 고친 문장이 나중에 통째로 빠져야 하면 헛수고가 되기 때문에","correct":true},{"t":"띄어쓰기는 고칠 필요가 없기 때문에","mis":"K6-1-u2-X24"},{"t":"띄어쓰기는 친구가 고쳐 주기 때문에","mis":"K6-1-u2-X40"},{"t":"띄어쓰기를 고치면 글을 다시 써야 하기 때문에","mis":"K6-1-u2-X01"}],"explanation":["띄어쓰기도 고쳐요.","다만 마지막에 해요.","큰 것부터 잡아야 헛수고가 줄어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L05_challenge#5','kor',6,1,'u2','L05','g6_1_kor_u2_L05_challenge','lesson_challenge','K6-1-u2-C24',3,'ox','auto','맞춤법과 띄어쓰기를 다 바로잡았으면 고쳐쓰기는 끝난 거예요.',ARRAY['K6-1-u2-X05']::text[],false,'{"seq":5,"concept":"K6-1-u2-C24","difficulty":3,"kind":"ox","stem":"맞춤법과 띄어쓰기를 다 바로잡았으면 고쳐쓰기는 끝난 거예요.","answer":"X","reason_options":[{"t":"글 · 문단 수준의 흐름과 내용까지 고르게 살펴야 하기 때문에","correct":true},{"t":"맞춤법이 글에서 가장 중요하기 때문에","mis":"K6-1-u2-X05"}],"mis":"K6-1-u2-X05","explanation":["맞춤법은 문장 수준의 일부예요.","주제에서 벗어난 문장 · 차례도 봐요.","세 수준을 고르게 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L05_challenge#6','kor',6,1,'u2','L05','g6_1_kor_u2_L05_challenge','lesson_challenge','K6-1-u2-C24',3,'match','auto','태린의 초고에서 고칠 곳과 수준을 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K6-1-u2-C24","difficulty":3,"kind":"match","stem":"태린의 초고에서 고칠 곳과 수준을 이으세요.","pairs":[{"l":"제목에 느낀 점이 없음","r":"글 수준"},{"l":"문구점 문장이 끼어 있음","r":"문단 수준"},{"l":"「우산두개」 띄어쓰기","r":"문장 수준"}],"mis":"K6-1-u2-X04","explanation":["제목은 글 전체와 견줘요.","끼어든 문장은 문단에서 봐요.","띄어쓰기는 문장에서 봐요."],"asset":{"type":"passage","lines":["비 오는 날 이야기라고 해서 골랐다. 전학 온 여울은 말이 거의 없다.","태린이 우산을 같이 쓰자고 했지만 여울은 뛰어가 버렸다.","요즘 우리 학교 앞 문구점이 문을 닫았다.","다음 날 태린의 사물함 앞에 낡은 우산이 놓여 있었다.","가장 마음에 남은 곳은 두 사람이 우산두개를 각각 펴 들고","나란히 걷는 장면이다. 나는 그 장면을 오래 바라보았다."],"title":"감상문 초고 「우산 하나를 봤다」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L05_challenge#7','kor',6,1,'u2','L05','g6_1_kor_u2_L05_challenge','lesson_challenge','K6-1-u2-C23',3,'mc','auto','「우산 하나」 감상문의 「끝」에 들어갈 문장으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u2-X12','K6-1-u2-X32']::text[],false,'{"seq":7,"concept":"K6-1-u2-C23","difficulty":3,"kind":"mc","stem":"「우산 하나」 감상문의 「끝」에 들어갈 문장으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"나도 친구에게 도움을 건넬 때 그 친구가 편한 방식을 먼저 물어보겠다.","correct":true},{"t":"비 오는 날 이야기라고 해서 골랐다.","mis":"K6-1-u2-X12"},{"t":"여울이 빗속으로 뛰어갔다.","mis":"K6-1-u2-X12"},{"t":"여울의 옷은 파란색이었고 가방은 회색이었다.","mis":"K6-1-u2-X32"}],"explanation":["보게 된 동기는 처음이에요.","줄거리는 가운데예요.","끝에는 느낀 점과 앞으로 할 일을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L05_challenge#8','kor',6,1,'u2','L05','g6_1_kor_u2_L05_challenge','lesson_challenge','K6-1-u2-C23',4,'mc','auto','태린의 초고를 고친 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u2-X03','K6-1-u2-X05','K6-1-u2-X32']::text[],false,'{"seq":8,"concept":"K6-1-u2-C23","difficulty":4,"kind":"mc","stem":"태린의 초고를 고친 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"제목을 「각자 쓰는 우산, 나란한 걸음」으로 바꾸고, 문구점 문장을 빼고, 「우산 두 개」로 띄어 쓴다","correct":true},{"t":"문구점 문장을 맨 앞으로 옮기고 나머지는 그대로 둔다","mis":"K6-1-u2-X03"},{"t":"「우산 두 개」만 고치고 제목과 문장은 그대로 둔다","mis":"K6-1-u2-X05"},{"t":"모든 장면을 빠짐없이 더 넣는다","mis":"K6-1-u2-X32"}],"explanation":["벗어난 문장은 옮기지 않고 빼요.","띄어쓰기만으로는 부족해요.","제목 · 문단 · 문장을 고르게 고쳐요."],"asset":{"type":"passage","lines":["비 오는 날 이야기라고 해서 골랐다. 전학 온 여울은 말이 거의 없다.","태린이 우산을 같이 쓰자고 했지만 여울은 뛰어가 버렸다.","요즘 우리 학교 앞 문구점이 문을 닫았다.","다음 날 태린의 사물함 앞에 낡은 우산이 놓여 있었다.","가장 마음에 남은 곳은 두 사람이 우산두개를 각각 펴 들고","나란히 걷는 장면이다. 나는 그 장면을 오래 바라보았다."],"title":"감상문 초고 「우산 하나를 봤다」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L05_challenge#9','kor',6,1,'u2','L05','g6_1_kor_u2_L05_challenge','lesson_challenge','K6-1-u2-C22',4,'essay','teacher','「우산 하나」에서 가장 인상 깊은 장면을 하나 고르고, 그 장면이 왜 마음에 남았는지 까닭을 붙여 감상문의 가운데 부분을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-1-u2-C22","difficulty":4,"kind":"essay","stem":"「우산 하나」에서 가장 인상 깊은 장면을 하나 고르고, 그 장면이 왜 마음에 남았는지 까닭을 붙여 감상문의 가운데 부분을 쓰세요.","answer_guide":{"answer":"예: 가장 마음에 남은 장면은 태린의 사물함 앞에 실로 꿰맨 낡은 우산이 놓여 있던 장면이다. 여울은 우산을 같이 쓰자는 말에 고개를 저었지만, 밤새 우산을 고쳐 와서 고마운 마음을 자기 방식으로 돌려주었다. 나는 이 장면을 보고 고마움을 표현하는 방법이 사람마다 다를 수 있다는 것을 알게 되었다.","scoring_points":["인상 깊은 장면을 하나 골랐는가","그 장면이 남은 까닭을 썼는가","줄거리는 짧게, 생각은 자세히 썼는가"]},"explanation":["한 장면을 골라요.","왜 남았는지 까닭을 붙여요.","생각을 자세히 써요."],"asset":{"type":"passage","lines":["전학 온 여울은 말수가 적습니다. 쉬는 시간에도 창밖만 봅니다.","비가 쏟아지던 날, 같은 반 태린이 우산을 같이 쓰자고 손짓합니다.","여울은 잠깐 멈추었다가 고개를 젓고 빗속으로 뛰어갑니다.","다음 날 아침, 태린의 사물함 앞에 낡은 우산 하나가 놓여 있습니다.","살이 부러졌던 자리를 실로 꿰맨 자국이 있습니다. 여울이 밤새 고쳐 온 것입니다.","마지막 장면에서 두 아이는 각자 우산을 펴 들고 나란히 걷습니다."],"title":"단편 영화 「우산 하나」 줄거리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L05_challenge#10','kor',6,1,'u2','L05','g6_1_kor_u2_L05_challenge','lesson_challenge','K6-1-u2-C24',4,'essay','teacher','태린의 초고에서 고칠 곳 세 가지를 글 · 문단 · 문장 수준으로 나누어 찾고, 어떤 차례로 고칠지 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-1-u2-C24","difficulty":4,"kind":"essay","stem":"태린의 초고에서 고칠 곳 세 가지를 글 · 문단 · 문장 수준으로 나누어 찾고, 어떤 차례로 고칠지 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 글 수준 — 제목 「우산 하나를 봤다」에 느낀 점이 없다. 문단 수준 — 「요즘 우리 학교 앞 문구점이 문을 닫았다」는 영화와 상관없는 문장이다. 문장 수준 — 「우산두개」는 「우산 두 개」로 띄어 써야 한다. 고칠 차례는 제목과 글의 흐름 → 문구점 문장 빼기 → 띄어쓰기이다. 큰 것부터 고쳐야 다듬은 문장이 통째로 빠지는 헛수고가 없기 때문이다.","scoring_points":["세 수준의 고칠 곳을 하나씩 찾았는가","큰 것부터의 차례를 썼는가","그 차례의 까닭을 썼는가"]},"explanation":["세 수준으로 나누어 찾아요.","큰 것부터 차례를 정해요.","헛수고가 줄어드는 까닭을 써요."],"asset":{"type":"passage","lines":["비 오는 날 이야기라고 해서 골랐다. 전학 온 여울은 말이 거의 없다.","태린이 우산을 같이 쓰자고 했지만 여울은 뛰어가 버렸다.","요즘 우리 학교 앞 문구점이 문을 닫았다.","다음 날 태린의 사물함 앞에 낡은 우산이 놓여 있었다.","가장 마음에 남은 곳은 두 사람이 우산두개를 각각 펴 들고","나란히 걷는 장면이다. 나는 그 장면을 오래 바라보았다."],"title":"감상문 초고 「우산 하나를 봤다」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L07_basic#1','kor',6,1,'u2','L07','g6_1_kor_u2_L07_basic','lesson_basic','K6-1-u2-C25',1,'mc','auto','명확한 문장의 조건으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u2-X33','K6-1-u2-X35','K6-1-u2-X34']::text[],false,'{"seq":1,"concept":"K6-1-u2-C25","difficulty":1,"kind":"mc","stem":"명확한 문장의 조건으로 알맞은 것은 어느 것인가요?","options":[{"t":"한 문장에는 한 가지만 담는다","correct":true},{"t":"한 문장에 되도록 많은 것을 담는다","mis":"K6-1-u2-X33"},{"t":"같은 낱말을 여러 번 되풀이한다","mis":"K6-1-u2-X35"},{"t":"주어와 목적어는 빼도 된다","mis":"K6-1-u2-X34"}],"explanation":["길게 이으면 한 번에 읽히지 않아요.","겹치는 표현은 줄여요.","한 문장에 한 가지만 담아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L07_basic#2','kor',6,1,'u2','L07','g6_1_kor_u2_L07_basic','lesson_basic','K6-1-u2-C25',1,'mc','auto','다빈이 처음 쓴 문장이 한 번에 읽히지 않는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u2-X37','K6-1-u2-X36','K6-1-u2-X33']::text[],false,'{"seq":2,"concept":"K6-1-u2-C25","difficulty":1,"kind":"mc","stem":"다빈이 처음 쓴 문장이 한 번에 읽히지 않는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"한 문장 안에 너무 많은 것이 들어 있고 같은 낱말이 되풀이되어서","correct":true},{"t":"틀린 내용이 많아서","mis":"K6-1-u2-X37"},{"t":"주제가 도서관이 아니어서","mis":"K6-1-u2-X36"},{"t":"문장이 너무 짧아서","mis":"K6-1-u2-X33"}],"explanation":["틀린 말은 하나도 없어요.","한 문장에 여러 가지가 이어져 있어요.","「번호」가 자꾸 되풀이돼요."],"asset":{"type":"passage","lines":["도서관에 가면 책마다 번호가 붙어 있는데 그 번호는 아무렇게나 붙인 번호가","아니라 책의 내용을 나누어 놓은 번호이고 그 번호를 알면 책을 찾기가","쉬워지는데 번호를 모르면 책을 찾기가 어렵고 그래서 도서관에서는","번호를 붙여 놓는 것입니다."],"title":"다빈이 처음 쓴 문장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L07_basic#3','kor',6,1,'u2','L07','g6_1_kor_u2_L07_basic','lesson_basic','K6-1-u2-C28',1,'mc','auto','설명하는 글에 쓰기 알맞은 자료는 어느 것인가요?',ARRAY['K6-1-u2-X37','K6-1-u2-X09']::text[],false,'{"seq":3,"concept":"K6-1-u2-C28","difficulty":1,"kind":"mc","stem":"설명하는 글에 쓰기 알맞은 자료는 어느 것인가요?","options":[{"t":"도서관에서 올해 펴낸 이용 안내 자료","correct":true},{"t":"누가 언제 썼는지 알 수 없는 글","mis":"K6-1-u2-X37"},{"t":"친구가 어디선가 들었다는 이야기","mis":"K6-1-u2-X37"},{"t":"다른 사람 글을 이름 없이 옮긴 것","mis":"K6-1-u2-X09"}],"explanation":["누가 만들었는지 알 수 있어야 해요.","언제 만들었는지 알 수 있어야 해요.","확인한 자료만 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L07_basic#4','kor',6,1,'u2','L07','g6_1_kor_u2_L07_basic','lesson_basic','K6-1-u2-C29',1,'match','auto','설명하는 글의 짜임과 하는 일을 이으세요.','{}'::text[],false,'{"seq":4,"concept":"K6-1-u2-C29","difficulty":1,"kind":"match","stem":"설명하는 글의 짜임과 하는 일을 이으세요.","pairs":[{"l":"처음","r":"무엇을 설명할지 밝히고 관심을 끈다"},{"l":"가운데","r":"설명하려는 내용을 자세하게 풀어 쓴다"},{"l":"끝","r":"전체 내용을 간추리고 마무리한다"}],"mis":"K6-1-u2-X12","explanation":["처음에는 무엇을 설명할지 밝혀요.","가운데에는 자세히 풀어 써요.","끝에는 간추려 맺어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L07_basic#5','kor',6,1,'u2','L07','g6_1_kor_u2_L07_basic','lesson_basic','K6-1-u2-C26',2,'match','auto','문장에서 빠진 성분을 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K6-1-u2-C26","difficulty":2,"kind":"match","stem":"문장에서 빠진 성분을 이으세요.","pairs":[{"l":"책등에 붙어 있습니다.","r":"주어 — 무엇이"},{"l":"나는 서가에서 찾았습니다.","r":"목적어 — 무엇을"},{"l":"이 숫자는 책의 갈래를.","r":"서술어 — 어찌한다"}],"mis":"K6-1-u2-X34","explanation":["무엇이 붙어 있는지 빠졌어요.","무엇을 찾았는지 빠졌어요.","어찌한다는 말이 빠졌어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L07_basic#6','kor',6,1,'u2','L07','g6_1_kor_u2_L07_basic','lesson_basic','K6-1-u2-C26',2,'ox','auto','말할 때 주어를 빼도 통하니까 글에서도 주어를 빼도 괜찮아요.',ARRAY['K6-1-u2-X34']::text[],false,'{"seq":6,"concept":"K6-1-u2-C26","difficulty":2,"kind":"ox","stem":"말할 때 주어를 빼도 통하니까 글에서도 주어를 빼도 괜찮아요.","answer":"X","reason_options":[{"t":"읽는 사람은 그 자리에 없었으므로 글에서는 필수 성분을 갖춰야 뜻이 전해지기 때문에","correct":true},{"t":"글은 말보다 짧게 써야 하기 때문에","mis":"K6-1-u2-X34"}],"mis":"K6-1-u2-X34","explanation":["말할 때는 서로 아는 것이 많아요.","읽는 사람은 그 자리에 없었어요.","글에서는 필수 성분을 갖춰요."],"asset":{"type":"speech","turns":[{"who":"민석","text":"(책을 들고) 여기 있어. 아까 찾던 거."},{"who":"세아","text":"고마워!"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L07_basic#7','kor',6,1,'u2','L07','g6_1_kor_u2_L07_basic','lesson_basic','K6-1-u2-C25',2,'mc','auto','다빈이 고친 글에서 한 일로 알맞지 않은 것은 어느 것인가요?',ARRAY['K6-1-u2-X33','K6-1-u2-X35']::text[],false,'{"seq":7,"concept":"K6-1-u2-C25","difficulty":2,"kind":"mc","stem":"다빈이 고친 글에서 한 일로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"설명하려는 내용을 다른 것으로 바꾸었다","correct":true},{"t":"한 문장을 여러 문장으로 나누었다","mis":"K6-1-u2-X33"},{"t":"되풀이되던 「번호」를 숫자 · 표시로 바꾸었다","mis":"K6-1-u2-X35"},{"t":"뜻이 또렷한 낱말로 바꾸었다","mis":"K6-1-u2-X35"}],"explanation":["문장을 셋으로 나누었어요.","겹치는 표현을 줄였어요.","설명하려는 내용은 그대로예요."],"asset":{"type":"passage","lines":["도서관에 가면 책등마다 숫자가 붙어 있습니다.","이 숫자는 책의 내용을 갈래별로 나눈 표시입니다.","숫자를 알면 넓은 서가에서도 찾는 책 앞으로 곧장 갈 수 있습니다."],"title":"다빈이 고친 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L07_basic#8','kor',6,1,'u2','L07','g6_1_kor_u2_L07_basic','lesson_basic','K6-1-u2-C27',2,'mc','auto','설명하는 글의 주제로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u2-X36']::text[],false,'{"seq":8,"concept":"K6-1-u2-C27","difficulty":2,"kind":"mc","stem":"설명하는 글의 주제로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"우리 동네 버스 번호의 규칙","correct":true},{"t":"세상에 있는 모든 동물","mis":"K6-1-u2-X36"},{"t":"어제 내가 먹은 아침","mis":"K6-1-u2-X36"},{"t":"우주에서 일어나는 모든 일","mis":"K6-1-u2-X36"}],"explanation":["너무 넓은 주제는 무엇부터 쓸지 몰라요.","쓸 말이 거의 없는 것도 어려워요.","궁금해할 만하고 자료를 모을 수 있는 것을 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L07_basic#9','kor',6,1,'u2','L07','g6_1_kor_u2_L07_basic','lesson_basic','K6-1-u2-C30',2,'ox','auto','찾은 자료를 그대로 붙여 넣으면 내가 쓴 설명하는 글이 돼요.',ARRAY['K6-1-u2-X38']::text[],false,'{"seq":9,"concept":"K6-1-u2-C30","difficulty":2,"kind":"ox","stem":"찾은 자료를 그대로 붙여 넣으면 내가 쓴 설명하는 글이 돼요.","answer":"X","reason_options":[{"t":"읽고 이해한 뒤 내 말로 다시 써야 내 글이기 때문에","correct":true},{"t":"자료가 내 글보다 정확하기 때문에","mis":"K6-1-u2-X38"}],"mis":"K6-1-u2-X38","explanation":["그대로 옮긴 문장은 내 글이 아니에요.","이해한 것을 내 말로 써요.","가져온 곳도 함께 적어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L07_basic#10','kor',6,1,'u2','L07','g6_1_kor_u2_L07_basic','lesson_basic','K6-1-u2-C28',3,'mc','auto','자료를 쓸 때 확인할 세 가지를 바르게 묶은 것은 어느 것인가요?',ARRAY['K6-1-u2-X37','K6-1-u2-X43']::text[],false,'{"seq":10,"concept":"K6-1-u2-C28","difficulty":3,"kind":"mc","stem":"자료를 쓸 때 확인할 세 가지를 바르게 묶은 것은 어느 것인가요?","options":[{"t":"누가 만들었는가 · 언제 만들었는가 · 어디서 가져왔는가","correct":true},{"t":"얼마나 긴가 · 그림이 있는가 · 재미있는가","mis":"K6-1-u2-X37"},{"t":"친구가 좋아하는가 · 유명한가 · 길이가 짧은가","mis":"K6-1-u2-X37"},{"t":"누가 만들었는가 · 그림이 예쁜가 · 글씨가 큰가","mis":"K6-1-u2-X43"}],"explanation":["믿을 수 있는지 봐요.","지금도 맞는지 봐요.","출처를 밝혔는지 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L07_challenge#1','kor',6,1,'u2','L07','g6_1_kor_u2_L07_challenge','lesson_challenge','K6-1-u2-C25',2,'mc','auto','「숫자는 갈래를 나타내고 숫자를 알면 책을 빨리 찾을 수 있고 도서관마다 안내도가 있어서 그것을 보면 된다.」를 잘 나눈 것은 어느 것인가요?',ARRAY['K6-1-u2-X33','K6-1-u2-X34','K6-1-u2-X35']::text[],false,'{"seq":1,"concept":"K6-1-u2-C25","difficulty":2,"kind":"mc","stem":"「숫자는 갈래를 나타내고 숫자를 알면 책을 빨리 찾을 수 있고 도서관마다 안내도가 있어서 그것을 보면 된다.」를 잘 나눈 것은 어느 것인가요?","options":[{"t":"숫자는 갈래를 나타냅니다. 숫자를 알면 책을 빨리 찾을 수 있습니다. 도서관마다 안내도도 있습니다.","correct":true},{"t":"숫자는 갈래를 나타내고 알면 빨리 찾을 수 있고 안내도도 있고 보면 됩니다.","mis":"K6-1-u2-X33"},{"t":"숫자는 갈래. 책은 빨리. 안내도.","mis":"K6-1-u2-X34"},{"t":"숫자 숫자 숫자는 갈래를 나타냅니다.","mis":"K6-1-u2-X35"}],"explanation":["여전히 이어 붙이면 길어요.","너무 줄이면 서술어가 빠져요.","한 문장에 한 가지씩, 서술어도 갖춰요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L07_challenge#2','kor',6,1,'u2','L07','g6_1_kor_u2_L07_challenge','lesson_challenge','K6-1-u2-C27',2,'mc','auto','설명하는 글의 제목으로 알맞은 것의 조건은 어느 것인가요?',ARRAY['K6-1-u2-X36','K6-1-u2-X11']::text[],false,'{"seq":2,"concept":"K6-1-u2-C27","difficulty":2,"kind":"mc","stem":"설명하는 글의 제목으로 알맞은 것의 조건은 어느 것인가요?","options":[{"t":"내용과 일치하고 짧으면서 관심을 끈다","correct":true},{"t":"내용과 상관없이 재미있으면 된다","mis":"K6-1-u2-X36"},{"t":"글감 이름만 쓰면 충분하다","mis":"K6-1-u2-X11"},{"t":"길수록 자세해서 좋다","mis":"K6-1-u2-X36"}],"explanation":["제목은 내용과 일치해야 해요.","짧으면서 관심을 끌어야 해요.","주제를 정한 다음에 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L07_challenge#3','kor',6,1,'u2','L07','g6_1_kor_u2_L07_challenge','lesson_challenge','K6-1-u2-C26',3,'error','auto','「여기 있어. 아까 찾던 거.」를 두고 이야기했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-1-u2-X34']::text[],false,'{"seq":3,"concept":"K6-1-u2-C26","difficulty":3,"kind":"error","stem":"「여기 있어. 아까 찾던 거.」를 두고 이야기했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"하율 — 「글에 써도 똑같이 뜻이 다 통해.」","correct":true,"mis_target":"K6-1-u2-X34"},{"t":"서진 — 「말할 때는 둘 다 무엇인지 알아서 통해.」","mis":"K6-1-u2-X34"},{"t":"라온 — 「글로 쓰면 무엇이 어디 있는지 넣어야 해.」","mis":"K6-1-u2-X34"}],"explanation":["서진과 라온은 바르게 말했어요.","읽는 사람은 무엇을 찾았는지 몰라요.","하율은 글에서도 필수 성분을 빼도 된다고 여겼어요."],"asset":{"type":"speech","turns":[{"who":"민석","text":"(책을 들고) 여기 있어. 아까 찾던 거."},{"who":"세아","text":"고마워!"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L07_challenge#4','kor',6,1,'u2','L07','g6_1_kor_u2_L07_challenge','lesson_challenge','K6-1-u2-C25',3,'mc','auto','「이 책은 책장 맨 위 책장 칸에 꽂힌 책입니다.」에서 고칠 점으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u2-X34','K6-1-u2-X33','K6-1-u2-X35']::text[],false,'{"seq":4,"concept":"K6-1-u2-C25","difficulty":3,"kind":"mc","stem":"「이 책은 책장 맨 위 책장 칸에 꽂힌 책입니다.」에서 고칠 점으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"겹치는 「책」 · 「책장」을 줄여 「이 책은 책장 맨 위 칸에 꽂혀 있습니다.」로 쓴다","correct":true},{"t":"주어를 빼고 「맨 위 칸에 꽂힌 책입니다.」로 쓴다","mis":"K6-1-u2-X34"},{"t":"뒤에 문장을 더 이어 붙인다","mis":"K6-1-u2-X33"},{"t":"그대로 두어도 된다","mis":"K6-1-u2-X35"}],"explanation":["주어를 빼면 무엇인지 몰라요.","이어 붙이면 더 길어져요.","겹치는 표현을 하나로 줄여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L07_challenge#5','kor',6,1,'u2','L07','g6_1_kor_u2_L07_challenge','lesson_challenge','K6-1-u2-C28',3,'match','auto','자료와 알맞은 판단을 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K6-1-u2-C28","difficulty":3,"kind":"match","stem":"자료와 알맞은 판단을 이으세요.","pairs":[{"l":"도서관에서 올해 펴낸 이용 안내 자료","r":"만든 곳과 때를 알아 쓸 수 있다"},{"l":"누가 언제 썼는지 알 수 없는 글","r":"확인되지 않아 쓰지 않는다"},{"l":"책에서 옮겨 온 설명","r":"내 말로 바꾸고 출처를 적는다"}],"mis":"K6-1-u2-X37","explanation":["만든 곳과 때가 분명하면 믿을 수 있어요.","확인되지 않은 자료는 쓰지 않아요.","옮긴 것은 내 말로 바꾸고 출처를 적어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L07_challenge#6','kor',6,1,'u2','L07','g6_1_kor_u2_L07_challenge','lesson_challenge','K6-1-u2-C29',3,'mc','auto','「도서관 책에 붙은 번호」의 「가운데」에 들어갈 내용으로 알맞지 않은 것은 어느 것인가요?',ARRAY['K6-1-u2-X12']::text[],false,'{"seq":6,"concept":"K6-1-u2-C29","difficulty":3,"kind":"mc","stem":"「도서관 책에 붙은 번호」의 「가운데」에 들어갈 내용으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"전체 내용을 간추리는 마지막 문장","correct":true},{"t":"숫자가 무엇을 나타내는지","mis":"K6-1-u2-X12"},{"t":"갈래를 나누는 방법의 예","mis":"K6-1-u2-X12"},{"t":"숫자로 책을 찾는 차례","mis":"K6-1-u2-X12"}],"explanation":["가운데에는 자세한 설명이 들어가요.","간추리는 문장은 끝에 들어가요.","처음 · 가운데 · 끝이 하는 일이 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L07_challenge#7','kor',6,1,'u2','L07','g6_1_kor_u2_L07_challenge','lesson_challenge','K6-1-u2-C30',3,'ox','auto','디지털 매체로 글을 쓸 때에는 보기 좋은 그림이면 내용과 상관없이 넣어도 돼요.',ARRAY['K6-1-u2-X43']::text[],false,'{"seq":7,"concept":"K6-1-u2-C30","difficulty":3,"kind":"ox","stem":"디지털 매체로 글을 쓸 때에는 보기 좋은 그림이면 내용과 상관없이 넣어도 돼요.","answer":"X","reason_options":[{"t":"넣는 그림은 글의 내용과 이어져야 흐름이 끊기지 않기 때문에","correct":true},{"t":"그림이 많을수록 좋은 글이기 때문에","mis":"K6-1-u2-X43"}],"mis":"K6-1-u2-X43","explanation":["그림도 글의 한 부분이에요.","아무거나 넣으면 흐름이 끊겨요.","내용과 이어지는 그림만 넣어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L07_challenge#8','kor',6,1,'u2','L07','g6_1_kor_u2_L07_challenge','lesson_challenge','K6-1-u2-C25',4,'mc','auto','다빈의 처음 문장과 고친 글을 견주어 알 수 있는 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u2-X33','K6-1-u2-X01','K6-1-u2-X35']::text[],false,'{"seq":8,"concept":"K6-1-u2-C25","difficulty":4,"kind":"mc","stem":"다빈의 처음 문장과 고친 글을 견주어 알 수 있는 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"문장을 나누고 겹치는 표현을 줄였더니 글자 수는 줄었는데 뜻은 더 또렷해졌다","correct":true},{"t":"문장이 길수록 뜻이 더 또렷해진다","mis":"K6-1-u2-X33"},{"t":"고친 글은 설명하는 내용이 달라졌다","mis":"K6-1-u2-X01"},{"t":"「번호」를 되풀이해야 뜻이 분명하다","mis":"K6-1-u2-X35"}],"explanation":["긴 문장은 한 번에 읽히지 않아요.","내용은 그대로예요.","나누고 줄이면 더 또렷해져요."],"asset":{"type":"passage","lines":["도서관에 가면 책등마다 숫자가 붙어 있습니다.","이 숫자는 책의 내용을 갈래별로 나눈 표시입니다.","숫자를 알면 넓은 서가에서도 찾는 책 앞으로 곧장 갈 수 있습니다."],"title":"다빈이 고친 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L07_challenge#9','kor',6,1,'u2','L07','g6_1_kor_u2_L07_challenge','lesson_challenge','K6-1-u2-C25',4,'essay','teacher','다빈이 처음 쓴 긴 문장을 명확한 문장의 세 가지 조건에 맞게 고쳐 쓰고, 어떤 조건을 지켰는지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-1-u2-C25","difficulty":4,"kind":"essay","stem":"다빈이 처음 쓴 긴 문장을 명확한 문장의 세 가지 조건에 맞게 고쳐 쓰고, 어떤 조건을 지켰는지 쓰세요.","answer_guide":{"answer":"예: 도서관 책에는 번호가 붙어 있습니다. 이 번호는 책의 내용을 갈래별로 나눈 표시입니다. 번호를 알면 책을 쉽게 찾을 수 있습니다. 그래서 도서관에서는 책마다 번호를 붙여 둡니다. — 한 문장에 한 가지만 담도록 넷으로 나누었고, 문장마다 주어와 서술어를 갖췄으며, 되풀이되던 「번호」를 「표시」로 바꾸어 겹치는 표현을 줄였다.","scoring_points":["긴 문장을 여러 문장으로 나누었는가","빠진 성분 없이 고쳐 썼는가","지킨 조건을 설명했는가"]},"explanation":["한 문장에 한 가지씩 나눠요.","필수 성분을 갖춰요.","겹치는 표현을 줄였는지 써요."],"asset":{"type":"passage","lines":["도서관에 가면 책마다 번호가 붙어 있는데 그 번호는 아무렇게나 붙인 번호가","아니라 책의 내용을 나누어 놓은 번호이고 그 번호를 알면 책을 찾기가","쉬워지는데 번호를 모르면 책을 찾기가 어렵고 그래서 도서관에서는","번호를 붙여 놓는 것입니다."],"title":"다빈이 처음 쓴 문장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L07_challenge#10','kor',6,1,'u2','L07','g6_1_kor_u2_L07_challenge','lesson_challenge','K6-1-u2-C30',4,'essay','teacher','설명하는 글을 쓸 때 찾은 자료를 어떻게 써야 하는지 세 가지를 쓰고, 그 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-1-u2-C30","difficulty":4,"kind":"essay","stem":"설명하는 글을 쓸 때 찾은 자료를 어떻게 써야 하는지 세 가지를 쓰고, 그 까닭을 쓰세요.","answer_guide":{"answer":"예: 첫째, 누가 언제 만들었는지 확인한 자료만 쓴다. 믿을 수 없거나 오래된 자료는 틀린 내용을 전할 수 있기 때문이다. 둘째, 읽고 이해한 뒤 내 말로 바꾸어 쓴다. 그대로 옮긴 문장은 내 글이 아니기 때문이다. 셋째, 가져온 곳을 함께 적는다. 다른 사람이 만든 자료이고 읽는 사람이 확인할 수 있어야 하기 때문이다.","scoring_points":["자료 확인에 대해 썼는가","내 말로 바꾸어 쓰기를 썼는가","출처 밝히기와 까닭을 썼는가"]},"explanation":["누가 · 언제를 확인해요.","내 말로 바꾸어 써요.","출처를 적는 까닭을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L09_basic#1','kor',6,1,'u2','L09','g6_1_kor_u2_L09_basic','lesson_basic','K6-1-u2-C31',1,'mc','auto','친구의 글을 읽을 때 가장 먼저 할 일은 무엇인가요?',ARRAY['K6-1-u2-X05','K6-1-u2-X06','K6-1-u2-X39']::text[],false,'{"seq":1,"concept":"K6-1-u2-C31","difficulty":1,"kind":"mc","stem":"친구의 글을 읽을 때 가장 먼저 할 일은 무엇인가요?","options":[{"t":"무슨 말을 하려는 글인지 한 줄로 잡는다","correct":true},{"t":"띄어쓰기가 틀린 곳부터 센다","mis":"K6-1-u2-X05"},{"t":"고칠 곳만 찾아 적는다","mis":"K6-1-u2-X06"},{"t":"글쓴이가 누구인지만 본다","mis":"K6-1-u2-X39"}],"explanation":["하려는 말을 알아야 고칠 곳도 보여요.","띄어쓰기는 마지막에 봐요.","먼저 하려는 말을 한 줄로 잡아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L09_basic#2','kor',6,1,'u2','L09','g6_1_kor_u2_L09_basic','lesson_basic','K6-1-u2-C31',1,'match','auto','친구의 말과 의견의 갈래를 이으세요.','{}'::text[],false,'{"seq":2,"concept":"K6-1-u2-C31","difficulty":1,"kind":"match","stem":"친구의 말과 의견의 갈래를 이으세요.","pairs":[{"l":"숫자에 뜻이 있는 줄 몰랐어","r":"새롭게 안 점"},{"l":"도서관마다 숫자가 같은지 궁금해","r":"궁금한 점"},{"l":"첫 문단이 짧아서 읽기 좋았어","r":"좋은 점"}],"mis":"K6-1-u2-X39","explanation":["몰랐던 것을 알게 되었어요.","더 알고 싶은 것이에요.","잘 쓴 곳과 까닭이에요."],"asset":{"type":"speech","turns":[{"who":"승아","text":"숫자에 뜻이 있는 줄 몰랐어."},{"who":"우진","text":"도서관마다 숫자가 같은지 궁금해."},{"who":"정후","text":"첫 문단이 짧아서 읽기 좋았어."},{"who":"승아","text":"의자 이야기는 빼면 좋겠어. 숫자 설명과 멀어 보여서."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L09_basic#3','kor',6,1,'u2','L09','g6_1_kor_u2_L09_basic','lesson_basic','K6-1-u2-C15',1,'mc','auto','다빈의 문단에서 빼야 할 문장은 어느 것인가요?',ARRAY['K6-1-u2-X15','K6-1-u2-X16']::text[],false,'{"seq":3,"concept":"K6-1-u2-C15","difficulty":1,"kind":"mc","stem":"다빈의 문단에서 빼야 할 문장은 어느 것인가요?","options":[{"t":"도서관 의자는 푹신합니다.","correct":true},{"t":"숫자를 알면 넓은 서가에서도 책을 빨리 찾을 수 있습니다.","mis":"K6-1-u2-X15"},{"t":"같은 갈래의 책은 한곳에 모여 있습니다.","mis":"K6-1-u2-X15"},{"t":"갈래는 크게 열개로 나뉩니다.","mis":"K6-1-u2-X16"}],"explanation":["이 문단의 중심 생각은 숫자로 책을 찾는 것이에요.","의자 이야기는 상관이 없어요.","「열개」는 빼지 말고 띄어 고쳐요."],"asset":{"type":"passage","lines":["숫자를 알면 넓은 서가에서도 책을 빨리 찾을 수 있습니다.","도서관 의자는 푹신합니다.","갈래는 크게 열개로 나뉘고, 같은 갈래의 책은 한곳에 모여 있습니다."],"title":"다빈의 글 「도서관 책에 붙은 번호」 한 문단"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L09_basic#4','kor',6,1,'u2','L09','g6_1_kor_u2_L09_basic','lesson_basic','K6-1-u2-C32',1,'ox','auto','친구가 말한 의견은 모두 따라 고쳐야 해요.',ARRAY['K6-1-u2-X40']::text[],false,'{"seq":4,"concept":"K6-1-u2-C32","difficulty":1,"kind":"ox","stem":"친구가 말한 의견은 모두 따라 고쳐야 해요.","answer":"X","reason_options":[{"t":"의견은 받는 것이고 고르는 것은 글쓴이이기 때문에","correct":true},{"t":"친구가 글쓴이보다 글을 더 잘 알기 때문에","mis":"K6-1-u2-X40"}],"mis":"K6-1-u2-X40","explanation":["다빈은 책 목록 의견을 따르지 않았어요.","숫자를 설명하는 글이었기 때문이에요.","하려던 말에 도움이 되는 의견을 골라요."],"asset":{"type":"speech","turns":[{"who":"정후","text":"다빈아, 글 끝에 네가 좋아하는 책 목록도 넣으면 어때?"},{"who":"다빈","text":"고맙지만 이 글은 숫자를 설명하는 글이라 그건 안 넣기로 했어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L09_basic#5','kor',6,1,'u2','L09','g6_1_kor_u2_L09_basic','lesson_basic','K6-1-u2-C5',2,'mc','auto','다빈의 글에 남길 댓글로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u2-X06','K6-1-u2-X07','K6-1-u2-X08']::text[],false,'{"seq":5,"concept":"K6-1-u2-C5","difficulty":2,"kind":"mc","stem":"다빈의 글에 남길 댓글로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「숫자 설명이 쉬웠어. 의자 이야기는 주제와 멀어 보여서 빼면 좋겠어.」","correct":true},{"t":"「틀린 데가 너무 많아. 처음부터 다시 써야겠어.」","mis":"K6-1-u2-X06"},{"t":"「잘 썼네. 고칠 곳 하나도 없어.」","mis":"K6-1-u2-X07"},{"t":"「의자 이야기 빼.」","mis":"K6-1-u2-X08"}],"explanation":["다시 쓰라는 말은 위축시켜요.","막연한 칭찬은 쓸모가 적어요.","잘한 곳 → 고칠 곳 → 까닭 차례로 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L09_basic#6','kor',6,1,'u2','L09','g6_1_kor_u2_L09_basic','lesson_basic','K6-1-u2-C17',2,'mc','auto','다빈의 문단에서 「열개」를 바르게 고친 것은 어느 것인가요?',ARRAY['K6-1-u2-X25','K6-1-u2-X27','K6-1-u2-X23']::text[],false,'{"seq":6,"concept":"K6-1-u2-C17","difficulty":2,"kind":"mc","stem":"다빈의 문단에서 「열개」를 바르게 고친 것은 어느 것인가요?","options":[{"t":"열 개","correct":true},{"t":"열개","mis":"K6-1-u2-X25"},{"t":"열 개 로","mis":"K6-1-u2-X27"},{"t":"열⌒개","mis":"K6-1-u2-X23"}],"explanation":["「개」는 세는 말이에요.","수와 세는 말은 띄어 써요.","「열 개로」처럼 조사는 붙여요."],"asset":{"type":"passage","lines":["숫자를 알면 넓은 서가에서도 책을 빨리 찾을 수 있습니다.","도서관 의자는 푹신합니다.","갈래는 크게 열개로 나뉘고, 같은 갈래의 책은 한곳에 모여 있습니다."],"title":"다빈의 글 「도서관 책에 붙은 번호」 한 문단"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L09_basic#7','kor',6,1,'u2','L09','g6_1_kor_u2_L09_basic','lesson_basic','K6-1-u2-C33',2,'mc','auto','고쳐 쓴 글을 학급 게시판에 공유하는 차례로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u2-X41','K6-1-u2-X10']::text[],false,'{"seq":7,"concept":"K6-1-u2-C33","difficulty":2,"kind":"mc","stem":"고쳐 쓴 글을 학급 게시판에 공유하는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"마지막 글 올리기 → 올라갔는지 확인 → 친구 글에 댓글 → 내 글 댓글 읽고 다시 점검","correct":true},{"t":"글 올리기 → 끝","mis":"K6-1-u2-X41"},{"t":"댓글 달기 → 글 올리기 → 끝","mis":"K6-1-u2-X41"},{"t":"글 올리기 → 칭찬 기다리기","mis":"K6-1-u2-X10"}],"explanation":["올리고 끝내지 않아요.","제대로 올라갔는지 확인해요.","달린 댓글을 읽고 다시 점검해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L09_basic#8','kor',6,1,'u2','L09','g6_1_kor_u2_L09_basic','lesson_basic','K6-1-u2-C35',2,'ox','auto','글에 넣은 사진이 보기 좋아도 내용과 이어지지 않으면 빼는 것도 고쳐쓰기예요.',ARRAY['K6-1-u2-X43']::text[],false,'{"seq":8,"concept":"K6-1-u2-C35","difficulty":2,"kind":"ox","stem":"글에 넣은 사진이 보기 좋아도 내용과 이어지지 않으면 빼는 것도 고쳐쓰기예요.","answer":"O","reason_options":[{"t":"사진과 영상도 글의 한 부분이라 내용과 이어져야 하기 때문에","correct":true},{"t":"사진은 글이 아니라 고칠 필요가 없기 때문에","mis":"K6-1-u2-X43"}],"mis":"K6-1-u2-X43","explanation":["도서관 바깥 풍경은 숫자 설명과 이어지지 않아요.","책등 숫자가 보이는 서가 사진은 이어져요.","겉도는 자료는 빼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L09_basic#9','kor',6,1,'u2','L09','g6_1_kor_u2_L09_basic','lesson_basic','K6-1-u2-C34',2,'mc','auto','맞춤법 검사기를 쓸 때 알맞은 태도는 어느 것인가요?',ARRAY['K6-1-u2-X42','K6-1-u2-X41']::text[],false,'{"seq":9,"concept":"K6-1-u2-C34","difficulty":2,"kind":"mc","stem":"맞춤법 검사기를 쓸 때 알맞은 태도는 어느 것인가요?","options":[{"t":"도구가 고친 곳도 왜 그렇게 고쳤는지 확인하고 받아들인다","correct":true},{"t":"도구가 고친 대로 모두 받아들인다","mis":"K6-1-u2-X42"},{"t":"도구가 글의 중심 생각까지 정해 준다","mis":"K6-1-u2-X42"},{"t":"도구를 썼으니 다시 읽지 않는다","mis":"K6-1-u2-X41"}],"explanation":["까닭을 모르면 다음에도 똑같이 틀려요.","중심 생각은 도구가 정하지 못해요.","고칠지 말지는 글쓴이가 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L09_basic#10','kor',6,1,'u2','L09','g6_1_kor_u2_L09_basic','lesson_basic','K6-1-u2-C32',3,'mc','auto','다빈이 정후의 의견을 따르지 않은 것에 대해 알맞게 말한 것은 어느 것인가요?',ARRAY['K6-1-u2-X40','K6-1-u2-X41']::text[],false,'{"seq":10,"concept":"K6-1-u2-C32","difficulty":3,"kind":"mc","stem":"다빈이 정후의 의견을 따르지 않은 것에 대해 알맞게 말한 것은 어느 것인가요?","options":[{"t":"숫자를 설명하는 글이라 책 목록은 하려던 말을 흐리게 하므로 따르지 않은 까닭이 분명하다","correct":true},{"t":"친구 의견을 따르지 않았으니 예의가 없다","mis":"K6-1-u2-X40"},{"t":"정후의 의견이 틀렸으니 다시는 의견을 받지 않는다","mis":"K6-1-u2-X41"},{"t":"친구가 말하면 무조건 넣어야 한다","mis":"K6-1-u2-X40"}],"explanation":["의견을 고르는 것은 글쓴이예요.","기준은 하려던 말이 더 잘 전해지는가예요.","따르지 않은 까닭을 말할 수 있으면 돼요."],"asset":{"type":"speech","turns":[{"who":"정후","text":"다빈아, 글 끝에 네가 좋아하는 책 목록도 넣으면 어때?"},{"who":"다빈","text":"고맙지만 이 글은 숫자를 설명하는 글이라 그건 안 넣기로 했어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L09_challenge#1','kor',6,1,'u2','L09','g6_1_kor_u2_L09_challenge','lesson_challenge','K6-1-u2-C31',2,'mc','auto','「의자 이야기는 빼면 좋겠어. 숫자 설명과 멀어 보여서.」는 의견의 네 갈래 가운데 무엇인가요?',ARRAY['K6-1-u2-X39']::text[],false,'{"seq":1,"concept":"K6-1-u2-C31","difficulty":2,"kind":"mc","stem":"「의자 이야기는 빼면 좋겠어. 숫자 설명과 멀어 보여서.」는 의견의 네 갈래 가운데 무엇인가요?","options":[{"t":"고쳤으면 하는 점","correct":true},{"t":"새롭게 안 점","mis":"K6-1-u2-X39"},{"t":"궁금한 점","mis":"K6-1-u2-X39"},{"t":"좋은 점","mis":"K6-1-u2-X39"}],"explanation":["빼자고 말했어요.","까닭도 함께 말했어요.","고칠 곳과 까닭은 고쳤으면 하는 점이에요."],"asset":{"type":"speech","turns":[{"who":"승아","text":"숫자에 뜻이 있는 줄 몰랐어."},{"who":"우진","text":"도서관마다 숫자가 같은지 궁금해."},{"who":"정후","text":"첫 문단이 짧아서 읽기 좋았어."},{"who":"승아","text":"의자 이야기는 빼면 좋겠어. 숫자 설명과 멀어 보여서."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L09_challenge#2','kor',6,1,'u2','L09','g6_1_kor_u2_L09_challenge','lesson_challenge','K6-1-u2-C33',2,'mc','auto','승아의 댓글에 다빈이 단 답글에서 본받을 점은 무엇인가요?',ARRAY['K6-1-u2-X41','K6-1-u2-X06','K6-1-u2-X01']::text[],false,'{"seq":2,"concept":"K6-1-u2-C33","difficulty":2,"kind":"mc","stem":"승아의 댓글에 다빈이 단 답글에서 본받을 점은 무엇인가요?","options":[{"t":"읽었다는 것과 어떻게 고쳤는지를 알려 주었다","correct":true},{"t":"댓글을 읽고 아무 말도 하지 않았다","mis":"K6-1-u2-X41"},{"t":"승아의 의견이 틀렸다고 말했다","mis":"K6-1-u2-X06"},{"t":"의견을 듣고 글을 처음부터 다시 썼다","mis":"K6-1-u2-X01"}],"explanation":["댓글을 받고 끝내지 않았어요.","고마움을 표현했어요.","한 문장 더 넣어 고친 것을 알렸어요."],"asset":{"type":"speech","turns":[{"who":"승아","text":"도서관마다 숫자가 같은지 궁금하다고 했는데, 나도 그게 궁금했어."},{"who":"다빈","text":"알려 줘서 고마워. 그 부분을 한 문장 더 넣어서 고쳐 뒀어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L09_challenge#3','kor',6,1,'u2','L09','g6_1_kor_u2_L09_challenge','lesson_challenge','K6-1-u2-C32',3,'error','auto','친구 의견을 받아들이는 방법을 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-1-u2-X40']::text[],false,'{"seq":3,"concept":"K6-1-u2-C32","difficulty":3,"kind":"error","stem":"친구 의견을 받아들이는 방법을 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"하율 — 「친구가 말한 건 다 넣어야 해. 안 넣으면 미안하잖아.」","correct":true,"mis_target":"K6-1-u2-X40"},{"t":"서진 — 「이 의견을 따르면 내가 하려던 말이 더 잘 전해지는지 물어봐.」","mis":"K6-1-u2-X40"},{"t":"라온 — 「따르지 않기로 했으면 까닭을 말할 수 있으면 돼.」","mis":"K6-1-u2-X40"}],"explanation":["서진은 기준을 말했어요.","라온은 까닭을 말했어요.","하율은 의견을 모두 따라야 한다고 여겼어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L09_challenge#4','kor',6,1,'u2','L09','g6_1_kor_u2_L09_challenge','lesson_challenge','K6-1-u2-C10',3,'mc','auto','글을 공유하면 좋은 점으로 알맞지 않은 것은 어느 것인가요?',ARRAY['K6-1-u2-X10']::text[],false,'{"seq":4,"concept":"K6-1-u2-C10","difficulty":3,"kind":"mc","stem":"글을 공유하면 좋은 점으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"내 글이 무조건 칭찬받는다","correct":true},{"t":"혼자서는 놓친 곳을 알게 된다","mis":"K6-1-u2-X10"},{"t":"내 글이 어떻게 읽히는지 안다","mis":"K6-1-u2-X10"},{"t":"새로운 생각을 얻는다","mis":"K6-1-u2-X10"}],"explanation":["친구가 못 본 곳을 짚어 줘요.","읽는 사람의 반응을 알아요.","공유는 칭찬받으려는 일이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L09_challenge#5','kor',6,1,'u2','L09','g6_1_kor_u2_L09_challenge','lesson_challenge','K6-1-u2-C35',3,'match','auto','다빈의 글에 넣을 사진과 알맞은 판단을 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K6-1-u2-C35","difficulty":3,"kind":"match","stem":"다빈의 글에 넣을 사진과 알맞은 판단을 이으세요.","pairs":[{"l":"책등의 숫자가 보이는 서가 사진","r":"내용을 바로 보여 주니 넣는다"},{"l":"도서관 건물 바깥 풍경 사진","r":"설명과 이어지지 않으니 뺀다"},{"l":"남이 찍은 서가 사진","r":"넣으려면 출처를 밝힌다"}],"mis":"K6-1-u2-X43","explanation":["설명을 보여 주는 사진은 넣어요.","겉도는 사진은 빼요.","남의 사진은 출처를 밝혀요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L09_challenge#6','kor',6,1,'u2','L09','g6_1_kor_u2_L09_challenge','lesson_challenge','K6-1-u2-C34',3,'ox','auto','인공 지능 도구를 쓰면 고칠지 말지도 도구가 정해 줘요.',ARRAY['K6-1-u2-X42']::text[],false,'{"seq":6,"concept":"K6-1-u2-C34","difficulty":3,"kind":"ox","stem":"인공 지능 도구를 쓰면 고칠지 말지도 도구가 정해 줘요.","answer":"X","reason_options":[{"t":"도구는 띄어쓰기 · 맞춤법을 짚어 줄 뿐 고칠지 말지는 글쓴이가 정하기 때문에","correct":true},{"t":"도구가 글쓴이보다 언제나 옳기 때문에","mis":"K6-1-u2-X42"}],"mis":"K6-1-u2-X42","explanation":["도구는 빠르게 짚어 줘요.","중심 생각은 정해 주지 못해요.","까닭을 확인하고 글쓴이가 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L09_challenge#7','kor',6,1,'u2','L09','g6_1_kor_u2_L09_challenge','lesson_challenge','K6-1-u2-C31',3,'mc','auto','「그냥 좋아.」라고만 말하지 않고 네 갈래로 의견을 나누면 좋은 까닭은 무엇인가요?',ARRAY['K6-1-u2-X39','K6-1-u2-X06','K6-1-u2-X07']::text[],false,'{"seq":7,"concept":"K6-1-u2-C31","difficulty":3,"kind":"mc","stem":"「그냥 좋아.」라고만 말하지 않고 네 갈래로 의견을 나누면 좋은 까닭은 무엇인가요?","options":[{"t":"글쓴이가 어디를 살리고 어디를 손볼지 알 수 있는 쓸모 있는 말이 되기 때문에","correct":true},{"t":"의견이 길어져서 멋있어 보이기 때문에","mis":"K6-1-u2-X39"},{"t":"고칠 곳만 말하면 되기 때문에","mis":"K6-1-u2-X06"},{"t":"칭찬을 더 많이 할 수 있기 때문에","mis":"K6-1-u2-X07"}],"explanation":["막연한 말은 도움이 적어요.","네 갈래는 글쓴이에게 쓸모가 있어요.","살릴 곳과 손볼 곳이 보여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L09_challenge#8','kor',6,1,'u2','L09','g6_1_kor_u2_L09_challenge','lesson_challenge','K6-1-u2-C33',4,'mc','auto','다빈의 글이 공유되고 나서 생긴 일을 가장 알맞게 평가한 것은 어느 것인가요?',ARRAY['K6-1-u2-X40','K6-1-u2-X10','K6-1-u2-X01']::text[],false,'{"seq":8,"concept":"K6-1-u2-C33","difficulty":4,"kind":"mc","stem":"다빈의 글이 공유되고 나서 생긴 일을 가장 알맞게 평가한 것은 어느 것인가요?","options":[{"t":"승아의 궁금한 점을 받아 한 문장을 더 넣고, 정후의 의견은 까닭을 들어 넣지 않아 하려던 말이 더 또렷해졌다","correct":true},{"t":"친구 의견을 하나라도 따르지 않았으니 공유가 실패했다","mis":"K6-1-u2-X40"},{"t":"공유한 뒤에는 더 고치지 않는 것이 맞다","mis":"K6-1-u2-X10"},{"t":"댓글을 읽은 뒤 글을 처음부터 다시 쓴 것이 가장 좋다","mis":"K6-1-u2-X01"}],"explanation":["의견을 골라 받아들였어요.","공유한 뒤 다시 점검했어요.","필요한 곳만 고쳤어요."],"asset":{"type":"speech","turns":[{"who":"승아","text":"도서관마다 숫자가 같은지 궁금하다고 했는데, 나도 그게 궁금했어."},{"who":"다빈","text":"알려 줘서 고마워. 그 부분을 한 문장 더 넣어서 고쳐 뒀어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L09_challenge#9','kor',6,1,'u2','L09','g6_1_kor_u2_L09_challenge','lesson_challenge','K6-1-u2-C31',4,'essay','teacher','다빈의 글 「도서관 책에 붙은 번호」를 읽었다고 생각하고, 의견의 네 갈래(새롭게 안 점 · 궁금한 점 · 좋은 점 · 고쳤으면 하는 점)로 의견을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-1-u2-C31","difficulty":4,"kind":"essay","stem":"다빈의 글 「도서관 책에 붙은 번호」를 읽었다고 생각하고, 의견의 네 갈래(새롭게 안 점 · 궁금한 점 · 좋은 점 · 고쳤으면 하는 점)로 의견을 쓰세요.","answer_guide":{"answer":"예: 새롭게 안 점 — 책등의 숫자가 책의 갈래를 나타낸다는 것을 처음 알았어. 궁금한 점 — 학교 도서관과 동네 도서관의 숫자도 같은지 궁금해. 좋은 점 — 문장이 짧아서 한 번에 읽혔어. 고쳤으면 하는 점 — 의자가 푹신하다는 문장은 숫자 설명과 멀어 보여서 빼면 좋겠어.","scoring_points":["네 갈래를 모두 썼는가","갈래에 맞는 내용을 썼는가","좋은 점과 고칠 점에 까닭을 붙였는가"]},"explanation":["네 갈래를 떠올려요.","갈래마다 알맞은 말을 써요.","까닭을 붙여요."],"asset":{"type":"passage","lines":["숫자를 알면 넓은 서가에서도 책을 빨리 찾을 수 있습니다.","도서관 의자는 푹신합니다.","갈래는 크게 열개로 나뉘고, 같은 갈래의 책은 한곳에 모여 있습니다."],"title":"다빈의 글 「도서관 책에 붙은 번호」 한 문단"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L09_challenge#10','kor',6,1,'u2','L09','g6_1_kor_u2_L09_challenge','lesson_challenge','K6-1-u2-C32',4,'essay','teacher','친구에게 받은 의견을 받아들일지 정하는 기준을 쓰고, 다빈이 정후의 의견을 따르지 않은 것이 알맞은지 까닭을 들어 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-1-u2-C32","difficulty":4,"kind":"essay","stem":"친구에게 받은 의견을 받아들일지 정하는 기준을 쓰고, 다빈이 정후의 의견을 따르지 않은 것이 알맞은지 까닭을 들어 쓰세요.","answer_guide":{"answer":"예: 의견을 받아들일지는 「이 의견을 따르면 내가 하려던 말이 더 잘 전해지는가?」를 기준으로 정한다. 다빈의 글은 책등의 숫자가 무엇을 뜻하고 어떻게 책을 찾는지 설명하는 글이다. 좋아하는 책 목록을 넣으면 하려던 말과 멀어진다. 그래서 다빈이 고맙다고 말하고 따르지 않은 것은 알맞다.","scoring_points":["받아들이는 기준을 썼는가","다빈의 글이 하려는 말을 썼는가","알맞은지를 까닭과 함께 판단했는가"]},"explanation":["기준을 먼저 써요.","글이 하려는 말과 견주어요.","까닭을 들어 판단해요."],"asset":{"type":"speech","turns":[{"who":"정후","text":"다빈아, 글 끝에 네가 좋아하는 책 목록도 넣으면 어때?"},{"who":"다빈","text":"고맙지만 이 글은 숫자를 설명하는 글이라 그건 안 넣기로 했어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L12_basic#1','kor',6,1,'u2','L12','g6_1_kor_u2_L12_basic','lesson_basic','K6-1-u2-C36',1,'mc','auto','소개하는 글로 쓰기에 알맞은 주제는 어느 것인가요?',ARRAY['K6-1-u2-X36']::text[],false,'{"seq":1,"concept":"K6-1-u2-C36","difficulty":1,"kind":"mc","stem":"소개하는 글로 쓰기에 알맞은 주제는 어느 것인가요?","options":[{"t":"삼 년째 타고 있는 내 낡은 자전거","correct":true},{"t":"세상에 있는 모든 운동","mis":"K6-1-u2-X36"},{"t":"어제 급식에 나온 반찬 이름","mis":"K6-1-u2-X36"},{"t":"우주에 있는 모든 별","mis":"K6-1-u2-X36"}],"explanation":["너무 넓으면 무엇부터 쓸지 몰라요.","너무 좁으면 쓸 말이 없어요.","쓸 말이 세 문단쯤 나오는 것을 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L12_basic#2','kor',6,1,'u2','L12','g6_1_kor_u2_L12_basic','lesson_basic','K6-1-u2-C36',1,'match','auto','소개하는 글의 문장이 들어갈 곳을 이으세요.','{}'::text[],false,'{"seq":2,"concept":"K6-1-u2-C36","difficulty":1,"kind":"match","stem":"소개하는 글의 문장이 들어갈 곳을 이으세요.","pairs":[{"l":"내가 가장 아끼는 물건은 낡은 자전거이다","r":"처음"},{"l":"손잡이 고무가 닳아 손 모양대로 파여 있다","r":"가운데"},{"l":"고쳐 가며 더 오래 타고 싶다","r":"끝"}],"mis":"K6-1-u2-X12","explanation":["무엇을 소개할지는 처음에 밝혀요.","자세한 모습은 가운데에 써요.","앞으로 하고 싶은 일은 끝에 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L12_basic#3','kor',6,1,'u2','L12','g6_1_kor_u2_L12_basic','lesson_basic','K6-1-u2-C37',1,'mc','auto','소개 문장으로 더 좋은 것은 어느 것인가요?',ARRAY['K6-1-u2-X44','K6-1-u2-X45']::text[],false,'{"seq":3,"concept":"K6-1-u2-C37","difficulty":1,"kind":"mc","stem":"소개 문장으로 더 좋은 것은 어느 것인가요?","options":[{"t":"체인이 늘어나 언덕에서 한 번씩 헛돌지만 손보면 다시 잘 간다","correct":true},{"t":"내 자전거가 세상에서 제일 좋은 자전거다","mis":"K6-1-u2-X44"},{"t":"자전거는 바퀴가 두 개인 탈것이다","mis":"K6-1-u2-X45"},{"t":"내 자전거는 정말 정말 멋지다","mis":"K6-1-u2-X44"}],"explanation":["자랑은 읽는 사람이 알 수 있는 것이 없어요.","누구에게나 있는 말은 소개가 아니에요.","그려 볼 수 있게 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L12_basic#4','kor',6,1,'u2','L12','g6_1_kor_u2_L12_basic','lesson_basic','K6-1-u2-C38',1,'mc','auto','「어제」와 어울리는 서술어는 어느 것인가요?',ARRAY['K6-1-u2-X20']::text[],false,'{"seq":4,"concept":"K6-1-u2-C38","difficulty":1,"kind":"mc","stem":"「어제」와 어울리는 서술어는 어느 것인가요?","options":[{"t":"보았다","correct":true},{"t":"볼 것이다","mis":"K6-1-u2-X20"},{"t":"본다","mis":"K6-1-u2-X20"},{"t":"보겠다","mis":"K6-1-u2-X20"}],"explanation":["어제는 지난 때예요.","지난 때에는 「~았다」를 써요.","「어제 보았다」로 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L12_basic#5','kor',6,1,'u2','L12','g6_1_kor_u2_L12_basic','lesson_basic','K6-1-u2-C18',2,'mc','auto','청아의 초고 「아버지가 이 자전거를 나에게 물려줬다.」를 바르게 고친 것은 어느 것인가요?',ARRAY['K6-1-u2-X20','K6-1-u2-X17','K6-1-u2-X34']::text[],false,'{"seq":5,"concept":"K6-1-u2-C18","difficulty":2,"kind":"mc","stem":"청아의 초고 「아버지가 이 자전거를 나에게 물려줬다.」를 바르게 고친 것은 어느 것인가요?","options":[{"t":"아버지께서 이 자전거를 나에게 물려주셨다.","correct":true},{"t":"아버지가 이 자전거를 나에게 물려준다.","mis":"K6-1-u2-X20"},{"t":"아버지를 이 자전거가 나에게 물려줬다.","mis":"K6-1-u2-X17"},{"t":"이 자전거를 나에게 물려줬다.","mis":"K6-1-u2-X34"}],"explanation":["아버지는 웃어른이에요.","높임 표현으로 받아요.","께서 · ~셨다로 고쳐요."],"asset":{"type":"passage","lines":["내가 가장 아끼는 물건은 자전거이다. 삼년째 타고 있어서 손잡이 고무가","손 모양대로 닳았다. 아버지가 이 자전거를 나에게 물려줬다.","우리 언니는 자전거를 못 탄다.","비 오는 날에는 마루에 들여놓고 마른 천으로 닦아 둔다."],"title":"청아가 쓴 초고 「내 낡은 자전거」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L12_basic#6','kor',6,1,'u2','L12','g6_1_kor_u2_L12_basic','lesson_basic','K6-1-u2-C15',2,'mc','auto','청아의 초고에서 빼야 할 문장은 어느 것인가요?',ARRAY['K6-1-u2-X15','K6-1-u2-X14']::text[],false,'{"seq":6,"concept":"K6-1-u2-C15","difficulty":2,"kind":"mc","stem":"청아의 초고에서 빼야 할 문장은 어느 것인가요?","options":[{"t":"우리 언니는 자전거를 못 탄다.","correct":true},{"t":"손잡이 고무가 손 모양대로 닳았다.","mis":"K6-1-u2-X15"},{"t":"비 오는 날에는 마루에 들여놓고 마른 천으로 닦아 둔다.","mis":"K6-1-u2-X15"},{"t":"내가 가장 아끼는 물건은 자전거이다.","mis":"K6-1-u2-X14"}],"explanation":["글의 중심은 내 자전거예요.","언니 이야기는 내 자전거와 상관없어요.","벗어난 문장은 빼요."],"asset":{"type":"passage","lines":["내가 가장 아끼는 물건은 자전거이다. 삼년째 타고 있어서 손잡이 고무가","손 모양대로 닳았다. 아버지가 이 자전거를 나에게 물려줬다.","우리 언니는 자전거를 못 탄다.","비 오는 날에는 마루에 들여놓고 마른 천으로 닦아 둔다."],"title":"청아가 쓴 초고 「내 낡은 자전거」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L12_basic#7','kor',6,1,'u2','L12','g6_1_kor_u2_L12_basic','lesson_basic','K6-1-u2-C39',2,'blank','auto','「바람에 창문이 (  ).」의 빈칸에 알맞은 말은 어느 것인가요?',ARRAY['K6-1-u2-X47','K6-1-u2-X19','K6-1-u2-X20']::text[],false,'{"seq":7,"concept":"K6-1-u2-C39","difficulty":2,"kind":"blank","stem":"「바람에 창문이 (  ).」의 빈칸에 알맞은 말은 어느 것인가요?","options":[{"t":"닫혔다","correct":true},{"t":"닫았다","mis":"K6-1-u2-X47"},{"t":"닫혀 주었다","mis":"K6-1-u2-X19"},{"t":"닫을 것이다","mis":"K6-1-u2-X20"}],"explanation":["창문은 스스로 닫지 않아요.","바람이라는 다른 힘에 의해 닫혔어요.","당하는 말 「닫혔다」를 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L12_basic#8','kor',6,1,'u2','L12','g6_1_kor_u2_L12_basic','lesson_basic','K6-1-u2-C38',2,'mc','auto','「화면이 어둠으로 채웠고」를 바르게 고친 것은 어느 것인가요?',ARRAY['K6-1-u2-X20','K6-1-u2-X34','K6-1-u2-X18']::text[],false,'{"seq":8,"concept":"K6-1-u2-C38","difficulty":2,"kind":"mc","stem":"「화면이 어둠으로 채웠고」를 바르게 고친 것은 어느 것인가요?","options":[{"t":"화면이 어둠으로 채워졌고","correct":true},{"t":"화면이 어둠으로 채울 것이고","mis":"K6-1-u2-X20"},{"t":"화면을 어둠으로 채웠고","mis":"K6-1-u2-X34"},{"t":"화면께서 어둠으로 채우셨고","mis":"K6-1-u2-X18"}],"explanation":["화면은 스스로 채운 것이 아니에요.","다른 힘에 의해 채워졌어요.","「채워졌고」로 받아요."],"asset":{"type":"passage","lines":["나는 어제 나무의 하루를 담은 다큐멘터리를 볼 것이다. 카메라는 한 그루의","나무를 일 년 동안 따라간다. 밤이 되면 나무가 낮에 만든 양분을 줄기 끝으로","보낸다는 사실을 처음 알았다.","가장 놀라운 곳은 뿌리 장면이었다. 화면이 어둠으로 채웠고, 그 속에서 뿌리가","물길을 따라 천천히 뻗어 갔다. 내 생각은 눈에 보이는 것만으로 판단하면 안 된다.","나무가 자란다는 말이 낮에만 해당하는 줄 알았다. 앞으로는 보이지 않는 곳에서","일어나는 일도 함께 헤아려 보고 싶다."],"title":"감상문 「밤에도 자라는 나무」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L12_basic#9','kor',6,1,'u2','L12','g6_1_kor_u2_L12_basic','lesson_basic','K6-1-u2-C24',2,'ox','auto','고쳐쓰기는 맞춤법을 바로잡고 낱말 몇 개를 바꾸는 일이에요.',ARRAY['K6-1-u2-X05']::text[],false,'{"seq":9,"concept":"K6-1-u2-C24","difficulty":2,"kind":"ox","stem":"고쳐쓰기는 맞춤법을 바로잡고 낱말 몇 개를 바꾸는 일이에요.","answer":"X","reason_options":[{"t":"주제에서 벗어난 문단 빼기 · 문단 차례 옮기기 · 부족한 설명 더하기까지 해야 하기 때문에","correct":true},{"t":"맞춤법이 글에서 가장 중요하기 때문에","mis":"K6-1-u2-X05"}],"mis":"K6-1-u2-X05","explanation":["맞춤법만 고치면 멈추기 쉬워요.","글 · 문단을 먼저 봐야 해요.","맞춤법과 띄어쓰기는 마지막에 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L12_basic#10','kor',6,1,'u2','L12','g6_1_kor_u2_L12_basic','lesson_basic','K6-1-u2-C37',3,'mc','auto','친구의 소개하는 글에 의견을 줄 때 알맞은 방법은 어느 것인가요?',ARRAY['K6-1-u2-X06','K6-1-u2-X07','K6-1-u2-X44']::text[],false,'{"seq":10,"concept":"K6-1-u2-C37","difficulty":3,"kind":"mc","stem":"친구의 소개하는 글에 의견을 줄 때 알맞은 방법은 어느 것인가요?","options":[{"t":"잘한 곳을 짚어 주고, 부족한 곳은 까닭과 함께 알려 준다","correct":true},{"t":"부족한 곳만 빠짐없이 적어 준다","mis":"K6-1-u2-X06"},{"t":"제일 좋다고만 말해 준다","mis":"K6-1-u2-X07"},{"t":"내 자전거가 더 좋다고 말한다","mis":"K6-1-u2-X44"}],"explanation":["고칠 곳만 늘어놓으면 위축돼요.","막연한 칭찬은 쓸모가 적어요.","주고받으며 글이 조금씩 나아져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L12_challenge#1','kor',6,1,'u2','L12','g6_1_kor_u2_L12_challenge','lesson_challenge','K6-1-u2-C17',2,'mc','auto','청아의 초고에서 「삼년째」를 바르게 고친 것은 어느 것인가요?',ARRAY['K6-1-u2-X25','K6-1-u2-X27','K6-1-u2-X23']::text[],false,'{"seq":1,"concept":"K6-1-u2-C17","difficulty":2,"kind":"mc","stem":"청아의 초고에서 「삼년째」를 바르게 고친 것은 어느 것인가요?","options":[{"t":"삼 년째","correct":true},{"t":"삼년 째","mis":"K6-1-u2-X25"},{"t":"삼 년 째","mis":"K6-1-u2-X27"},{"t":"삼⌒년째","mis":"K6-1-u2-X23"}],"explanation":["「년」은 세는 말이에요.","수와 세는 말은 띄어요.","「째」는 앞말에 붙여 써요."],"asset":{"type":"passage","lines":["내가 가장 아끼는 물건은 자전거이다. 삼년째 타고 있어서 손잡이 고무가","손 모양대로 닳았다. 아버지가 이 자전거를 나에게 물려줬다.","우리 언니는 자전거를 못 탄다.","비 오는 날에는 마루에 들여놓고 마른 천으로 닦아 둔다."],"title":"청아가 쓴 초고 「내 낡은 자전거」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L12_challenge#2','kor',6,1,'u2','L12','g6_1_kor_u2_L12_challenge','lesson_challenge','K6-1-u2-C39',2,'blank','auto','「내가 못을 박고 그림을 (  ).」의 빈칸에 알맞은 말은 어느 것인가요?',ARRAY['K6-1-u2-X47','K6-1-u2-X20']::text[],false,'{"seq":2,"concept":"K6-1-u2-C39","difficulty":2,"kind":"blank","stem":"「내가 못을 박고 그림을 (  ).」의 빈칸에 알맞은 말은 어느 것인가요?","options":[{"t":"걸었다","correct":true},{"t":"걸렸다","mis":"K6-1-u2-X47"},{"t":"걸려 있었다","mis":"K6-1-u2-X47"},{"t":"걸 것이다","mis":"K6-1-u2-X20"}],"explanation":["내가 스스로 한 일이에요.","스스로 하는 일에는 -리-를 붙이지 않아요.","「걸었다」로 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L12_challenge#3','kor',6,1,'u2','L12','g6_1_kor_u2_L12_challenge','lesson_challenge','K6-1-u2-C38',3,'error','auto','「밤에도 자라는 나무」의 문장을 고쳤어요. 알맞지 않게 고친 친구는 누구인가요?',ARRAY['K6-1-u2-X20','K6-1-u2-X46']::text[],false,'{"seq":3,"concept":"K6-1-u2-C38","difficulty":3,"kind":"error","stem":"「밤에도 자라는 나무」의 문장을 고쳤어요. 알맞지 않게 고친 친구는 누구인가요?","options":[{"t":"하율 — 「나는 어제 다큐멘터리를 본다.」","correct":true,"mis_target":"K6-1-u2-X20"},{"t":"서진 — 「내 생각은 눈에 보이는 것만으로 판단하면 안 된다는 것이다.」","mis":"K6-1-u2-X46"},{"t":"라온 — 「화면이 어둠으로 채워졌다.」","mis":"K6-1-u2-X46"}],"explanation":["서진은 주어와 서술어 짝을 맞췄어요.","라온은 당하는 말로 받았어요.","하율은 어제와 서술어의 때가 여전히 어긋나요."],"asset":{"type":"passage","lines":["나는 어제 나무의 하루를 담은 다큐멘터리를 볼 것이다. 카메라는 한 그루의","나무를 일 년 동안 따라간다. 밤이 되면 나무가 낮에 만든 양분을 줄기 끝으로","보낸다는 사실을 처음 알았다.","가장 놀라운 곳은 뿌리 장면이었다. 화면이 어둠으로 채웠고, 그 속에서 뿌리가","물길을 따라 천천히 뻗어 갔다. 내 생각은 눈에 보이는 것만으로 판단하면 안 된다.","나무가 자란다는 말이 낮에만 해당하는 줄 알았다. 앞으로는 보이지 않는 곳에서","일어나는 일도 함께 헤아려 보고 싶다."],"title":"감상문 「밤에도 자라는 나무」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L12_challenge#4','kor',6,1,'u2','L12','g6_1_kor_u2_L12_challenge','lesson_challenge','K6-1-u2-C38',3,'mc','auto','「내 생각은 눈에 보이는 것만으로 판단하면 안 된다.」가 어색한 까닭은 무엇인가요?',ARRAY['K6-1-u2-X20','K6-1-u2-X18','K6-1-u2-X05']::text[],false,'{"seq":4,"concept":"K6-1-u2-C38","difficulty":3,"kind":"mc","stem":"「내 생각은 눈에 보이는 것만으로 판단하면 안 된다.」가 어색한 까닭은 무엇인가요?","options":[{"t":"주어 「내 생각은」과 서술어 「안 된다」가 짝이 맞지 않아서","correct":true},{"t":"시간을 나타내는 말이 없어서","mis":"K6-1-u2-X20"},{"t":"높임 표현을 쓰지 않아서","mis":"K6-1-u2-X18"},{"t":"띄어쓰기가 틀려서","mis":"K6-1-u2-X05"}],"explanation":["주어가 「내 생각은」이에요.","서술어는 「~것이다」로 받아야 해요.","주어와 서술어의 짝을 맞춰요."],"asset":{"type":"passage","lines":["나는 어제 나무의 하루를 담은 다큐멘터리를 볼 것이다. 카메라는 한 그루의","나무를 일 년 동안 따라간다. 밤이 되면 나무가 낮에 만든 양분을 줄기 끝으로","보낸다는 사실을 처음 알았다.","가장 놀라운 곳은 뿌리 장면이었다. 화면이 어둠으로 채웠고, 그 속에서 뿌리가","물길을 따라 천천히 뻗어 갔다. 내 생각은 눈에 보이는 것만으로 판단하면 안 된다.","나무가 자란다는 말이 낮에만 해당하는 줄 알았다. 앞으로는 보이지 않는 곳에서","일어나는 일도 함께 헤아려 보고 싶다."],"title":"감상문 「밤에도 자라는 나무」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L12_challenge#5','kor',6,1,'u2','L12','g6_1_kor_u2_L12_challenge','lesson_challenge','K6-1-u2-C39',3,'match','auto','상황에 알맞은 표현을 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K6-1-u2-C39","difficulty":3,"kind":"match","stem":"상황에 알맞은 표현을 이으세요.","pairs":[{"l":"내가 손으로 창문을","r":"닫았다"},{"l":"언제부터인가 벽에 그림이","r":"걸려 있었다"},{"l":"나는 책상 위에 책을","r":"놓았다"}],"mis":"K6-1-u2-X47","explanation":["내가 스스로 한 일은 주동이에요.","저절로 그리 된 것은 피동이에요.","누가 한 일인지 물어봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L12_challenge#6','kor',6,1,'u2','L12','g6_1_kor_u2_L12_challenge','lesson_challenge','K6-1-u2-C36',3,'mc','auto','청아의 소개하는 글 「가운데」에 넣기 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u2-X45','K6-1-u2-X15','K6-1-u2-X44']::text[],false,'{"seq":6,"concept":"K6-1-u2-C36","difficulty":3,"kind":"mc","stem":"청아의 소개하는 글 「가운데」에 넣기 가장 알맞은 것은 어느 것인가요?","options":[{"t":"비 오는 날마다 마루에 들여놓고 마른 천으로 닦아 두는 이야기","correct":true},{"t":"자전거는 바퀴가 두 개라는 설명","mis":"K6-1-u2-X45"},{"t":"언니가 자전거를 못 탄다는 이야기","mis":"K6-1-u2-X15"},{"t":"내 자전거가 제일 좋다는 말","mis":"K6-1-u2-X44"}],"explanation":["누구의 자전거에나 있는 말은 소개가 아니에요.","상관없는 이야기는 빼요.","그것만의 이야기를 넣어요."],"asset":{"type":"passage","lines":["내가 가장 아끼는 물건은 자전거이다. 삼년째 타고 있어서 손잡이 고무가","손 모양대로 닳았다. 아버지가 이 자전거를 나에게 물려줬다.","우리 언니는 자전거를 못 탄다.","비 오는 날에는 마루에 들여놓고 마른 천으로 닦아 둔다."],"title":"청아가 쓴 초고 「내 낡은 자전거」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L12_challenge#7','kor',6,1,'u2','L12','g6_1_kor_u2_L12_challenge','lesson_challenge','K6-1-u2-C37',3,'ox','auto','소개하는 글은 내가 가진 것이 얼마나 좋은지 자랑하는 글이에요.',ARRAY['K6-1-u2-X44']::text[],false,'{"seq":7,"concept":"K6-1-u2-C37","difficulty":3,"kind":"ox","stem":"소개하는 글은 내가 가진 것이 얼마나 좋은지 자랑하는 글이에요.","answer":"X","reason_options":[{"t":"읽는 사람이 그려 볼 수 있게 어떤 것인지와 나와 얽힌 이야기를 알려 주는 글이기 때문에","correct":true},{"t":"자랑을 많이 할수록 소개가 잘되기 때문에","mis":"K6-1-u2-X44"}],"mis":"K6-1-u2-X44","explanation":["「제일 좋다」로는 알 수 있는 것이 없어요.","어떤 모습인지 자세히 써요.","읽는 사람이 그려 볼 수 있게 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L12_challenge#8','kor',6,1,'u2','L12','g6_1_kor_u2_L12_challenge','lesson_challenge','K6-1-u2-C24',4,'mc','auto','청아의 초고를 고치는 계획으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u2-X05','K6-1-u2-X03','K6-1-u2-X01']::text[],false,'{"seq":8,"concept":"K6-1-u2-C24","difficulty":4,"kind":"mc","stem":"청아의 초고를 고치는 계획으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"언니 문장을 빼고, 「삼 년째」로 띄어 쓰고, 「아버지께서 물려주셨다」로 높임을 맞춘다","correct":true},{"t":"「삼 년째」 띄어쓰기만 고친다","mis":"K6-1-u2-X05"},{"t":"언니 문장을 맨 끝으로 옮긴다","mis":"K6-1-u2-X03"},{"t":"글을 다 지우고 다른 물건을 소개한다","mis":"K6-1-u2-X01"}],"explanation":["띄어쓰기만 고치면 부족해요.","벗어난 문장은 옮기지 않고 빼요.","세 수준을 고르게 고쳐요."],"asset":{"type":"passage","lines":["내가 가장 아끼는 물건은 자전거이다. 삼년째 타고 있어서 손잡이 고무가","손 모양대로 닳았다. 아버지가 이 자전거를 나에게 물려줬다.","우리 언니는 자전거를 못 탄다.","비 오는 날에는 마루에 들여놓고 마른 천으로 닦아 둔다."],"title":"청아가 쓴 초고 「내 낡은 자전거」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L12_challenge#9','kor',6,1,'u2','L12','g6_1_kor_u2_L12_challenge','lesson_challenge','K6-1-u2-C36',4,'essay','teacher','내가 관심 있는 것 하나를 골라 처음 · 가운데 · 끝의 짜임으로 소개하는 글을 짧게 쓰고, 가운데에 넣은 「그것만의 이야기」가 무엇인지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-1-u2-C36","difficulty":4,"kind":"essay","stem":"내가 관심 있는 것 하나를 골라 처음 · 가운데 · 끝의 짜임으로 소개하는 글을 짧게 쓰고, 가운데에 넣은 「그것만의 이야기」가 무엇인지 쓰세요.","answer_guide":{"answer":"예: 처음 — 내가 소개할 것은 할머니께서 떠 주신 털모자이다. 겨울마다 가장 먼저 찾는 물건이라 골랐다. 가운데 — 모자 꼭대기의 방울은 한쪽이 조금 작다. 할머니께서 실이 모자라 남은 실로 마저 만드셨기 때문이다. 그래서 나는 이 모자를 쓰면 할머니가 생각난다. 끝 — 올겨울에도 이 모자를 아껴 쓰고, 해진 곳은 직접 꿰매 보고 싶다. 그것만의 이야기 — 한쪽이 작은 방울에 얽힌 이야기.","scoring_points":["처음 · 가운데 · 끝의 짜임으로 썼는가","가운데에 그것만의 이야기를 넣었는가","자랑이 아니라 그려 볼 수 있게 썼는가"]},"explanation":["짜임에 맞춰 써요.","그것만의 이야기를 넣어요.","읽는 사람이 그려 볼 수 있게 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_L12_challenge#10','kor',6,1,'u2','L12','g6_1_kor_u2_L12_challenge','lesson_challenge','K6-1-u2-C38',4,'essay','teacher','「밤에도 자라는 나무」에서 호응이 어긋난 문장 세 개를 찾아 바르게 고치고, 각각 무엇이 어긋났는지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-1-u2-C38","difficulty":4,"kind":"essay","stem":"「밤에도 자라는 나무」에서 호응이 어긋난 문장 세 개를 찾아 바르게 고치고, 각각 무엇이 어긋났는지 쓰세요.","answer_guide":{"answer":"예: 「나는 어제 다큐멘터리를 볼 것이다」 → 「나는 어제 다큐멘터리를 보았다」 — 어제와 서술어의 때가 어긋났다. 「화면이 어둠으로 채웠고」 → 「화면이 어둠으로 채워졌고」 — 화면이 스스로 한 일이 아니어서 당하는 말로 받아야 한다. 「내 생각은 눈에 보이는 것만으로 판단하면 안 된다」 → 「내 생각은 눈에 보이는 것만으로 판단하면 안 된다는 것이다」 — 주어와 서술어의 짝이 어긋났다.","scoring_points":["어긋난 문장 세 개를 찾았는가","바르게 고쳐 썼는가","어긋난 까닭(때 · 피동 · 주어와 서술어 짝)을 썼는가"]},"explanation":["서술어를 짚어 앞말과 견주어요.","알맞게 고쳐 써요.","무엇이 어긋났는지 써요."],"asset":{"type":"passage","lines":["나는 어제 나무의 하루를 담은 다큐멘터리를 볼 것이다. 카메라는 한 그루의","나무를 일 년 동안 따라간다. 밤이 되면 나무가 낮에 만든 양분을 줄기 끝으로","보낸다는 사실을 처음 알았다.","가장 놀라운 곳은 뿌리 장면이었다. 화면이 어둠으로 채웠고, 그 속에서 뿌리가","물길을 따라 천천히 뻗어 갔다. 내 생각은 눈에 보이는 것만으로 판단하면 안 된다.","나무가 자란다는 말이 낮에만 해당하는 줄 알았다. 앞으로는 보이지 않는 곳에서","일어나는 일도 함께 헤아려 보고 싶다."],"title":"감상문 「밤에도 자라는 나무」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_a#1','kor',6,1,'u2','','g6_1_kor_u2_review_a','unit_review','K6-1-u2-C1',1,'mc','auto','쓴 글을 점검해 하고 싶은 말이 더 잘 전달되도록 필요한 곳만 손보는 일을 무엇이라고 하나요?',ARRAY['K6-1-u2-X01']::text[],false,'{"seq":1,"concept":"K6-1-u2-C1","difficulty":1,"kind":"mc","stem":"쓴 글을 점검해 하고 싶은 말이 더 잘 전달되도록 필요한 곳만 손보는 일을 무엇이라고 하나요?","options":[{"t":"고쳐쓰기","correct":true},{"t":"옮겨 쓰기","mis":"K6-1-u2-X01"},{"t":"다시 쓰기","mis":"K6-1-u2-X01"},{"t":"베껴 쓰기","mis":"K6-1-u2-X01"}],"explanation":["글씨를 옮기는 일이 아니에요.","처음부터 새로 쓰는 일도 아니에요.","필요한 곳만 손보는 일이 고쳐쓰기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_a#2','kor',6,1,'u2','','g6_1_kor_u2_review_a','unit_review','K6-1-u2-C3',1,'mc','auto','「주어와 서술어가 호응하는가」는 어느 수준에서 살필 일인가요?',ARRAY['K6-1-u2-X04']::text[],false,'{"seq":2,"concept":"K6-1-u2-C3","difficulty":1,"kind":"mc","stem":"「주어와 서술어가 호응하는가」는 어느 수준에서 살필 일인가요?","options":[{"t":"문장 수준","correct":true},{"t":"글 수준","mis":"K6-1-u2-X04"},{"t":"문단 수준","mis":"K6-1-u2-X04"},{"t":"제목 수준","mis":"K6-1-u2-X04"}],"explanation":["한 문장만 봐도 알 수 있어요.","글 전체를 볼 필요는 없어요.","문장 수준의 일이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_a#3','kor',6,1,'u2','','g6_1_kor_u2_review_a','unit_review','K6-1-u2-C17',1,'mc','auto','「책」 · 「세」 · 「권」을 바르게 띄어 쓴 것은 어느 것인가요?',ARRAY['K6-1-u2-X25','K6-1-u2-X24']::text[],false,'{"seq":3,"concept":"K6-1-u2-C17","difficulty":1,"kind":"mc","stem":"「책」 · 「세」 · 「권」을 바르게 띄어 쓴 것은 어느 것인가요?","options":[{"t":"책 세 권","correct":true},{"t":"책 세권","mis":"K6-1-u2-X25"},{"t":"책세 권","mis":"K6-1-u2-X24"},{"t":"책세권","mis":"K6-1-u2-X25"}],"explanation":["「권」은 세는 말이에요.","세는 말은 수와 띄어요.","책 ∨ 세 ∨ 권으로 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_a#4','kor',6,1,'u2','','g6_1_kor_u2_review_a','unit_review','K6-1-u2-C21',1,'mc','auto','본 것에 더해 내가 무엇을 느끼고 생각했는지 적는 글을 무엇이라고 하나요?',ARRAY['K6-1-u2-X30']::text[],false,'{"seq":4,"concept":"K6-1-u2-C21","difficulty":1,"kind":"mc","stem":"본 것에 더해 내가 무엇을 느끼고 생각했는지 적는 글을 무엇이라고 하나요?","options":[{"t":"감상문","correct":true},{"t":"줄거리 요약","mis":"K6-1-u2-X30"},{"t":"안내문","mis":"K6-1-u2-X30"},{"t":"일기 예보","mis":"K6-1-u2-X30"}],"explanation":["줄거리 요약은 일어난 일만 적어요.","안내문은 알리는 글이에요.","느끼고 생각한 것을 적는 글은 감상문이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_a#5','kor',6,1,'u2','','g6_1_kor_u2_review_a','unit_review','K6-1-u2-C26',1,'mc','auto','「책등에 붙어 있습니다.」에서 빠진 문장 성분은 무엇인가요?',ARRAY['K6-1-u2-X34']::text[],false,'{"seq":5,"concept":"K6-1-u2-C26","difficulty":1,"kind":"mc","stem":"「책등에 붙어 있습니다.」에서 빠진 문장 성분은 무엇인가요?","options":[{"t":"주어","correct":true},{"t":"목적어","mis":"K6-1-u2-X34"},{"t":"서술어","mis":"K6-1-u2-X34"},{"t":"빠진 것이 없다","mis":"K6-1-u2-X34"}],"explanation":["무엇이 붙어 있는지 없어요.","「무엇이」가 빠졌어요.","주어를 넣어야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_a#6','kor',6,1,'u2','','g6_1_kor_u2_review_a','unit_review','K6-1-u2-C28',1,'mc','auto','자료를 가져온 곳을 밝힌 것을 무엇이라고 하나요?',ARRAY['K6-1-u2-X37']::text[],false,'{"seq":6,"concept":"K6-1-u2-C28","difficulty":1,"kind":"mc","stem":"자료를 가져온 곳을 밝힌 것을 무엇이라고 하나요?","options":[{"t":"출처","correct":true},{"t":"제목","mis":"K6-1-u2-X37"},{"t":"줄거리","mis":"K6-1-u2-X37"},{"t":"댓글","mis":"K6-1-u2-X37"}],"explanation":["어디서 가져왔는지가 출처예요.","제목 · 줄거리와 달라요.","자료를 옮길 때 출처를 밝혀요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_a#7','kor',6,1,'u2','','g6_1_kor_u2_review_a','unit_review','K6-1-u2-C39',1,'mc','auto','다른 힘에 의해 그리 되는 일을 나타낸 말은 어느 것인가요?',ARRAY['K6-1-u2-X47']::text[],false,'{"seq":7,"concept":"K6-1-u2-C39","difficulty":1,"kind":"mc","stem":"다른 힘에 의해 그리 되는 일을 나타낸 말은 어느 것인가요?","options":[{"t":"문이 닫히다","correct":true},{"t":"내가 문을 닫다","mis":"K6-1-u2-X47"},{"t":"내가 그림을 걸다","mis":"K6-1-u2-X47"},{"t":"내가 책을 놓다","mis":"K6-1-u2-X47"}],"explanation":["「내가 ~다」는 스스로 한 일이에요.","문은 스스로 닫지 않아요.","「닫히다」는 다른 힘에 의해 그리 된 것이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_a#8','kor',6,1,'u2','','g6_1_kor_u2_review_a','unit_review','K6-1-u2-C6',1,'mc','auto','온라인 게시판에 글을 올릴 때 지킬 것으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u2-X09']::text[],false,'{"seq":8,"concept":"K6-1-u2-C6","difficulty":1,"kind":"mc","stem":"온라인 게시판에 글을 올릴 때 지킬 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"자료를 옮길 때 출처를 밝힌다","correct":true},{"t":"줄임말을 많이 쓴다","mis":"K6-1-u2-X09"},{"t":"은어를 써서 재미있게 쓴다","mis":"K6-1-u2-X09"},{"t":"남의 글을 이름 없이 옮긴다","mis":"K6-1-u2-X09"}],"explanation":["한 번 올린 글은 널리 퍼져요.","줄임말 · 은어 · 비속어를 쓰지 않아요.","출처를 밝혀요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_a#9','kor',6,1,'u2','','g6_1_kor_u2_review_a','unit_review','K6-1-u2-C15',2,'mc','auto','하린의 감상문 초고에서 빼야 할 문장은 어느 것인가요?',ARRAY['K6-1-u2-X15','K6-1-u2-X16']::text[],false,'{"seq":9,"concept":"K6-1-u2-C15","difficulty":2,"kind":"mc","stem":"하린의 감상문 초고에서 빼야 할 문장은 어느 것인가요?","options":[{"t":"우리 동네 놀이터에는 새 미끄럼틀이 생겼다.","correct":true},{"t":"손녀는 몇 번이나 배를 찢었지만 할머니는 한 번도 서두르지 않았다.","mis":"K6-1-u2-X15"},{"t":"배 두척을 강물에 띄우는 마지막 장면도 기억에 남는다.","mis":"K6-1-u2-X16"},{"t":"나도 동생에게 무엇을 가르쳐 줄 때 기다려 줄수 있는 사람이 되겠다.","mis":"K6-1-u2-X16"}],"explanation":["글의 중심은 연극 「종이배」예요.","놀이터 이야기는 상관없어요.","띄어쓰기가 틀린 문장은 빼지 말고 고쳐요."],"asset":{"type":"passage","lines":["가장 오래 남은 장면은 할머니가 손녀에게 종이배 접는 법을 가르치는 장면이다.","손녀는 몇 번이나 배를 찢었지만 할머니는 한 번도 서두르지 않았다.","우리 동네 놀이터에는 새 미끄럼틀이 생겼다.","할머니가 「천천히 접으면 물에 오래 뜬단다.」 하고 말했다. 나는 그 장면이 전혀 지루했다.","배 두척을 강물에 띄우는 마지막 장면도 기억에 남는다.","나도 동생에게 무엇을 가르쳐 줄 때 기다려 줄수 있는 사람이 되겠다.","지난 토요일 학교 강당에서 학부모 및학생이 함께 이 연극을 보았다."],"title":"하린이 쓴 연극 감상문 초고 「종이배 이야기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_a#10','kor',6,1,'u2','','g6_1_kor_u2_review_a','unit_review','K6-1-u2-C14',2,'mc','auto','하린의 초고에서 「할머니가 ~ 하고 말했다.」를 바르게 고친 것은 어느 것인가요?',ARRAY['K6-1-u2-X20','K6-1-u2-X17','K6-1-u2-X34']::text[],false,'{"seq":10,"concept":"K6-1-u2-C14","difficulty":2,"kind":"mc","stem":"하린의 초고에서 「할머니가 ~ 하고 말했다.」를 바르게 고친 것은 어느 것인가요?","options":[{"t":"할머니께서 ~ 하고 말씀하셨다.","correct":true},{"t":"할머니가 ~ 하고 말할 것이다.","mis":"K6-1-u2-X20"},{"t":"할머니를 ~ 하고 말했다.","mis":"K6-1-u2-X17"},{"t":"~ 하고 말했다.","mis":"K6-1-u2-X34"}],"explanation":["할머니는 웃어른이에요.","높임 표현으로 받아요.","께서 · 말씀하셨다로 고쳐요."],"asset":{"type":"passage","lines":["가장 오래 남은 장면은 할머니가 손녀에게 종이배 접는 법을 가르치는 장면이다.","손녀는 몇 번이나 배를 찢었지만 할머니는 한 번도 서두르지 않았다.","우리 동네 놀이터에는 새 미끄럼틀이 생겼다.","할머니가 「천천히 접으면 물에 오래 뜬단다.」 하고 말했다. 나는 그 장면이 전혀 지루했다.","배 두척을 강물에 띄우는 마지막 장면도 기억에 남는다.","나도 동생에게 무엇을 가르쳐 줄 때 기다려 줄수 있는 사람이 되겠다.","지난 토요일 학교 강당에서 학부모 및학생이 함께 이 연극을 보았다."],"title":"하린이 쓴 연극 감상문 초고 「종이배 이야기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_a#11','kor',6,1,'u2','','g6_1_kor_u2_review_a','unit_review','K6-1-u2-C18',2,'mc','auto','하린의 초고 「학부모 및학생」을 바르게 고친 것은 어느 것인가요?',ARRAY['K6-1-u2-X26','K6-1-u2-X24']::text[],false,'{"seq":11,"concept":"K6-1-u2-C18","difficulty":2,"kind":"mc","stem":"하린의 초고 「학부모 및학생」을 바르게 고친 것은 어느 것인가요?","options":[{"t":"학부모 및 학생","correct":true},{"t":"학부모및학생","mis":"K6-1-u2-X26"},{"t":"학부모및 학생","mis":"K6-1-u2-X26"},{"t":"학 부 모 및 학 생","mis":"K6-1-u2-X24"}],"explanation":["「및」은 잇는 말이에요.","앞뒤를 모두 띄어요.","학부모 ∨ 및 ∨ 학생으로 써요."],"asset":{"type":"passage","lines":["가장 오래 남은 장면은 할머니가 손녀에게 종이배 접는 법을 가르치는 장면이다.","손녀는 몇 번이나 배를 찢었지만 할머니는 한 번도 서두르지 않았다.","우리 동네 놀이터에는 새 미끄럼틀이 생겼다.","할머니가 「천천히 접으면 물에 오래 뜬단다.」 하고 말했다. 나는 그 장면이 전혀 지루했다.","배 두척을 강물에 띄우는 마지막 장면도 기억에 남는다.","나도 동생에게 무엇을 가르쳐 줄 때 기다려 줄수 있는 사람이 되겠다.","지난 토요일 학교 강당에서 학부모 및학생이 함께 이 연극을 보았다."],"title":"하린이 쓴 연극 감상문 초고 「종이배 이야기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_a#12','kor',6,1,'u2','','g6_1_kor_u2_review_a','unit_review','K6-1-u2-C5',2,'mc','auto','하린의 글에 달린 댓글 가운데 가장 알맞은 것은 누구의 댓글인가요?',ARRAY['K6-1-u2-X06','K6-1-u2-X07','K6-1-u2-X08']::text[],false,'{"seq":12,"concept":"K6-1-u2-C5","difficulty":2,"kind":"mc","stem":"하린의 글에 달린 댓글 가운데 가장 알맞은 것은 누구의 댓글인가요?","options":[{"t":"서준","correct":true},{"t":"도윤","mis":"K6-1-u2-X06"},{"t":"채아","mis":"K6-1-u2-X07"},{"t":"셋 다 알맞지 않다","mis":"K6-1-u2-X08"}],"explanation":["도윤은 다시 쓰라고 했어요.","채아는 막연하게 칭찬했어요.","서준은 잘한 곳 → 고칠 곳 → 까닭 차례로 썼어요."],"asset":{"type":"speech","turns":[{"who":"도윤","text":"틀린 데가 너무 많아. 처음부터 다시 써."},{"who":"채아","text":"잘 썼네. 고칠 곳 하나도 없어."},{"who":"서준","text":"할머니가 서두르지 않는 장면이 눈에 그려졌어. 놀이터 문장은 연극 이야기와 멀어 보여서 빼면 좋겠어."},{"who":"보미","text":"연극을 보게 된 이야기가 맨 끝에 있어서 조금 헷갈렸어. 맨 앞으로 옮기면 어때?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_a#13','kor',6,1,'u2','','g6_1_kor_u2_review_a','unit_review','K6-1-u2-C32',2,'mc','auto','하린이 지호의 의견을 넣지 않은 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u2-X40','K6-1-u2-X41']::text[],false,'{"seq":13,"concept":"K6-1-u2-C32","difficulty":2,"kind":"mc","stem":"하린이 지호의 의견을 넣지 않은 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"「종이배」 감상문이라 다른 연극 이름은 하려던 말과 멀어서","correct":true},{"t":"지호가 친구가 아니어서","mis":"K6-1-u2-X40"},{"t":"의견은 하나도 받지 않기로 해서","mis":"K6-1-u2-X41"},{"t":"다른 연극 이름을 몰라서","mis":"K6-1-u2-X40"}],"explanation":["고르는 것은 글쓴이예요.","하려던 말에 도움이 되는지 봐요.","하린은 까닭을 말했어요."],"asset":{"type":"speech","turns":[{"who":"지호","text":"하린아, 끝에 네가 좋아하는 다른 연극 이름도 다 적으면 어때?"},{"who":"하린","text":"고맙지만 이 글은 「종이배」 감상문이라 그건 넣지 않을래."},{"who":"하린","text":"보미 말대로 연극을 본 이야기는 맨 앞으로 옮겼어. 서준이 말대로 놀이터 문장은 뺐고."},{"who":"하린","text":"띄어쓰기는 검사기를 돌려 봤는데, 왜 그렇게 고쳤는지 하나씩 확인하고 받아들였어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_a#14','kor',6,1,'u2','','g6_1_kor_u2_review_a','unit_review','K6-1-u2-C25',2,'mc','auto','로운의 글 첫 문장이 한 번에 읽히지 않는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u2-X36','K6-1-u2-X33','K6-1-u2-X18']::text[],false,'{"seq":14,"concept":"K6-1-u2-C25","difficulty":2,"kind":"mc","stem":"로운의 글 첫 문장이 한 번에 읽히지 않는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"한 문장에 여러 가지를 이어 붙이고 「순서」를 되풀이해서","correct":true},{"t":"주제가 텃밭이 아니어서","mis":"K6-1-u2-X36"},{"t":"문장이 너무 짧아서","mis":"K6-1-u2-X33"},{"t":"높임 표현을 써서","mis":"K6-1-u2-X18"}],"explanation":["주제는 텃밭이 맞아요.","한 문장이 너무 길어요.","「순서」가 자꾸 되풀이돼요."],"asset":{"type":"passage","lines":["우리 학교 텃밭에는 물 주는 순서가 있는데 그 순서는 반마다 정해 놓은","순서이고 순서를 지키면 채소가 잘 자라는데 순서를 안 지키면 물을 두 번","주게 되고 그래서 순서를 지켜야 한다.","당번은 아침마다 텃밭에 줍니다.","상추는 물을 많이 주면 뿌리가 썩는다고 누가 그랬다.","텃밭 옆 체육 창고 문은 지난달에 새로 칠했습니다."],"title":"로운이 쓴 설명하는 글 초고 「텃밭 물 주기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_a#15','kor',6,1,'u2','','g6_1_kor_u2_review_a','unit_review','K6-1-u2-C23',2,'match','auto','감상문의 짜임과 들어갈 내용을 이으세요.','{}'::text[],false,'{"seq":15,"concept":"K6-1-u2-C23","difficulty":2,"kind":"match","stem":"감상문의 짜임과 들어갈 내용을 이으세요.","pairs":[{"l":"처음","r":"무엇을 보았는지와 보게 된 까닭"},{"l":"가운데","r":"간단한 줄거리와 인상 깊은 장면, 그때의 생각"},{"l":"끝","r":"느낀 점과 앞으로 하고 싶은 일"}],"mis":"K6-1-u2-X12","explanation":["처음에는 무엇을 왜 보았는지 써요.","가운데가 가장 길어요.","끝에는 느낀 점과 다짐을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_a#16','kor',6,1,'u2','','g6_1_kor_u2_review_a','unit_review','K6-1-u2-C35',2,'mc','auto','「텃밭 물 주기」에 넣기 가장 알맞은 사진은 어느 것인가요?',ARRAY['K6-1-u2-X43','K6-1-u2-X09']::text[],false,'{"seq":16,"concept":"K6-1-u2-C35","difficulty":2,"kind":"mc","stem":"「텃밭 물 주기」에 넣기 가장 알맞은 사진은 어느 것인가요?","options":[{"t":"반별 물 주기 순서가 적힌 텃밭 안내판 사진","correct":true},{"t":"학교 정문의 멋진 풍경 사진","mis":"K6-1-u2-X43"},{"t":"체육 창고 문 사진","mis":"K6-1-u2-X43"},{"t":"남이 찍은 텃밭 사진을 출처 없이","mis":"K6-1-u2-X09"}],"explanation":["보기 좋아도 내용과 멀면 빼요.","남의 사진은 출처를 밝혀요.","설명을 바로 보여 주는 사진을 넣어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_a#17','kor',6,1,'u2','','g6_1_kor_u2_review_a','unit_review','K6-1-u2-C8',3,'mc','auto','하린의 초고 제목 「종이배 이야기」를 고친 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u2-X11','K6-1-u2-X36']::text[],false,'{"seq":17,"concept":"K6-1-u2-C8","difficulty":3,"kind":"mc","stem":"하린의 초고 제목 「종이배 이야기」를 고친 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"서두르지 않는 손이 가르쳐 준 것","correct":true},{"t":"종이배 연극 줄거리","mis":"K6-1-u2-X11"},{"t":"우리 동네 놀이터","mis":"K6-1-u2-X36"},{"t":"토요일 강당","mis":"K6-1-u2-X11"}],"explanation":["지금 제목에는 느낀 것이 없어요.","줄거리 · 장소만 알리는 제목은 부족해요.","가장 하고 싶었던 말을 제목에 담아요."],"asset":{"type":"passage","lines":["가장 오래 남은 장면은 할머니가 손녀에게 종이배 접는 법을 가르치는 장면이다.","손녀는 몇 번이나 배를 찢었지만 할머니는 한 번도 서두르지 않았다.","우리 동네 놀이터에는 새 미끄럼틀이 생겼다.","할머니가 「천천히 접으면 물에 오래 뜬단다.」 하고 말했다. 나는 그 장면이 전혀 지루했다.","배 두척을 강물에 띄우는 마지막 장면도 기억에 남는다.","나도 동생에게 무엇을 가르쳐 줄 때 기다려 줄수 있는 사람이 되겠다.","지난 토요일 학교 강당에서 학부모 및학생이 함께 이 연극을 보았다."],"title":"하린이 쓴 연극 감상문 초고 「종이배 이야기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_a#18','kor',6,1,'u2','','g6_1_kor_u2_review_a','unit_review','K6-1-u2-C15',3,'ox','auto','글 수준을 고치다가 띄어쓰기 틀린 곳이 보이면 나중에 따로 보려고 미뤄 두어야 해요.',ARRAY['K6-1-u2-X22']::text[],false,'{"seq":18,"concept":"K6-1-u2-C15","difficulty":3,"kind":"ox","stem":"글 수준을 고치다가 띄어쓰기 틀린 곳이 보이면 나중에 따로 보려고 미뤄 두어야 해요.","answer":"X","reason_options":[{"t":"세 수준은 따로 도는 절차가 아니라 보이는 그때그때 함께 고치는 것이기 때문에","correct":true},{"t":"반드시 글 → 문단 → 문장을 세 번 나누어 해야 하기 때문에","mis":"K6-1-u2-X22"}],"mis":"K6-1-u2-X22","explanation":["큰 것부터 보는 것은 맞아요.","보이는 것은 그때 함께 고쳐요.","부호로 표시해 두면 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_a#19','kor',6,1,'u2','','g6_1_kor_u2_review_a','unit_review','K6-1-u2-C10',3,'mc','auto','하린의 감상문 중심 내용을 두 친구가 다르게 말했어요. 둘 다 좋은 답이 되는 조건은 무엇인가요?',ARRAY['K6-1-u2-X13']::text[],false,'{"seq":19,"concept":"K6-1-u2-C10","difficulty":3,"kind":"mc","stem":"하린의 감상문 중심 내용을 두 친구가 다르게 말했어요. 둘 다 좋은 답이 되는 조건은 무엇인가요?","options":[{"t":"둘 다 글에서 근거를 댈 수 있어야 한다","correct":true},{"t":"둘 가운데 먼저 말한 쪽만 맞다","mis":"K6-1-u2-X13"},{"t":"선생님이 정한 답과 같아야 한다","mis":"K6-1-u2-X13"},{"t":"근거는 없어도 느낌이 같으면 된다","mis":"K6-1-u2-X13"}],"explanation":["중심 내용은 여럿일 수 있어요.","정답 하나를 찾는 일이 아니에요.","근거를 댈 수 있는지가 중요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_a#20','kor',6,1,'u2','','g6_1_kor_u2_review_a','unit_review','K6-1-u2-C25',3,'mc','auto','로운의 글 첫 문장을 잘 나눈 것은 어느 것인가요?',ARRAY['K6-1-u2-X33','K6-1-u2-X34','K6-1-u2-X35']::text[],false,'{"seq":20,"concept":"K6-1-u2-C25","difficulty":3,"kind":"mc","stem":"로운의 글 첫 문장을 잘 나눈 것은 어느 것인가요?","options":[{"t":"우리 학교 텃밭에는 물 주는 순서가 있습니다. 반마다 정한 순서입니다. 순서를 지키면 물을 두 번 주는 일이 없습니다.","correct":true},{"t":"우리 학교 텃밭에는 순서가 있는데 반마다 정했고 지키면 잘 자라고 안 지키면 두 번 주고 그래서 지켜야 한다.","mis":"K6-1-u2-X33"},{"t":"텃밭. 순서. 반마다. 두 번.","mis":"K6-1-u2-X34"},{"t":"순서 순서 순서를 지켜야 합니다.","mis":"K6-1-u2-X35"}],"explanation":["이어 붙이면 여전히 길어요.","너무 줄이면 성분이 빠져요.","한 문장에 한 가지씩, 성분을 갖춰요."],"asset":{"type":"passage","lines":["우리 학교 텃밭에는 물 주는 순서가 있는데 그 순서는 반마다 정해 놓은","순서이고 순서를 지키면 채소가 잘 자라는데 순서를 안 지키면 물을 두 번","주게 되고 그래서 순서를 지켜야 한다.","당번은 아침마다 텃밭에 줍니다.","상추는 물을 많이 주면 뿌리가 썩는다고 누가 그랬다.","텃밭 옆 체육 창고 문은 지난달에 새로 칠했습니다."],"title":"로운이 쓴 설명하는 글 초고 「텃밭 물 주기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_a#21','kor',6,1,'u2','','g6_1_kor_u2_review_a','unit_review','K6-1-u2-C37',3,'mc','auto','「종이배」 연극을 소개하는 문장으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u2-X44','K6-1-u2-X45']::text[],false,'{"seq":21,"concept":"K6-1-u2-C37","difficulty":3,"kind":"mc","stem":"「종이배」 연극을 소개하는 문장으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"할머니는 손녀가 배를 찢을 때마다 새 종이를 건네며 「천천히」라고만 말한다","correct":true},{"t":"이 연극은 세상에서 제일 재미있는 연극이다","mis":"K6-1-u2-X44"},{"t":"연극은 무대에서 배우가 하는 공연이다","mis":"K6-1-u2-X45"},{"t":"정말 정말 꼭 보세요","mis":"K6-1-u2-X44"}],"explanation":["자랑은 알 수 있는 것이 없어요.","누구에게나 있는 말은 소개가 아니에요.","그려 볼 수 있게 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_a#22','kor',6,1,'u2','','g6_1_kor_u2_review_a','unit_review','K6-1-u2-C33',3,'mc','auto','하린이 고쳐 쓴 글을 공유한 뒤 할 일로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u2-X41','K6-1-u2-X10','K6-1-u2-X01']::text[],false,'{"seq":22,"concept":"K6-1-u2-C33","difficulty":3,"kind":"mc","stem":"하린이 고쳐 쓴 글을 공유한 뒤 할 일로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"달린 댓글을 읽고 답글로 어떻게 했는지 알린 뒤 다시 점검한다","correct":true},{"t":"올리고 바로 끝낸다","mis":"K6-1-u2-X41"},{"t":"칭찬 댓글만 남기고 나머지는 지운다","mis":"K6-1-u2-X10"},{"t":"댓글을 받으면 글을 처음부터 다시 쓴다","mis":"K6-1-u2-X01"}],"explanation":["올리고 끝내지 않아요.","공유는 칭찬받으려는 일이 아니에요.","읽었다는 것과 어떻게 했는지 알려요."],"asset":{"type":"speech","turns":[{"who":"지호","text":"하린아, 끝에 네가 좋아하는 다른 연극 이름도 다 적으면 어때?"},{"who":"하린","text":"고맙지만 이 글은 「종이배」 감상문이라 그건 넣지 않을래."},{"who":"하린","text":"보미 말대로 연극을 본 이야기는 맨 앞으로 옮겼어. 서준이 말대로 놀이터 문장은 뺐고."},{"who":"하린","text":"띄어쓰기는 검사기를 돌려 봤는데, 왜 그렇게 고쳤는지 하나씩 확인하고 받아들였어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_a#23','kor',6,1,'u2','','g6_1_kor_u2_review_a','unit_review','K6-1-u2-C24',4,'mc','auto','하린의 초고를 가장 알맞게 고친 계획은 어느 것인가요?',ARRAY['K6-1-u2-X05','K6-1-u2-X01','K6-1-u2-X03']::text[],false,'{"seq":23,"concept":"K6-1-u2-C24","difficulty":4,"kind":"mc","stem":"하린의 초고를 가장 알맞게 고친 계획은 어느 것인가요?","options":[{"t":"제목에 생각 담기 → 연극을 본 이야기를 맨 앞으로 옮기기 → 놀이터 문장 빼기 → 높임 · 부정 호응 고치기 → 띄어쓰기 고치기","correct":true},{"t":"띄어쓰기 고치기 → 맞춤법 고치기 → 끝","mis":"K6-1-u2-X05"},{"t":"글을 지우고 다른 연극으로 새로 쓰기","mis":"K6-1-u2-X01"},{"t":"놀이터 문장을 맨 앞으로 옮기기 → 나머지는 그대로","mis":"K6-1-u2-X03"}],"explanation":["맞춤법만으로는 부족해요.","다시 쓰지 않아요.","큰 것부터 고르게 고쳐요."],"asset":{"type":"passage","lines":["가장 오래 남은 장면은 할머니가 손녀에게 종이배 접는 법을 가르치는 장면이다.","손녀는 몇 번이나 배를 찢었지만 할머니는 한 번도 서두르지 않았다.","우리 동네 놀이터에는 새 미끄럼틀이 생겼다.","할머니가 「천천히 접으면 물에 오래 뜬단다.」 하고 말했다. 나는 그 장면이 전혀 지루했다.","배 두척을 강물에 띄우는 마지막 장면도 기억에 남는다.","나도 동생에게 무엇을 가르쳐 줄 때 기다려 줄수 있는 사람이 되겠다.","지난 토요일 학교 강당에서 학부모 및학생이 함께 이 연극을 보았다."],"title":"하린이 쓴 연극 감상문 초고 「종이배 이야기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_a#24','kor',6,1,'u2','','g6_1_kor_u2_review_a','unit_review','K6-1-u2-C24',4,'essay','teacher','하린의 감상문 초고에서 고칠 곳을 글 · 문단 · 문장 수준에서 하나 이상씩 찾고, 어떤 차례로 고칠지 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K6-1-u2-C24","difficulty":4,"kind":"essay","stem":"하린의 감상문 초고에서 고칠 곳을 글 · 문단 · 문장 수준에서 하나 이상씩 찾고, 어떤 차례로 고칠지 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 글 수준 — 제목 「종이배 이야기」에 느낀 것이 없고, 연극을 본 이야기가 맨 끝에 있어 차례가 뒤엉켰다. 문단 수준 — 「우리 동네 놀이터에는 새 미끄럼틀이 생겼다」는 연극과 상관없다. 문장 수준 — 「할머니가 말했다」는 「할머니께서 말씀하셨다」로, 「전혀 지루했다」는 「전혀 지루하지 않았다」로, 「두척」 · 「줄수」 · 「및학생」은 띄어 써야 한다. 제목과 차례 → 놀이터 문장 빼기 → 호응 → 띄어쓰기 차례로 고치겠다. 큰 것부터 고쳐야 다듬은 문장이 빠지는 헛수고가 없기 때문이다.","scoring_points":["글 수준의 고칠 곳을 찾았는가","문단 · 문장 수준의 고칠 곳을 찾았는가","큰 것부터의 차례와 까닭을 썼는가"]},"explanation":["세 수준으로 나누어 찾아요.","빠짐없이 찾아요.","큰 것부터의 까닭을 써요."],"asset":{"type":"passage","lines":["가장 오래 남은 장면은 할머니가 손녀에게 종이배 접는 법을 가르치는 장면이다.","손녀는 몇 번이나 배를 찢었지만 할머니는 한 번도 서두르지 않았다.","우리 동네 놀이터에는 새 미끄럼틀이 생겼다.","할머니가 「천천히 접으면 물에 오래 뜬단다.」 하고 말했다. 나는 그 장면이 전혀 지루했다.","배 두척을 강물에 띄우는 마지막 장면도 기억에 남는다.","나도 동생에게 무엇을 가르쳐 줄 때 기다려 줄수 있는 사람이 되겠다.","지난 토요일 학교 강당에서 학부모 및학생이 함께 이 연극을 보았다."],"title":"하린이 쓴 연극 감상문 초고 「종이배 이야기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_a#25','kor',6,1,'u2','','g6_1_kor_u2_review_a','unit_review','K6-1-u2-C1',4,'essay','teacher','이 단원에서 배운 「고쳐쓰기」를 설명하고, 고쳐쓰기가 다시 쓰기나 맞춤법 고치기와 어떻게 다른지 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K6-1-u2-C1","difficulty":4,"kind":"essay","stem":"이 단원에서 배운 「고쳐쓰기」를 설명하고, 고쳐쓰기가 다시 쓰기나 맞춤법 고치기와 어떻게 다른지 쓰세요.","answer_guide":{"answer":"예: 고쳐쓰기는 쓴 글을 글 · 문단 · 문장의 세 수준으로 점검해서 하고 싶은 말이 더 잘 전해지도록 필요한 곳만 빼고 · 더하고 · 바꾸고 · 옮기는 일이다. 다시 쓰기는 처음 쓴 글을 버리고 새로 쓰는 일이라 다르다. 또 맞춤법이나 띄어쓰기만 고치는 것은 문장 수준의 일부일 뿐이어서, 주제에서 벗어난 문장을 빼거나 문단 차례를 옮기는 일까지 해야 고쳐쓰기이다.","scoring_points":["고쳐쓰기를 세 수준과 네 가지 손질로 설명했는가","다시 쓰기와의 차이를 썼는가","맞춤법 고치기와의 차이를 썼는가"]},"explanation":["세 수준과 네 가지 손질을 떠올려요.","다시 쓰기와 견주어요.","맞춤법 고치기와 견주어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_b#1','kor',6,1,'u2','','g6_1_kor_u2_review_b','unit_review','K6-1-u2-C1',1,'ox','auto','고쳐쓰기는 처음 쓴 글을 버리고 새로 쓰는 일이에요.',ARRAY['K6-1-u2-X01']::text[],false,'{"seq":1,"concept":"K6-1-u2-C1","difficulty":1,"kind":"ox","stem":"고쳐쓰기는 처음 쓴 글을 버리고 새로 쓰는 일이에요.","answer":"X","reason_options":[{"t":"처음 쓴 글을 살리면서 필요한 곳만 손보는 일이기 때문에","correct":true},{"t":"처음 쓴 글은 언제나 쓸모없기 때문에","mis":"K6-1-u2-X01"}],"mis":"K6-1-u2-X01","explanation":["고쳐쓰기는 다시 쓰기가 아니에요.","점검한 내용을 바탕으로 해요.","필요한 곳만 손봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_b#2','kor',6,1,'u2','','g6_1_kor_u2_review_b','unit_review','K6-1-u2-C3',1,'mc','auto','「처음 · 가운데 · 끝의 흐름이 자연스러운가」는 어느 수준에서 살필 일인가요?',ARRAY['K6-1-u2-X04','K6-1-u2-X05']::text[],false,'{"seq":2,"concept":"K6-1-u2-C3","difficulty":1,"kind":"mc","stem":"「처음 · 가운데 · 끝의 흐름이 자연스러운가」는 어느 수준에서 살필 일인가요?","options":[{"t":"글 수준","correct":true},{"t":"문장 수준","mis":"K6-1-u2-X04"},{"t":"낱말 수준","mis":"K6-1-u2-X04"},{"t":"띄어쓰기 수준","mis":"K6-1-u2-X05"}],"explanation":["흐름은 글 전체를 봐야 보여요.","한 문장으로는 알 수 없어요.","글 수준의 일이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_b#3','kor',6,1,'u2','','g6_1_kor_u2_review_b','unit_review','K6-1-u2-C18',1,'mc','auto','「아침」 · 「겸」 · 「점심」을 바르게 띄어 쓴 것은 어느 것인가요?',ARRAY['K6-1-u2-X26']::text[],false,'{"seq":3,"concept":"K6-1-u2-C18","difficulty":1,"kind":"mc","stem":"「아침」 · 「겸」 · 「점심」을 바르게 띄어 쓴 것은 어느 것인가요?","options":[{"t":"아침 겸 점심","correct":true},{"t":"아침겸점심","mis":"K6-1-u2-X26"},{"t":"아침 겸점심","mis":"K6-1-u2-X26"},{"t":"아침겸 점심","mis":"K6-1-u2-X26"}],"explanation":["「겸」은 두 말을 잇는 말이에요.","잇는 말은 앞뒤를 띄어요.","아침 ∨ 겸 ∨ 점심으로 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_b#4','kor',6,1,'u2','','g6_1_kor_u2_review_b','unit_review','K6-1-u2-C23',1,'mc','auto','감상문의 「처음」에 쓸 내용으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u2-X12','K6-1-u2-X32']::text[],false,'{"seq":4,"concept":"K6-1-u2-C23","difficulty":1,"kind":"mc","stem":"감상문의 「처음」에 쓸 내용으로 알맞은 것은 어느 것인가요?","options":[{"t":"무엇을 보았는지와 보게 된 까닭","correct":true},{"t":"느낀 점과 다짐","mis":"K6-1-u2-X12"},{"t":"인상 깊은 장면과 생각","mis":"K6-1-u2-X12"},{"t":"모든 장면의 차례","mis":"K6-1-u2-X32"}],"explanation":["다짐은 끝에 써요.","인상 깊은 장면은 가운데에 써요.","처음에는 무엇을 왜 보았는지 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_b#5','kor',6,1,'u2','','g6_1_kor_u2_review_b','unit_review','K6-1-u2-C26',1,'mc','auto','「나는 서가에서 찾았습니다.」에서 빠진 문장 성분은 무엇인가요?',ARRAY['K6-1-u2-X34']::text[],false,'{"seq":5,"concept":"K6-1-u2-C26","difficulty":1,"kind":"mc","stem":"「나는 서가에서 찾았습니다.」에서 빠진 문장 성분은 무엇인가요?","options":[{"t":"목적어","correct":true},{"t":"주어","mis":"K6-1-u2-X34"},{"t":"서술어","mis":"K6-1-u2-X34"},{"t":"빠진 것이 없다","mis":"K6-1-u2-X34"}],"explanation":["누가 찾았는지는 있어요.","무엇을 찾았는지가 없어요.","목적어를 넣어야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_b#6','kor',6,1,'u2','','g6_1_kor_u2_review_b','unit_review','K6-1-u2-C31',1,'mc','auto','「도서관마다 숫자가 같은지 궁금해.」는 의견의 네 갈래 가운데 무엇인가요?',ARRAY['K6-1-u2-X39']::text[],false,'{"seq":6,"concept":"K6-1-u2-C31","difficulty":1,"kind":"mc","stem":"「도서관마다 숫자가 같은지 궁금해.」는 의견의 네 갈래 가운데 무엇인가요?","options":[{"t":"궁금한 점","correct":true},{"t":"새롭게 안 점","mis":"K6-1-u2-X39"},{"t":"좋은 점","mis":"K6-1-u2-X39"},{"t":"고쳤으면 하는 점","mis":"K6-1-u2-X39"}],"explanation":["더 알고 싶은 것을 말했어요.","잘했다는 말이 아니에요.","궁금한 점이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_b#7','kor',6,1,'u2','','g6_1_kor_u2_review_b','unit_review','K6-1-u2-C39',1,'mc','auto','내가 스스로 하는 일을 나타낸 말은 어느 것인가요?',ARRAY['K6-1-u2-X47']::text[],false,'{"seq":7,"concept":"K6-1-u2-C39","difficulty":1,"kind":"mc","stem":"내가 스스로 하는 일을 나타낸 말은 어느 것인가요?","options":[{"t":"내가 그림을 걸다","correct":true},{"t":"그림이 걸리다","mis":"K6-1-u2-X47"},{"t":"책이 놓이다","mis":"K6-1-u2-X47"},{"t":"문이 닫히다","mis":"K6-1-u2-X47"}],"explanation":["「~리다 · ~이다 · ~히다」는 그리 된 일이에요.","내가 직접 한 일을 찾아요.","「그림을 걸다」가 스스로 한 일이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_b#8','kor',6,1,'u2','','g6_1_kor_u2_review_b','unit_review','K6-1-u2-C4',1,'mc','auto','고쳐 쓴 글을 다른 사람과 나누면 좋은 점은 어느 것인가요?',ARRAY['K6-1-u2-X10','K6-1-u2-X05']::text[],false,'{"seq":8,"concept":"K6-1-u2-C4","difficulty":1,"kind":"mc","stem":"고쳐 쓴 글을 다른 사람과 나누면 좋은 점은 어느 것인가요?","options":[{"t":"읽는 사람의 반응을 바로 알 수 있다","correct":true},{"t":"글을 더 고치지 않아도 된다","mis":"K6-1-u2-X10"},{"t":"무조건 칭찬을 받는다","mis":"K6-1-u2-X10"},{"t":"맞춤법을 몰라도 된다","mis":"K6-1-u2-X05"}],"explanation":["나눈 뒤에도 다시 점검해요.","칭찬받으려는 일이 아니에요.","반응을 알면 고쳐쓰기에 도움이 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_b#9','kor',6,1,'u2','','g6_1_kor_u2_review_b','unit_review','K6-1-u2-C12',2,'mc','auto','하린의 초고에서 「배 두척을 강물에 띄우는 마지막 장면도 기억에 남는다.」는 어떻게 하는 것이 알맞은가요?',ARRAY['K6-1-u2-X16','K6-1-u2-X03','K6-1-u2-X25']::text[],false,'{"seq":9,"concept":"K6-1-u2-C12","difficulty":2,"kind":"mc","stem":"하린의 초고에서 「배 두척을 강물에 띄우는 마지막 장면도 기억에 남는다.」는 어떻게 하는 것이 알맞은가요?","options":[{"t":"빼지 않고 「두 척」으로 띄어 고쳐 쓴다","correct":true},{"t":"띄어쓰기가 틀렸으니 문장을 통째로 지운다","mis":"K6-1-u2-X16"},{"t":"놀이터 문장 뒤로 옮긴다","mis":"K6-1-u2-X03"},{"t":"그대로 둔다","mis":"K6-1-u2-X25"}],"explanation":["마지막 장면은 연극과 관련이 있어요.","틀린 곳은 띄어쓰기뿐이에요.","지우지 말고 고쳐요."],"asset":{"type":"passage","lines":["가장 오래 남은 장면은 할머니가 손녀에게 종이배 접는 법을 가르치는 장면이다.","손녀는 몇 번이나 배를 찢었지만 할머니는 한 번도 서두르지 않았다.","우리 동네 놀이터에는 새 미끄럼틀이 생겼다.","할머니가 「천천히 접으면 물에 오래 뜬단다.」 하고 말했다. 나는 그 장면이 전혀 지루했다.","배 두척을 강물에 띄우는 마지막 장면도 기억에 남는다.","나도 동생에게 무엇을 가르쳐 줄 때 기다려 줄수 있는 사람이 되겠다.","지난 토요일 학교 강당에서 학부모 및학생이 함께 이 연극을 보았다."],"title":"하린이 쓴 연극 감상문 초고 「종이배 이야기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_b#10','kor',6,1,'u2','','g6_1_kor_u2_review_b','unit_review','K6-1-u2-C14',2,'mc','auto','「나는 그 장면이 전혀 지루했다.」에서 어긋난 것은 무엇인가요?',ARRAY['K6-1-u2-X18','K6-1-u2-X20','K6-1-u2-X34']::text[],false,'{"seq":10,"concept":"K6-1-u2-C14","difficulty":2,"kind":"mc","stem":"「나는 그 장면이 전혀 지루했다.」에서 어긋난 것은 무엇인가요?","options":[{"t":"「전혀」 뒤에 부정하는 서술어가 오지 않았다","correct":true},{"t":"높임 표현이 빠졌다","mis":"K6-1-u2-X18"},{"t":"시간을 나타내는 말이 없다","mis":"K6-1-u2-X20"},{"t":"주어가 빠졌다","mis":"K6-1-u2-X34"}],"explanation":["「전혀」는 부정과 어울려요.","「지루하지 않았다」로 받아야 해요.","부정 호응이 어긋났어요."],"asset":{"type":"passage","lines":["가장 오래 남은 장면은 할머니가 손녀에게 종이배 접는 법을 가르치는 장면이다.","손녀는 몇 번이나 배를 찢었지만 할머니는 한 번도 서두르지 않았다.","우리 동네 놀이터에는 새 미끄럼틀이 생겼다.","할머니가 「천천히 접으면 물에 오래 뜬단다.」 하고 말했다. 나는 그 장면이 전혀 지루했다.","배 두척을 강물에 띄우는 마지막 장면도 기억에 남는다.","나도 동생에게 무엇을 가르쳐 줄 때 기다려 줄수 있는 사람이 되겠다.","지난 토요일 학교 강당에서 학부모 및학생이 함께 이 연극을 보았다."],"title":"하린이 쓴 연극 감상문 초고 「종이배 이야기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_b#11','kor',6,1,'u2','','g6_1_kor_u2_review_b','unit_review','K6-1-u2-C19',2,'mc','auto','하린의 초고 「기다려 줄수 있는」을 바르게 고친 것은 어느 것인가요?',ARRAY['K6-1-u2-X28','K6-1-u2-X24']::text[],false,'{"seq":11,"concept":"K6-1-u2-C19","difficulty":2,"kind":"mc","stem":"하린의 초고 「기다려 줄수 있는」을 바르게 고친 것은 어느 것인가요?","options":[{"t":"기다려 줄 수 있는","correct":true},{"t":"기다려줄수있는","mis":"K6-1-u2-X28"},{"t":"기다려 줄수있는","mis":"K6-1-u2-X28"},{"t":"기다려 줄 수있는","mis":"K6-1-u2-X24"}],"explanation":["「수」는 홀로 못 쓰는 이름씨예요.","앞말과 띄어 써요.","「있는」도 띄어 써요."],"asset":{"type":"passage","lines":["가장 오래 남은 장면은 할머니가 손녀에게 종이배 접는 법을 가르치는 장면이다.","손녀는 몇 번이나 배를 찢었지만 할머니는 한 번도 서두르지 않았다.","우리 동네 놀이터에는 새 미끄럼틀이 생겼다.","할머니가 「천천히 접으면 물에 오래 뜬단다.」 하고 말했다. 나는 그 장면이 전혀 지루했다.","배 두척을 강물에 띄우는 마지막 장면도 기억에 남는다.","나도 동생에게 무엇을 가르쳐 줄 때 기다려 줄수 있는 사람이 되겠다.","지난 토요일 학교 강당에서 학부모 및학생이 함께 이 연극을 보았다."],"title":"하린이 쓴 연극 감상문 초고 「종이배 이야기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_b#12','kor',6,1,'u2','','g6_1_kor_u2_review_b','unit_review','K6-1-u2-C31',2,'mc','auto','보미의 댓글은 의견의 네 갈래 가운데 무엇인가요?',ARRAY['K6-1-u2-X39']::text[],false,'{"seq":12,"concept":"K6-1-u2-C31","difficulty":2,"kind":"mc","stem":"보미의 댓글은 의견의 네 갈래 가운데 무엇인가요?","options":[{"t":"고쳤으면 하는 점","correct":true},{"t":"새롭게 안 점","mis":"K6-1-u2-X39"},{"t":"궁금한 점","mis":"K6-1-u2-X39"},{"t":"좋은 점","mis":"K6-1-u2-X39"}],"explanation":["맨 앞으로 옮기자고 했어요.","헷갈린 까닭도 말했어요.","고칠 곳과 까닭은 고쳤으면 하는 점이에요."],"asset":{"type":"speech","turns":[{"who":"도윤","text":"틀린 데가 너무 많아. 처음부터 다시 써."},{"who":"채아","text":"잘 썼네. 고칠 곳 하나도 없어."},{"who":"서준","text":"할머니가 서두르지 않는 장면이 눈에 그려졌어. 놀이터 문장은 연극 이야기와 멀어 보여서 빼면 좋겠어."},{"who":"보미","text":"연극을 보게 된 이야기가 맨 끝에 있어서 조금 헷갈렸어. 맨 앞으로 옮기면 어때?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_b#13','kor',6,1,'u2','','g6_1_kor_u2_review_b','unit_review','K6-1-u2-C34',2,'mc','auto','하린이 맞춤법 검사기를 쓴 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u2-X42','K6-1-u2-X41']::text[],false,'{"seq":13,"concept":"K6-1-u2-C34","difficulty":2,"kind":"mc","stem":"하린이 맞춤법 검사기를 쓴 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"고친 곳을 하나씩 왜 그렇게 고쳤는지 확인하고 받아들였다","correct":true},{"t":"검사기가 고친 대로 모두 받아들였다","mis":"K6-1-u2-X42"},{"t":"검사기가 감상문 제목까지 정해 주었다","mis":"K6-1-u2-X42"},{"t":"검사기를 썼으니 다시 읽지 않았다","mis":"K6-1-u2-X41"}],"explanation":["까닭을 확인했어요.","중심 생각은 도구가 정하지 못해요.","고칠지 말지는 하린이 정했어요."],"asset":{"type":"speech","turns":[{"who":"지호","text":"하린아, 끝에 네가 좋아하는 다른 연극 이름도 다 적으면 어때?"},{"who":"하린","text":"고맙지만 이 글은 「종이배」 감상문이라 그건 넣지 않을래."},{"who":"하린","text":"보미 말대로 연극을 본 이야기는 맨 앞으로 옮겼어. 서준이 말대로 놀이터 문장은 뺐고."},{"who":"하린","text":"띄어쓰기는 검사기를 돌려 봤는데, 왜 그렇게 고쳤는지 하나씩 확인하고 받아들였어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_b#14','kor',6,1,'u2','','g6_1_kor_u2_review_b','unit_review','K6-1-u2-C26',2,'mc','auto','「당번은 아침마다 텃밭에 줍니다.」에서 빠진 것은 무엇인가요?',ARRAY['K6-1-u2-X34']::text[],false,'{"seq":14,"concept":"K6-1-u2-C26","difficulty":2,"kind":"mc","stem":"「당번은 아침마다 텃밭에 줍니다.」에서 빠진 것은 무엇인가요?","options":[{"t":"무엇을 주는지(목적어)","correct":true},{"t":"누가 주는지(주어)","mis":"K6-1-u2-X34"},{"t":"어찌하는지(서술어)","mis":"K6-1-u2-X34"},{"t":"빠진 것이 없다","mis":"K6-1-u2-X34"}],"explanation":["당번이 주어예요.","「줍니다」가 서술어예요.","「물을」이 빠졌어요."],"asset":{"type":"passage","lines":["우리 학교 텃밭에는 물 주는 순서가 있는데 그 순서는 반마다 정해 놓은","순서이고 순서를 지키면 채소가 잘 자라는데 순서를 안 지키면 물을 두 번","주게 되고 그래서 순서를 지켜야 한다.","당번은 아침마다 텃밭에 줍니다.","상추는 물을 많이 주면 뿌리가 썩는다고 누가 그랬다.","텃밭 옆 체육 창고 문은 지난달에 새로 칠했습니다."],"title":"로운이 쓴 설명하는 글 초고 「텃밭 물 주기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_b#15','kor',6,1,'u2','','g6_1_kor_u2_review_b','unit_review','K6-1-u2-C36',2,'match','auto','소개하는 글의 짜임과 들어갈 내용을 이으세요.','{}'::text[],false,'{"seq":15,"concept":"K6-1-u2-C36","difficulty":2,"kind":"match","stem":"소개하는 글의 짜임과 들어갈 내용을 이으세요.","pairs":[{"l":"처음","r":"무엇을 소개할지와 고른 까닭"},{"l":"가운데","r":"어떤 것인지와 나와 얽힌 이야기"},{"l":"끝","r":"소개를 맺으며 앞으로 하고 싶은 일"}],"mis":"K6-1-u2-X12","explanation":["처음에 무엇을 왜 골랐는지 밝혀요.","가운데에 그것만의 이야기를 넣어요.","끝에 앞으로의 일을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_b#16','kor',6,1,'u2','','g6_1_kor_u2_review_b','unit_review','K6-1-u2-C30',2,'mc','auto','책에서 찾은 상추 기르기 설명을 글에 쓰는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u2-X38','K6-1-u2-X09']::text[],false,'{"seq":16,"concept":"K6-1-u2-C30","difficulty":2,"kind":"mc","stem":"책에서 찾은 상추 기르기 설명을 글에 쓰는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"읽고 이해한 뒤 내 말로 바꾸어 쓰고 책 이름을 적는다","correct":true},{"t":"그대로 붙여 넣는다","mis":"K6-1-u2-X38"},{"t":"그대로 옮기고 책 이름은 적지 않는다","mis":"K6-1-u2-X09"},{"t":"줄임말로 짧게 바꾼다","mis":"K6-1-u2-X09"}],"explanation":["그대로 옮긴 문장은 내 글이 아니에요.","출처를 밝혀요.","이해한 것을 내 말로 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_b#17','kor',6,1,'u2','','g6_1_kor_u2_review_b','unit_review','K6-1-u2-C24',3,'mc','auto','하린의 초고를 고칠 때 가장 먼저 할 일은 어느 것인가요?',ARRAY['K6-1-u2-X05','K6-1-u2-X01']::text[],false,'{"seq":17,"concept":"K6-1-u2-C24","difficulty":3,"kind":"mc","stem":"하린의 초고를 고칠 때 가장 먼저 할 일은 어느 것인가요?","options":[{"t":"제목을 고치고 연극을 본 이야기를 맨 앞으로 옮긴다","correct":true},{"t":"「두척」 띄어쓰기부터 고친다","mis":"K6-1-u2-X05"},{"t":"글씨를 예쁘게 다시 옮겨 쓴다","mis":"K6-1-u2-X01"},{"t":"맞춤법만 한 번에 고치고 끝낸다","mis":"K6-1-u2-X05"}],"explanation":["작은 것부터 하면 헛수고가 생겨요.","옮겨 쓰기는 고쳐쓰기가 아니에요.","글 수준부터 잡아요."],"asset":{"type":"passage","lines":["가장 오래 남은 장면은 할머니가 손녀에게 종이배 접는 법을 가르치는 장면이다.","손녀는 몇 번이나 배를 찢었지만 할머니는 한 번도 서두르지 않았다.","우리 동네 놀이터에는 새 미끄럼틀이 생겼다.","할머니가 「천천히 접으면 물에 오래 뜬단다.」 하고 말했다. 나는 그 장면이 전혀 지루했다.","배 두척을 강물에 띄우는 마지막 장면도 기억에 남는다.","나도 동생에게 무엇을 가르쳐 줄 때 기다려 줄수 있는 사람이 되겠다.","지난 토요일 학교 강당에서 학부모 및학생이 함께 이 연극을 보았다."],"title":"하린이 쓴 연극 감상문 초고 「종이배 이야기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_b#18','kor',6,1,'u2','','g6_1_kor_u2_review_b','unit_review','K6-1-u2-C15',3,'mc','auto','하린의 초고에서 「배 두척」을 고칠 때 쓸 부호와 쓰임을 바르게 짝 지은 것은 어느 것인가요?',ARRAY['K6-1-u2-X23','K6-1-u2-X29']::text[],false,'{"seq":18,"concept":"K6-1-u2-C15","difficulty":3,"kind":"mc","stem":"하린의 초고에서 「배 두척」을 고칠 때 쓸 부호와 쓰임을 바르게 짝 지은 것은 어느 것인가요?","options":[{"t":"두∨척 — 띄어 쓸 곳에 ∨","correct":true},{"t":"두⌒척 — 띄어 쓸 곳에 ⌒","mis":"K6-1-u2-X23"},{"t":"두⊂척 — 띄어 쓸 곳에 ⊂","mis":"K6-1-u2-X23"},{"t":"부호 없이 문장을 다시 쓴다","mis":"K6-1-u2-X29"}],"explanation":["⌒ 는 붙일 때 써요.","⊂ 는 더 넣을 때 써요.","띄울 곳에는 ∨ 예요."],"asset":{"type":"passage","lines":["가장 오래 남은 장면은 할머니가 손녀에게 종이배 접는 법을 가르치는 장면이다.","손녀는 몇 번이나 배를 찢었지만 할머니는 한 번도 서두르지 않았다.","우리 동네 놀이터에는 새 미끄럼틀이 생겼다.","할머니가 「천천히 접으면 물에 오래 뜬단다.」 하고 말했다. 나는 그 장면이 전혀 지루했다.","배 두척을 강물에 띄우는 마지막 장면도 기억에 남는다.","나도 동생에게 무엇을 가르쳐 줄 때 기다려 줄수 있는 사람이 되겠다.","지난 토요일 학교 강당에서 학부모 및학생이 함께 이 연극을 보았다."],"title":"하린이 쓴 연극 감상문 초고 「종이배 이야기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_b#19','kor',6,1,'u2','','g6_1_kor_u2_review_b','unit_review','K6-1-u2-C11',3,'mc','auto','하린의 감상문에서 중심 생각을 가장 잘 담은 문장은 어느 것인가요?',ARRAY['K6-1-u2-X15','K6-1-u2-X14']::text[],false,'{"seq":19,"concept":"K6-1-u2-C11","difficulty":3,"kind":"mc","stem":"하린의 감상문에서 중심 생각을 가장 잘 담은 문장은 어느 것인가요?","options":[{"t":"나도 동생에게 무엇을 가르쳐 줄 때 기다려 줄 수 있는 사람이 되겠다.","correct":true},{"t":"우리 동네 놀이터에는 새 미끄럼틀이 생겼다.","mis":"K6-1-u2-X15"},{"t":"배 두 척을 강물에 띄우는 마지막 장면도 기억에 남는다.","mis":"K6-1-u2-X14"},{"t":"지난 토요일 학교 강당에서 연극을 보았다.","mis":"K6-1-u2-X14"}],"explanation":["놀이터 문장은 상관없어요.","장면 · 본 때는 뒷받침이에요.","하린이 하고 싶은 말은 기다려 주는 마음이에요."],"asset":{"type":"passage","lines":["가장 오래 남은 장면은 할머니가 손녀에게 종이배 접는 법을 가르치는 장면이다.","손녀는 몇 번이나 배를 찢었지만 할머니는 한 번도 서두르지 않았다.","우리 동네 놀이터에는 새 미끄럼틀이 생겼다.","할머니가 「천천히 접으면 물에 오래 뜬단다.」 하고 말했다. 나는 그 장면이 전혀 지루했다.","배 두척을 강물에 띄우는 마지막 장면도 기억에 남는다.","나도 동생에게 무엇을 가르쳐 줄 때 기다려 줄수 있는 사람이 되겠다.","지난 토요일 학교 강당에서 학부모 및학생이 함께 이 연극을 보았다."],"title":"하린이 쓴 연극 감상문 초고 「종이배 이야기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_b#20','kor',6,1,'u2','','g6_1_kor_u2_review_b','unit_review','K6-1-u2-C27',3,'mc','auto','로운의 글 제목으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u2-X36','K6-1-u2-X11']::text[],false,'{"seq":20,"concept":"K6-1-u2-C27","difficulty":3,"kind":"mc","stem":"로운의 글 제목으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"반마다 순서가 있는 텃밭 물 주기","correct":true},{"t":"세상의 모든 채소","mis":"K6-1-u2-X36"},{"t":"체육 창고 이야기","mis":"K6-1-u2-X36"},{"t":"우리 학교","mis":"K6-1-u2-X11"}],"explanation":["너무 넓은 제목은 내용과 달라요.","창고는 내용과 상관없어요.","내용과 일치하고 짧게 지어요."],"asset":{"type":"passage","lines":["우리 학교 텃밭에는 물 주는 순서가 있는데 그 순서는 반마다 정해 놓은","순서이고 순서를 지키면 채소가 잘 자라는데 순서를 안 지키면 물을 두 번","주게 되고 그래서 순서를 지켜야 한다.","당번은 아침마다 텃밭에 줍니다.","상추는 물을 많이 주면 뿌리가 썩는다고 누가 그랬다.","텃밭 옆 체육 창고 문은 지난달에 새로 칠했습니다."],"title":"로운이 쓴 설명하는 글 초고 「텃밭 물 주기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_b#21','kor',6,1,'u2','','g6_1_kor_u2_review_b','unit_review','K6-1-u2-C39',3,'match','auto','책상과 문에 일어난 일에 알맞은 표현을 이으세요.','{}'::text[],false,'{"seq":21,"concept":"K6-1-u2-C39","difficulty":3,"kind":"match","stem":"책상과 문에 일어난 일에 알맞은 표현을 이으세요.","pairs":[{"l":"내가 책상 위에 책을","r":"놓았다"},{"l":"언제부터인가 책상 위에 책이","r":"놓여 있었다"},{"l":"바람에 문이","r":"닫혔다"}],"mis":"K6-1-u2-X47","explanation":["내가 한 일은 주동이에요.","저절로 그리 된 것은 피동이에요.","바람이라는 다른 힘이 닫았어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_b#22','kor',6,1,'u2','','g6_1_kor_u2_review_b','unit_review','K6-1-u2-C20',3,'mc','auto','하린이 「나는 「수」를 자주 붙여 써.」라고 알게 되었어요. 다음에 할 일로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u2-X24','K6-1-u2-X29','K6-1-u2-X42']::text[],false,'{"seq":22,"concept":"K6-1-u2-C20","difficulty":3,"kind":"mc","stem":"하린이 「나는 「수」를 자주 붙여 써.」라고 알게 되었어요. 다음에 할 일로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"다음 글을 쓸 때 「수」 앞뒤를 꼭 확인하기로 정해 둔다","correct":true},{"t":"띄어쓰기는 원래 어려우니 신경 쓰지 않는다","mis":"K6-1-u2-X24"},{"t":"틀릴 때마다 글을 처음부터 다시 쓴다","mis":"K6-1-u2-X29"},{"t":"검사기가 알아서 고쳐 주니 확인하지 않는다","mis":"K6-1-u2-X42"}],"explanation":["띄어쓰기는 뜻 문제예요.","다시 쓰지 않아도 돼요.","내 버릇 한 가지를 정해 챙겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_b#23','kor',6,1,'u2','','g6_1_kor_u2_review_b','unit_review','K6-1-u2-C32',4,'mc','auto','하린이 받은 의견을 처리한 방법을 평가한 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u2-X40','K6-1-u2-X01','K6-1-u2-X42']::text[],false,'{"seq":23,"concept":"K6-1-u2-C32","difficulty":4,"kind":"mc","stem":"하린이 받은 의견을 처리한 방법을 평가한 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"하려던 말에 도움이 되는 보미 · 서준의 의견은 받아들이고, 지호의 의견은 까닭을 들어 넣지 않아 알맞다","correct":true},{"t":"지호의 의견도 꼭 넣었어야 했다","mis":"K6-1-u2-X40"},{"t":"도윤이 말대로 처음부터 다시 썼어야 했다","mis":"K6-1-u2-X01"},{"t":"검사기가 고친 대로 받아들였으니 알맞다","mis":"K6-1-u2-X42"}],"explanation":["의견을 모두 따를 필요는 없어요.","다시 쓰지 않아요.","하린은 까닭을 확인했어요."],"asset":{"type":"speech","turns":[{"who":"지호","text":"하린아, 끝에 네가 좋아하는 다른 연극 이름도 다 적으면 어때?"},{"who":"하린","text":"고맙지만 이 글은 「종이배」 감상문이라 그건 넣지 않을래."},{"who":"하린","text":"보미 말대로 연극을 본 이야기는 맨 앞으로 옮겼어. 서준이 말대로 놀이터 문장은 뺐고."},{"who":"하린","text":"띄어쓰기는 검사기를 돌려 봤는데, 왜 그렇게 고쳤는지 하나씩 확인하고 받아들였어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_b#24','kor',6,1,'u2','','g6_1_kor_u2_review_b','unit_review','K6-1-u2-C5',4,'essay','teacher','하린의 글에 달린 도윤이와 채아의 댓글이 왜 알맞지 않은지 쓰고, 두 사람의 댓글을 알맞게 고쳐 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K6-1-u2-C5","difficulty":4,"kind":"essay","stem":"하린의 글에 달린 도윤이와 채아의 댓글이 왜 알맞지 않은지 쓰고, 두 사람의 댓글을 알맞게 고쳐 쓰세요.","answer_guide":{"answer":"예: 도윤이는 고칠 곳만 말하고 다시 쓰라고 해서 하린이가 위축될 수 있다. 채아는 「고칠 곳 하나도 없어」라고 막연하게 칭찬해서 하린이에게 쓸모 있는 말이 되지 못한다. 고친 도윤이 댓글 — 「할머니 대사를 그대로 넣어서 장면이 생생했어. 「할머니가 말했다」는 「할머니께서 말씀하셨다」로 고치면 더 좋겠어. 할머니는 웃어른이니까.」 고친 채아 댓글 — 「마지막 다짐이 마음에 남았어. 다만 놀이터 문장은 연극과 멀어 보여서 빼면 좋겠어.」","scoring_points":["도윤이 댓글의 문제를 썼는가","채아 댓글의 문제를 썼는가","잘한 곳 → 고칠 곳 → 까닭 차례로 고쳐 썼는가"]},"explanation":["두 댓글의 문제를 찾아요.","왜 알맞지 않은지 써요.","잘한 곳 · 고칠 곳 · 까닭으로 고쳐요."],"asset":{"type":"speech","turns":[{"who":"도윤","text":"틀린 데가 너무 많아. 처음부터 다시 써."},{"who":"채아","text":"잘 썼네. 고칠 곳 하나도 없어."},{"who":"서준","text":"할머니가 서두르지 않는 장면이 눈에 그려졌어. 놀이터 문장은 연극 이야기와 멀어 보여서 빼면 좋겠어."},{"who":"보미","text":"연극을 보게 된 이야기가 맨 끝에 있어서 조금 헷갈렸어. 맨 앞으로 옮기면 어때?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_b#25','kor',6,1,'u2','','g6_1_kor_u2_review_b','unit_review','K6-1-u2-C16',4,'essay','teacher','띄어쓰기를 「글씨 문제가 아니라 뜻 문제」라고 하는 까닭을 예를 들어 설명하고, 띄어쓰기 원리 두 가지를 예와 함께 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K6-1-u2-C16","difficulty":4,"kind":"essay","stem":"띄어쓰기를 「글씨 문제가 아니라 뜻 문제」라고 하는 까닭을 예를 들어 설명하고, 띄어쓰기 원리 두 가지를 예와 함께 쓰세요.","answer_guide":{"answer":"예: 「큰집에 다녀왔다」와 「큰 집에 다녀왔다」는 띄어쓰기 하나로 친척 어른 댁과 크기가 큰 집으로 뜻이 갈린다. 읽는 사람은 글쓴이의 마음을 볼 수 없어서 띄어쓰기로 뜻을 알아내므로 띄어쓰기는 뜻 문제이다. 원리 첫째, 세는 말은 앞의 수와 띄어 써서 「나무 두 그루」처럼 쓴다. 둘째, 잇는 말은 앞뒤를 띄어 써서 「학생 및 학부모」처럼 쓴다.","scoring_points":["뜻이 갈리는 예를 들었는가","뜻 문제인 까닭을 썼는가","띄어쓰기 원리 두 가지를 예와 함께 썼는가"]},"explanation":["뜻이 갈리는 예를 들어요.","읽는 사람의 처지에서 써요.","원리를 예와 함께 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_c#1','kor',6,1,'u2','','g6_1_kor_u2_review_c','unit_review','K6-1-u2-C2',1,'mc','auto','글에 부족한 내용이 있을 때 하는 손질은 어느 것인가요?',ARRAY['K6-1-u2-X03','K6-1-u2-X01']::text[],false,'{"seq":1,"concept":"K6-1-u2-C2","difficulty":1,"kind":"mc","stem":"글에 부족한 내용이 있을 때 하는 손질은 어느 것인가요?","options":[{"t":"더하기","correct":true},{"t":"빼기","mis":"K6-1-u2-X03"},{"t":"옮기기","mis":"K6-1-u2-X03"},{"t":"지우고 다시 쓰기","mis":"K6-1-u2-X01"}],"explanation":["벗어난 것은 빼요.","뒤엉킨 것은 옮겨요.","모자란 것은 더해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_c#2','kor',6,1,'u2','','g6_1_kor_u2_review_c','unit_review','K6-1-u2-C3',1,'mc','auto','「상관없는 뒷받침 문장은 없는가」는 어느 수준에서 살필 일인가요?',ARRAY['K6-1-u2-X04','K6-1-u2-X05']::text[],false,'{"seq":2,"concept":"K6-1-u2-C3","difficulty":1,"kind":"mc","stem":"「상관없는 뒷받침 문장은 없는가」는 어느 수준에서 살필 일인가요?","options":[{"t":"문단 수준","correct":true},{"t":"글 수준","mis":"K6-1-u2-X04"},{"t":"문장 수준","mis":"K6-1-u2-X04"},{"t":"맞춤법 수준","mis":"K6-1-u2-X05"}],"explanation":["뒷받침 문장은 문단 안에 있어요.","중심 문장과 견주어 봐요.","문단 수준의 일이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_c#3','kor',6,1,'u2','','g6_1_kor_u2_review_c','unit_review','K6-1-u2-C19',1,'mc','auto','「할수있다」를 바르게 띄어 쓴 것은 어느 것인가요?',ARRAY['K6-1-u2-X28','K6-1-u2-X24']::text[],false,'{"seq":3,"concept":"K6-1-u2-C19","difficulty":1,"kind":"mc","stem":"「할수있다」를 바르게 띄어 쓴 것은 어느 것인가요?","options":[{"t":"할 수 있다","correct":true},{"t":"할수있다","mis":"K6-1-u2-X28"},{"t":"할수 있다","mis":"K6-1-u2-X28"},{"t":"할 수있다","mis":"K6-1-u2-X24"}],"explanation":["「수」는 홀로 못 쓰는 이름씨예요.","앞말과 띄어 써요.","「있다」도 띄어 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_c#4','kor',6,1,'u2','','g6_1_kor_u2_review_c','unit_review','K6-1-u2-C22',1,'ox','auto','감상문에는 인상 깊은 장면과 함께 그 장면이 왜 남았는지도 써요.',ARRAY['K6-1-u2-X31']::text[],false,'{"seq":4,"concept":"K6-1-u2-C22","difficulty":1,"kind":"ox","stem":"감상문에는 인상 깊은 장면과 함께 그 장면이 왜 남았는지도 써요.","answer":"O","reason_options":[{"t":"까닭까지 써야 내가 느끼고 생각한 것이 드러나기 때문에","correct":true},{"t":"장면만 고르면 까닭은 읽는 사람이 알아서 짐작하기 때문에","mis":"K6-1-u2-X31"}],"mis":"K6-1-u2-X31","explanation":["「좋았다」로 끝내지 않아요.","왜 남았는지 써요.","그래야 감상문이 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_c#5','kor',6,1,'u2','','g6_1_kor_u2_review_c','unit_review','K6-1-u2-C25',1,'mc','auto','한 문장이 너무 길 때 고치는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u2-X33','K6-1-u2-X34','K6-1-u2-X35']::text[],false,'{"seq":5,"concept":"K6-1-u2-C25","difficulty":1,"kind":"mc","stem":"한 문장이 너무 길 때 고치는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"한 가지씩 담기도록 여러 문장으로 나눈다","correct":true},{"t":"문장을 더 이어 붙인다","mis":"K6-1-u2-X33"},{"t":"주어와 서술어를 뺀다","mis":"K6-1-u2-X34"},{"t":"같은 낱말을 더 넣는다","mis":"K6-1-u2-X35"}],"explanation":["이어 붙이면 더 길어져요.","성분을 빼면 뜻이 흐려져요.","한 문장에 한 가지씩 나눠요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_c#6','kor',6,1,'u2','','g6_1_kor_u2_review_c','unit_review','K6-1-u2-C31',1,'mc','auto','「숫자에 뜻이 있는 줄 몰랐어.」는 의견의 네 갈래 가운데 무엇인가요?',ARRAY['K6-1-u2-X39']::text[],false,'{"seq":6,"concept":"K6-1-u2-C31","difficulty":1,"kind":"mc","stem":"「숫자에 뜻이 있는 줄 몰랐어.」는 의견의 네 갈래 가운데 무엇인가요?","options":[{"t":"새롭게 안 점","correct":true},{"t":"궁금한 점","mis":"K6-1-u2-X39"},{"t":"좋은 점","mis":"K6-1-u2-X39"},{"t":"고쳤으면 하는 점","mis":"K6-1-u2-X39"}],"explanation":["몰랐던 것이에요.","이제 알게 되었어요.","새롭게 안 점이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_c#7','kor',6,1,'u2','','g6_1_kor_u2_review_c','unit_review','K6-1-u2-C38',1,'mc','auto','「내일」과 어울리는 서술어는 어느 것인가요?',ARRAY['K6-1-u2-X20','K6-1-u2-X18']::text[],false,'{"seq":7,"concept":"K6-1-u2-C38","difficulty":1,"kind":"mc","stem":"「내일」과 어울리는 서술어는 어느 것인가요?","options":[{"t":"갈 것이다","correct":true},{"t":"갔다","mis":"K6-1-u2-X20"},{"t":"간다","mis":"K6-1-u2-X20"},{"t":"가셨다","mis":"K6-1-u2-X18"}],"explanation":["내일은 아직 오지 않은 때예요.","앞으로의 일에는 「~ㄹ 것이다」를 써요.","「내일 갈 것이다」로 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_c#8','kor',6,1,'u2','','g6_1_kor_u2_review_c','unit_review','K6-1-u2-C33',1,'ox','auto','글을 게시판에 올린 뒤에는 제대로 올라갔는지 다시 들어가 확인해요.',ARRAY['K6-1-u2-X41']::text[],false,'{"seq":8,"concept":"K6-1-u2-C33","difficulty":1,"kind":"ox","stem":"글을 게시판에 올린 뒤에는 제대로 올라갔는지 다시 들어가 확인해요.","answer":"O","reason_options":[{"t":"올린 뒤 확인하고 댓글을 읽으며 다시 점검하는 것까지가 공유하기이기 때문에","correct":true},{"t":"한 번 올리면 다시 볼 필요가 없기 때문에","mis":"K6-1-u2-X41"}],"mis":"K6-1-u2-X41","explanation":["올리고 끝내지 않아요.","확인하고 댓글을 읽어요.","다시 점검해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_c#9','kor',6,1,'u2','','g6_1_kor_u2_review_c','unit_review','K6-1-u2-C15',2,'ox','auto','하린의 초고에서 놀이터 문장은 연극 이야기와 상관없어서 빼는 것이 알맞아요.',ARRAY['K6-1-u2-X15']::text[],false,'{"seq":9,"concept":"K6-1-u2-C15","difficulty":2,"kind":"ox","stem":"하린의 초고에서 놀이터 문장은 연극 이야기와 상관없어서 빼는 것이 알맞아요.","answer":"O","reason_options":[{"t":"감상문의 중심인 연극 「종이배」와 이어지지 않는 문장이기 때문에","correct":true},{"t":"놀이터 이야기는 재미가 없기 때문에","mis":"K6-1-u2-X15"}],"mis":"K6-1-u2-X15","explanation":["중심과 견주어 봐요.","놀이터는 연극과 상관없어요.","벗어난 문장은 빼요."],"asset":{"type":"passage","lines":["가장 오래 남은 장면은 할머니가 손녀에게 종이배 접는 법을 가르치는 장면이다.","손녀는 몇 번이나 배를 찢었지만 할머니는 한 번도 서두르지 않았다.","우리 동네 놀이터에는 새 미끄럼틀이 생겼다.","할머니가 「천천히 접으면 물에 오래 뜬단다.」 하고 말했다. 나는 그 장면이 전혀 지루했다.","배 두척을 강물에 띄우는 마지막 장면도 기억에 남는다.","나도 동생에게 무엇을 가르쳐 줄 때 기다려 줄수 있는 사람이 되겠다.","지난 토요일 학교 강당에서 학부모 및학생이 함께 이 연극을 보았다."],"title":"하린이 쓴 연극 감상문 초고 「종이배 이야기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_c#10','kor',6,1,'u2','','g6_1_kor_u2_review_c','unit_review','K6-1-u2-C14',2,'match','auto','하린의 초고 문장과 어긋난 갈래를 이으세요.','{}'::text[],false,'{"seq":10,"concept":"K6-1-u2-C14","difficulty":2,"kind":"match","stem":"하린의 초고 문장과 어긋난 갈래를 이으세요.","pairs":[{"l":"할머니가 말했다","r":"높임"},{"l":"전혀 지루했다","r":"부정"},{"l":"배 두척","r":"띄어쓰기"}],"mis":"K6-1-u2-X04","explanation":["웃어른에게는 높임을 써요.","전혀 뒤에는 부정이 와요.","세는 말은 띄어요."],"asset":{"type":"passage","lines":["가장 오래 남은 장면은 할머니가 손녀에게 종이배 접는 법을 가르치는 장면이다.","손녀는 몇 번이나 배를 찢었지만 할머니는 한 번도 서두르지 않았다.","우리 동네 놀이터에는 새 미끄럼틀이 생겼다.","할머니가 「천천히 접으면 물에 오래 뜬단다.」 하고 말했다. 나는 그 장면이 전혀 지루했다.","배 두척을 강물에 띄우는 마지막 장면도 기억에 남는다.","나도 동생에게 무엇을 가르쳐 줄 때 기다려 줄수 있는 사람이 되겠다.","지난 토요일 학교 강당에서 학부모 및학생이 함께 이 연극을 보았다."],"title":"하린이 쓴 연극 감상문 초고 「종이배 이야기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_c#11','kor',6,1,'u2','','g6_1_kor_u2_review_c','unit_review','K6-1-u2-C20',2,'mc','auto','하린의 초고에서 띄어 쓸 곳을 부호로 바르게 표시한 것은 어느 것인가요?',ARRAY['K6-1-u2-X23','K6-1-u2-X29']::text[],false,'{"seq":11,"concept":"K6-1-u2-C20","difficulty":2,"kind":"mc","stem":"하린의 초고에서 띄어 쓸 곳을 부호로 바르게 표시한 것은 어느 것인가요?","options":[{"t":"두∨척 · 및∨학생 · 줄∨수","correct":true},{"t":"두⌒척 · 및⌒학생 · 줄⌒수","mis":"K6-1-u2-X23"},{"t":"두⊂척 · 및⊂학생 · 줄⊂수","mis":"K6-1-u2-X23"},{"t":"부호 없이 글을 처음부터 다시 쓴다","mis":"K6-1-u2-X29"}],"explanation":["⌒ 는 붙일 때 써요.","⊂ 는 내용을 더 넣을 때 써요.","띄울 곳에는 ∨ 를 표시해요."],"asset":{"type":"passage","lines":["가장 오래 남은 장면은 할머니가 손녀에게 종이배 접는 법을 가르치는 장면이다.","손녀는 몇 번이나 배를 찢었지만 할머니는 한 번도 서두르지 않았다.","우리 동네 놀이터에는 새 미끄럼틀이 생겼다.","할머니가 「천천히 접으면 물에 오래 뜬단다.」 하고 말했다. 나는 그 장면이 전혀 지루했다.","배 두척을 강물에 띄우는 마지막 장면도 기억에 남는다.","나도 동생에게 무엇을 가르쳐 줄 때 기다려 줄수 있는 사람이 되겠다.","지난 토요일 학교 강당에서 학부모 및학생이 함께 이 연극을 보았다."],"title":"하린이 쓴 연극 감상문 초고 「종이배 이야기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_c#12','kor',6,1,'u2','','g6_1_kor_u2_review_c','unit_review','K6-1-u2-C5',2,'ox','auto','도윤이의 댓글은 하린이가 다시 고쳐 쓰고 싶어지게 하는 좋은 댓글이에요.',ARRAY['K6-1-u2-X06']::text[],false,'{"seq":12,"concept":"K6-1-u2-C5","difficulty":2,"kind":"ox","stem":"도윤이의 댓글은 하린이가 다시 고쳐 쓰고 싶어지게 하는 좋은 댓글이에요.","answer":"X","reason_options":[{"t":"고칠 곳만 말하고 다시 쓰라고 해 글쓴이를 위축시키기 때문에","correct":true},{"t":"틀린 곳을 많이 말해 줄수록 좋은 댓글이기 때문에","mis":"K6-1-u2-X06"}],"mis":"K6-1-u2-X06","explanation":["잘한 곳이 하나도 없어요.","까닭도 없어요.","글쓴이가 쓰기 싫어질 수 있어요."],"asset":{"type":"speech","turns":[{"who":"도윤","text":"틀린 데가 너무 많아. 처음부터 다시 써."},{"who":"채아","text":"잘 썼네. 고칠 곳 하나도 없어."},{"who":"서준","text":"할머니가 서두르지 않는 장면이 눈에 그려졌어. 놀이터 문장은 연극 이야기와 멀어 보여서 빼면 좋겠어."},{"who":"보미","text":"연극을 보게 된 이야기가 맨 끝에 있어서 조금 헷갈렸어. 맨 앞으로 옮기면 어때?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_c#13','kor',6,1,'u2','','g6_1_kor_u2_review_c','unit_review','K6-1-u2-C32',2,'ox','auto','하린은 보미와 서준의 의견은 받아들이고 지호의 의견은 받아들이지 않았어요.',ARRAY['K6-1-u2-X40']::text[],false,'{"seq":13,"concept":"K6-1-u2-C32","difficulty":2,"kind":"ox","stem":"하린은 보미와 서준의 의견은 받아들이고 지호의 의견은 받아들이지 않았어요.","answer":"O","reason_options":[{"t":"하려던 말이 더 잘 전해지는 의견만 골라 받아들였기 때문에","correct":true},{"t":"친구 의견은 모두 따라야 하기 때문에","mis":"K6-1-u2-X40"}],"mis":"K6-1-u2-X40","explanation":["보미 — 차례 옮기기를 받아들였어요.","서준 — 놀이터 문장 빼기를 받아들였어요.","지호의 의견은 까닭을 들어 넣지 않았어요."],"asset":{"type":"speech","turns":[{"who":"지호","text":"하린아, 끝에 네가 좋아하는 다른 연극 이름도 다 적으면 어때?"},{"who":"하린","text":"고맙지만 이 글은 「종이배」 감상문이라 그건 넣지 않을래."},{"who":"하린","text":"보미 말대로 연극을 본 이야기는 맨 앞으로 옮겼어. 서준이 말대로 놀이터 문장은 뺐고."},{"who":"하린","text":"띄어쓰기는 검사기를 돌려 봤는데, 왜 그렇게 고쳤는지 하나씩 확인하고 받아들였어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_c#14','kor',6,1,'u2','','g6_1_kor_u2_review_c','unit_review','K6-1-u2-C28',2,'mc','auto','「상추는 물을 많이 주면 뿌리가 썩는다고 누가 그랬다.」의 문제로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u2-X15','K6-1-u2-X33','K6-1-u2-X05']::text[],false,'{"seq":14,"concept":"K6-1-u2-C28","difficulty":2,"kind":"mc","stem":"「상추는 물을 많이 주면 뿌리가 썩는다고 누가 그랬다.」의 문제로 알맞은 것은 어느 것인가요?","options":[{"t":"누가 언제 한 말인지 알 수 없어 확인되지 않은 자료이다","correct":true},{"t":"상추는 텃밭과 상관없다","mis":"K6-1-u2-X15"},{"t":"문장이 너무 짧다","mis":"K6-1-u2-X33"},{"t":"띄어쓰기가 틀렸다","mis":"K6-1-u2-X05"}],"explanation":["상추는 텃밭과 관련 있어요.","「누가 그랬다」는 확인할 수 없어요.","믿을 수 있는 자료로 바꾸고 출처를 밝혀요."],"asset":{"type":"passage","lines":["우리 학교 텃밭에는 물 주는 순서가 있는데 그 순서는 반마다 정해 놓은","순서이고 순서를 지키면 채소가 잘 자라는데 순서를 안 지키면 물을 두 번","주게 되고 그래서 순서를 지켜야 한다.","당번은 아침마다 텃밭에 줍니다.","상추는 물을 많이 주면 뿌리가 썩는다고 누가 그랬다.","텃밭 옆 체육 창고 문은 지난달에 새로 칠했습니다."],"title":"로운이 쓴 설명하는 글 초고 「텃밭 물 주기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_c#15','kor',6,1,'u2','','g6_1_kor_u2_review_c','unit_review','K6-1-u2-C29',2,'match','auto','설명하는 글 「텃밭 물 주기」의 내용이 들어갈 곳을 이으세요.','{}'::text[],false,'{"seq":15,"concept":"K6-1-u2-C29","difficulty":2,"kind":"match","stem":"설명하는 글 「텃밭 물 주기」의 내용이 들어갈 곳을 이으세요.","pairs":[{"l":"텃밭에 물 주는 순서가 왜 있는지 궁금하지 않나요?","r":"처음"},{"l":"반마다 요일을 나누어 아침에 물을 줍니다","r":"가운데"},{"l":"순서를 지키면 채소도 우리도 편해집니다","r":"끝"}],"mis":"K6-1-u2-X12","explanation":["관심을 끄는 말은 처음이에요.","자세한 설명은 가운데예요.","간추려 맺는 말은 끝이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_c#16','kor',6,1,'u2','','g6_1_kor_u2_review_c','unit_review','K6-1-u2-C6',2,'ox','auto','온라인에 한 번 올린 글은 널리 퍼질 수 있으므로 읽는 사람을 떠올리며 써야 해요.',ARRAY['K6-1-u2-X09']::text[],false,'{"seq":16,"concept":"K6-1-u2-C6","difficulty":2,"kind":"ox","stem":"온라인에 한 번 올린 글은 널리 퍼질 수 있으므로 읽는 사람을 떠올리며 써야 해요.","answer":"O","reason_options":[{"t":"여러 사람이 읽고 퍼질 수 있어 읽는 사람이 누구인지가 고칠 때의 기준이 되기 때문에","correct":true},{"t":"올린 글은 금방 사라지기 때문에","mis":"K6-1-u2-X09"}],"mis":"K6-1-u2-X09","explanation":["올린 글은 널리 퍼져요.","읽는 사람을 떠올려요.","그것이 고쳐쓰기의 기준이 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_c#17','kor',6,1,'u2','','g6_1_kor_u2_review_c','unit_review','K6-1-u2-C22',3,'ox','auto','하린은 할머니가 서두르지 않는 장면을 고르고 그 까닭을 「나도 기다려 줄 수 있는 사람이 되겠다」로 이어 썼어요.',ARRAY['K6-1-u2-X31']::text[],false,'{"seq":17,"concept":"K6-1-u2-C22","difficulty":3,"kind":"ox","stem":"하린은 할머니가 서두르지 않는 장면을 고르고 그 까닭을 「나도 기다려 줄 수 있는 사람이 되겠다」로 이어 썼어요.","answer":"O","reason_options":[{"t":"인상 깊은 장면과 그 장면에서 얻은 생각을 이어 썼기 때문에","correct":true},{"t":"장면만 쓰면 감상문이 되기 때문에","mis":"K6-1-u2-X31"}],"mis":"K6-1-u2-X31","explanation":["장면을 골랐어요.","그 장면에서 생각한 것을 썼어요.","장면과 까닭이 이어져요."],"asset":{"type":"passage","lines":["가장 오래 남은 장면은 할머니가 손녀에게 종이배 접는 법을 가르치는 장면이다.","손녀는 몇 번이나 배를 찢었지만 할머니는 한 번도 서두르지 않았다.","우리 동네 놀이터에는 새 미끄럼틀이 생겼다.","할머니가 「천천히 접으면 물에 오래 뜬단다.」 하고 말했다. 나는 그 장면이 전혀 지루했다.","배 두척을 강물에 띄우는 마지막 장면도 기억에 남는다.","나도 동생에게 무엇을 가르쳐 줄 때 기다려 줄수 있는 사람이 되겠다.","지난 토요일 학교 강당에서 학부모 및학생이 함께 이 연극을 보았다."],"title":"하린이 쓴 연극 감상문 초고 「종이배 이야기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_c#18','kor',6,1,'u2','','g6_1_kor_u2_review_c','unit_review','K6-1-u2-C2',3,'mc','auto','하린의 초고에 해야 할 손질을 바르게 짝 지은 것은 어느 것인가요?',ARRAY['K6-1-u2-X03','K6-1-u2-X01','K6-1-u2-X05']::text[],false,'{"seq":18,"concept":"K6-1-u2-C2","difficulty":3,"kind":"mc","stem":"하린의 초고에 해야 할 손질을 바르게 짝 지은 것은 어느 것인가요?","options":[{"t":"놀이터 문장 — 빼기 · 연극을 본 이야기 — 옮기기 · 「전혀 지루했다」 — 바꾸기","correct":true},{"t":"놀이터 문장 — 옮기기 · 연극을 본 이야기 — 빼기 · 「전혀 지루했다」 — 더하기","mis":"K6-1-u2-X03"},{"t":"모든 문장 — 지우고 다시 쓰기","mis":"K6-1-u2-X01"},{"t":"놀이터 문장 — 그대로 · 연극을 본 이야기 — 그대로 · 띄어쓰기만 바꾸기","mis":"K6-1-u2-X05"}],"explanation":["벗어난 것은 빼요.","뒤엉킨 것은 옮겨요.","어색한 표현은 바꿔요."],"asset":{"type":"passage","lines":["가장 오래 남은 장면은 할머니가 손녀에게 종이배 접는 법을 가르치는 장면이다.","손녀는 몇 번이나 배를 찢었지만 할머니는 한 번도 서두르지 않았다.","우리 동네 놀이터에는 새 미끄럼틀이 생겼다.","할머니가 「천천히 접으면 물에 오래 뜬단다.」 하고 말했다. 나는 그 장면이 전혀 지루했다.","배 두척을 강물에 띄우는 마지막 장면도 기억에 남는다.","나도 동생에게 무엇을 가르쳐 줄 때 기다려 줄수 있는 사람이 되겠다.","지난 토요일 학교 강당에서 학부모 및학생이 함께 이 연극을 보았다."],"title":"하린이 쓴 연극 감상문 초고 「종이배 이야기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_c#19','kor',6,1,'u2','','g6_1_kor_u2_review_c','unit_review','K6-1-u2-C10',3,'ox','auto','하린의 감상문 중심 내용을 「서두르지 않는 마음」으로도, 「가르쳐 주는 사람의 기다림」으로도 볼 수 있어요.',ARRAY['K6-1-u2-X13']::text[],false,'{"seq":19,"concept":"K6-1-u2-C10","difficulty":3,"kind":"ox","stem":"하린의 감상문 중심 내용을 「서두르지 않는 마음」으로도, 「가르쳐 주는 사람의 기다림」으로도 볼 수 있어요.","answer":"O","reason_options":[{"t":"두 가지 모두 할머니 장면과 하린의 다짐에서 근거를 댈 수 있기 때문에","correct":true},{"t":"중심 내용은 아무렇게나 정해도 되기 때문에","mis":"K6-1-u2-X13"}],"mis":"K6-1-u2-X13","explanation":["할머니는 서두르지 않았어요.","하린은 기다려 주겠다고 했어요.","근거가 있으면 둘 다 좋은 답이에요."],"asset":{"type":"passage","lines":["가장 오래 남은 장면은 할머니가 손녀에게 종이배 접는 법을 가르치는 장면이다.","손녀는 몇 번이나 배를 찢었지만 할머니는 한 번도 서두르지 않았다.","우리 동네 놀이터에는 새 미끄럼틀이 생겼다.","할머니가 「천천히 접으면 물에 오래 뜬단다.」 하고 말했다. 나는 그 장면이 전혀 지루했다.","배 두척을 강물에 띄우는 마지막 장면도 기억에 남는다.","나도 동생에게 무엇을 가르쳐 줄 때 기다려 줄수 있는 사람이 되겠다.","지난 토요일 학교 강당에서 학부모 및학생이 함께 이 연극을 보았다."],"title":"하린이 쓴 연극 감상문 초고 「종이배 이야기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_c#20','kor',6,1,'u2','','g6_1_kor_u2_review_c','unit_review','K6-1-u2-C28',3,'mc','auto','「누가 그랬다」를 고치는 방법으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u2-X37','K6-1-u2-X38']::text[],false,'{"seq":20,"concept":"K6-1-u2-C28","difficulty":3,"kind":"mc","stem":"「누가 그랬다」를 고치는 방법으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"학교 텃밭 담당 선생님이나 믿을 수 있는 책에서 확인하고 출처를 밝혀 쓴다","correct":true},{"t":"그대로 둔다","mis":"K6-1-u2-X37"},{"t":"「인터넷에서 봤다」로만 바꾼다","mis":"K6-1-u2-X37"},{"t":"그 문장을 다른 글에서 그대로 베껴 온다","mis":"K6-1-u2-X38"}],"explanation":["확인되지 않은 말은 쓰지 않아요.","「인터넷」만으로는 누가 언제 썼는지 몰라요.","확인하고 출처를 밝혀요."],"asset":{"type":"passage","lines":["우리 학교 텃밭에는 물 주는 순서가 있는데 그 순서는 반마다 정해 놓은","순서이고 순서를 지키면 채소가 잘 자라는데 순서를 안 지키면 물을 두 번","주게 되고 그래서 순서를 지켜야 한다.","당번은 아침마다 텃밭에 줍니다.","상추는 물을 많이 주면 뿌리가 썩는다고 누가 그랬다.","텃밭 옆 체육 창고 문은 지난달에 새로 칠했습니다."],"title":"로운이 쓴 설명하는 글 초고 「텃밭 물 주기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_c#21','kor',6,1,'u2','','g6_1_kor_u2_review_c','unit_review','K6-1-u2-C38',3,'error','auto','문장을 고쳤어요. 알맞지 않게 고친 친구는 누구인가요?',ARRAY['K6-1-u2-X20','K6-1-u2-X46']::text[],false,'{"seq":21,"concept":"K6-1-u2-C38","difficulty":3,"kind":"error","stem":"문장을 고쳤어요. 알맞지 않게 고친 친구는 누구인가요?","options":[{"t":"하율 — 「내일 우리 반은 텃밭에 물을 주었다.」","correct":true,"mis_target":"K6-1-u2-X20"},{"t":"서진 — 「어제 우리 반은 텃밭에 물을 주었다.」","mis":"K6-1-u2-X46"},{"t":"라온 — 「텃밭이 물로 채워졌다.」","mis":"K6-1-u2-X46"}],"explanation":["서진은 어제와 「주었다」를 맞췄어요.","라온은 당하는 말로 받았어요.","하율은 내일과 「주었다」가 어긋나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_c#22','kor',6,1,'u2','','g6_1_kor_u2_review_c','unit_review','K6-1-u2-C16',3,'ox','auto','「아버지가방에들어가신다」는 띄어쓰기에 따라 뜻이 달라질 수 있어요.',ARRAY['K6-1-u2-X24']::text[],false,'{"seq":22,"concept":"K6-1-u2-C16","difficulty":3,"kind":"ox","stem":"「아버지가방에들어가신다」는 띄어쓰기에 따라 뜻이 달라질 수 있어요.","answer":"O","reason_options":[{"t":"「아버지가 방에」와 「아버지 가방에」처럼 어디서 띄느냐에 따라 뜻이 갈리기 때문에","correct":true},{"t":"붙여 써도 뜻은 하나뿐이기 때문에","mis":"K6-1-u2-X24"}],"mis":"K6-1-u2-X24","explanation":["「가방」으로 읽을 수도 있어요.","「가 ∨ 방」으로 읽을 수도 있어요.","띄어쓰기가 뜻을 갈라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_c#23','kor',6,1,'u2','','g6_1_kor_u2_review_c','unit_review','K6-1-u2-C29',4,'mc','auto','로운의 글을 가장 알맞게 고친 계획은 어느 것인가요?',ARRAY['K6-1-u2-X33','K6-1-u2-X37','K6-1-u2-X38']::text[],false,'{"seq":23,"concept":"K6-1-u2-C29","difficulty":4,"kind":"mc","stem":"로운의 글을 가장 알맞게 고친 계획은 어느 것인가요?","options":[{"t":"첫 문장을 나누고 · 「물을」을 넣고 · 확인되지 않은 상추 문장은 확인 뒤 출처를 밝히고 · 창고 문장은 뺀다","correct":true},{"t":"첫 문장을 더 길게 이어 붙인다","mis":"K6-1-u2-X33"},{"t":"창고 문장은 두고 상추 문장은 그대로 쓴다","mis":"K6-1-u2-X37"},{"t":"찾은 자료를 그대로 붙여 넣어 글을 늘린다","mis":"K6-1-u2-X38"}],"explanation":["길게 이으면 더 안 읽혀요.","확인되지 않은 자료는 쓰지 않아요.","나누고 · 채우고 · 확인하고 · 빼요."],"asset":{"type":"passage","lines":["우리 학교 텃밭에는 물 주는 순서가 있는데 그 순서는 반마다 정해 놓은","순서이고 순서를 지키면 채소가 잘 자라는데 순서를 안 지키면 물을 두 번","주게 되고 그래서 순서를 지켜야 한다.","당번은 아침마다 텃밭에 줍니다.","상추는 물을 많이 주면 뿌리가 썩는다고 누가 그랬다.","텃밭 옆 체육 창고 문은 지난달에 새로 칠했습니다."],"title":"로운이 쓴 설명하는 글 초고 「텃밭 물 주기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_c#24','kor',6,1,'u2','','g6_1_kor_u2_review_c','unit_review','K6-1-u2-C25',4,'essay','teacher','로운의 설명하는 글 초고를 명확한 문장의 조건과 자료 확인을 생각하며 고쳐 쓰고, 무엇을 고쳤는지 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K6-1-u2-C25","difficulty":4,"kind":"essay","stem":"로운의 설명하는 글 초고를 명확한 문장의 조건과 자료 확인을 생각하며 고쳐 쓰고, 무엇을 고쳤는지 쓰세요.","answer_guide":{"answer":"예: 우리 학교 텃밭에는 물 주는 순서가 있습니다. 이 순서는 반마다 정해 둔 것입니다. 순서를 지키면 같은 곳에 물을 두 번 주는 일이 없어 채소가 잘 자랍니다. 당번은 아침마다 텃밭에 물을 줍니다. 상추는 물을 너무 많이 주면 뿌리가 상할 수 있어 조심해야 한다고 텃밭 담당 선생님께서 알려 주셨습니다. — 긴 첫 문장을 나누고, 되풀이되던 「순서」를 줄이고, 빠진 「물을」을 넣고, 「누가 그랬다」를 확인한 출처로 바꾸고, 창고 문장을 뺐다.","scoring_points":["긴 문장을 나누고 겹치는 표현을 줄였는가","빠진 성분을 채웠는가","확인되지 않은 자료와 상관없는 문장을 고쳤는가"]},"explanation":["한 문장에 한 가지씩 나눠요.","빠진 성분을 채워요.","자료를 확인하고 벗어난 문장을 빼요."],"asset":{"type":"passage","lines":["우리 학교 텃밭에는 물 주는 순서가 있는데 그 순서는 반마다 정해 놓은","순서이고 순서를 지키면 채소가 잘 자라는데 순서를 안 지키면 물을 두 번","주게 되고 그래서 순서를 지켜야 한다.","당번은 아침마다 텃밭에 줍니다.","상추는 물을 많이 주면 뿌리가 썩는다고 누가 그랬다.","텃밭 옆 체육 창고 문은 지난달에 새로 칠했습니다."],"title":"로운이 쓴 설명하는 글 초고 「텃밭 물 주기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_c#25','kor',6,1,'u2','','g6_1_kor_u2_review_c','unit_review','K6-1-u2-C38',4,'essay','teacher','「어제」 · 「내 생각은」 · 「화면이」로 시작하는 문장을 하나씩 호응이 맞게 쓰고, 각 문장에서 서술어를 어떻게 맞추었는지 설명하세요.','{}'::text[],false,'{"seq":25,"concept":"K6-1-u2-C38","difficulty":4,"kind":"essay","stem":"「어제」 · 「내 생각은」 · 「화면이」로 시작하는 문장을 하나씩 호응이 맞게 쓰고, 각 문장에서 서술어를 어떻게 맞추었는지 설명하세요.","answer_guide":{"answer":"예: 어제 나는 도서관에서 책을 빌렸다. — 어제는 지난 때라 서술어를 「빌렸다」로 맞추었다. 내 생각은 작은 고침도 소중하다는 것이다. — 주어가 「내 생각은」이라 「~것이다」로 받았다. 화면이 밝은 빛으로 채워졌다. — 화면이 스스로 한 일이 아니어서 「채워졌다」로 받았다.","scoring_points":["세 문장을 호응이 맞게 썼는가","시간 표현에 맞춘 까닭을 썼는가","주어에 맞춘 까닭(~것이다 · ~되다)을 썼는가"]},"explanation":["시간 말에 서술어를 맞춰요.","「내 생각은」은 「~것이다」로 받아요.","스스로 한 일이 아니면 「~되다 · ~히다」로 받아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_d#1','kor',6,1,'u2','','g6_1_kor_u2_review_d','unit_review','K6-1-u2-C2',1,'mc','auto','어색한 표현을 알맞은 말로 고치는 손질은 어느 것인가요?',ARRAY['K6-1-u2-X03']::text[],false,'{"seq":1,"concept":"K6-1-u2-C2","difficulty":1,"kind":"mc","stem":"어색한 표현을 알맞은 말로 고치는 손질은 어느 것인가요?","options":[{"t":"바꾸기","correct":true},{"t":"빼기","mis":"K6-1-u2-X03"},{"t":"더하기","mis":"K6-1-u2-X03"},{"t":"옮기기","mis":"K6-1-u2-X03"}],"explanation":["빼기는 벗어난 내용을 지우는 일이에요.","더하기는 모자란 내용을 넣는 일이에요.","어색한 표현은 바꿔요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_d#2','kor',6,1,'u2','','g6_1_kor_u2_review_d','unit_review','K6-1-u2-C3',1,'ox','auto','고쳐 쓸 때에는 글 → 문단 → 문장의 차례로 큰 것부터 살펴요.',ARRAY['K6-1-u2-X05']::text[],false,'{"seq":2,"concept":"K6-1-u2-C3","difficulty":1,"kind":"ox","stem":"고쳐 쓸 때에는 글 → 문단 → 문장의 차례로 큰 것부터 살펴요.","answer":"O","reason_options":[{"t":"큰 것부터 봐야 다듬은 문장이 통째로 빠지는 헛수고가 줄기 때문에","correct":true},{"t":"작은 것은 고칠 필요가 없기 때문에","mis":"K6-1-u2-X05"}],"mis":"K6-1-u2-X05","explanation":["큰 것부터 봐요.","작은 것도 나중에 고쳐요.","헛수고가 줄어들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_d#3','kor',6,1,'u2','','g6_1_kor_u2_review_d','unit_review','K6-1-u2-C19',1,'mc','auto','조사를 바르게 붙여 쓴 문장은 어느 것인가요?',ARRAY['K6-1-u2-X27','K6-1-u2-X24']::text[],false,'{"seq":3,"concept":"K6-1-u2-C19","difficulty":1,"kind":"mc","stem":"조사를 바르게 붙여 쓴 문장은 어느 것인가요?","options":[{"t":"친구에게 편지를 썼다","correct":true},{"t":"친구 에게 편지를 썼다","mis":"K6-1-u2-X27"},{"t":"친구에게 편지 를 썼다","mis":"K6-1-u2-X27"},{"t":"친구에게편지를썼다","mis":"K6-1-u2-X24"}],"explanation":["「에게」 · 「를」은 조사예요.","조사는 앞말에 붙여요.","낱말과 낱말 사이는 띄어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_d#4','kor',6,1,'u2','','g6_1_kor_u2_review_d','unit_review','K6-1-u2-C23',1,'ox','auto','감상문에는 처음부터 끝까지의 모든 장면을 빠짐없이 적어요.',ARRAY['K6-1-u2-X32']::text[],false,'{"seq":4,"concept":"K6-1-u2-C23","difficulty":1,"kind":"ox","stem":"감상문에는 처음부터 끝까지의 모든 장면을 빠짐없이 적어요.","answer":"X","reason_options":[{"t":"줄거리는 짧게 쓰고 인상 깊은 장면과 생각을 자세히 쓰기 때문에","correct":true},{"t":"모든 장면을 써야 읽는 사람이 이해하기 때문에","mis":"K6-1-u2-X32"}],"mis":"K6-1-u2-X32","explanation":["모든 장면을 쓰면 줄거리 요약이 돼요.","줄거리는 간단히 써요.","장면과 생각을 길게 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_d#5','kor',6,1,'u2','','g6_1_kor_u2_review_d','unit_review','K6-1-u2-C25',1,'ox','auto','같은 낱말을 여러 번 되풀이하면 뜻이 더 또렷해져요.',ARRAY['K6-1-u2-X35']::text[],false,'{"seq":5,"concept":"K6-1-u2-C25","difficulty":1,"kind":"ox","stem":"같은 낱말을 여러 번 되풀이하면 뜻이 더 또렷해져요.","answer":"X","reason_options":[{"t":"겹치는 표현은 하나로 줄여야 읽기 쉽고 뜻이 또렷해지기 때문에","correct":true},{"t":"되풀이할수록 중요하다는 뜻이 되기 때문에","mis":"K6-1-u2-X35"}],"mis":"K6-1-u2-X35","explanation":["다빈은 「번호」를 되풀이했어요.","고친 글에서는 숫자 · 표시로 갈랐어요.","겹치는 표현은 줄여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_d#6','kor',6,1,'u2','','g6_1_kor_u2_review_d','unit_review','K6-1-u2-C28',1,'ox','auto','누가 언제 썼는지 알 수 없는 글도 설명하는 글의 자료로 그대로 써도 돼요.',ARRAY['K6-1-u2-X37']::text[],false,'{"seq":6,"concept":"K6-1-u2-C28","difficulty":1,"kind":"ox","stem":"누가 언제 썼는지 알 수 없는 글도 설명하는 글의 자료로 그대로 써도 돼요.","answer":"X","reason_options":[{"t":"믿을 수 있는지, 지금도 맞는지 확인할 수 없기 때문에","correct":true},{"t":"인터넷에 있는 글은 모두 맞기 때문에","mis":"K6-1-u2-X37"}],"mis":"K6-1-u2-X37","explanation":["누가 만들었는지 확인해요.","언제 만들었는지 확인해요.","확인하지 않은 자료는 쓰지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_d#7','kor',6,1,'u2','','g6_1_kor_u2_review_d','unit_review','K6-1-u2-C38',1,'ox','auto','「지난주」와 「본다」는 서로 잘 어울려요.',ARRAY['K6-1-u2-X20']::text[],false,'{"seq":7,"concept":"K6-1-u2-C38","difficulty":1,"kind":"ox","stem":"「지난주」와 「본다」는 서로 잘 어울려요.","answer":"X","reason_options":[{"t":"지난주는 지난 때라 「보았다」로 받아야 하기 때문에","correct":true},{"t":"시간을 나타내는 말은 서술어와 상관없기 때문에","mis":"K6-1-u2-X20"}],"mis":"K6-1-u2-X20","explanation":["시간 말이 서술어를 끌고 가요.","지난주는 지난 때예요.","「지난주에 보았다」로 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_d#8','kor',6,1,'u2','','g6_1_kor_u2_review_d','unit_review','K6-1-u2-C7',1,'ox','auto','고쳐쓰기를 할 때 한 군데만 고쳐도 글은 그만큼 나아져요.',ARRAY['K6-1-u2-X02']::text[],false,'{"seq":8,"concept":"K6-1-u2-C7","difficulty":1,"kind":"ox","stem":"고쳐쓰기를 할 때 한 군데만 고쳐도 글은 그만큼 나아져요.","answer":"O","reason_options":[{"t":"고쳐쓰기는 완벽한 글을 만드는 일이 아니라 필요한 곳을 손보는 일이기 때문에","correct":true},{"t":"한 군데만 고치면 고친 것이 아니기 때문에","mis":"K6-1-u2-X02"}],"mis":"K6-1-u2-X02","explanation":["완벽할 필요가 없어요.","작게 고친 것도 잘 고친 것이에요.","고친 만큼 나아져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_d#9','kor',6,1,'u2','','g6_1_kor_u2_review_d','unit_review','K6-1-u2-C9',2,'mc','auto','하린의 초고에서 맨 끝 문장 「지난 토요일 학교 강당에서 ~ 이 연극을 보았다.」는 어디로 옮기는 것이 알맞은가요?',ARRAY['K6-1-u2-X12','K6-1-u2-X03','K6-1-u2-X16']::text[],false,'{"seq":9,"concept":"K6-1-u2-C9","difficulty":2,"kind":"mc","stem":"하린의 초고에서 맨 끝 문장 「지난 토요일 학교 강당에서 ~ 이 연극을 보았다.」는 어디로 옮기는 것이 알맞은가요?","options":[{"t":"글의 맨 앞(처음)","correct":true},{"t":"그대로 맨 끝","mis":"K6-1-u2-X12"},{"t":"놀이터 문장 바로 뒤","mis":"K6-1-u2-X03"},{"t":"빼 버린다","mis":"K6-1-u2-X16"}],"explanation":["언제 어디서 보았는지는 보게 된 이야기예요.","처음에 와야 해요.","내용은 그대로 두고 차례만 옮겨요."],"asset":{"type":"passage","lines":["가장 오래 남은 장면은 할머니가 손녀에게 종이배 접는 법을 가르치는 장면이다.","손녀는 몇 번이나 배를 찢었지만 할머니는 한 번도 서두르지 않았다.","우리 동네 놀이터에는 새 미끄럼틀이 생겼다.","할머니가 「천천히 접으면 물에 오래 뜬단다.」 하고 말했다. 나는 그 장면이 전혀 지루했다.","배 두척을 강물에 띄우는 마지막 장면도 기억에 남는다.","나도 동생에게 무엇을 가르쳐 줄 때 기다려 줄수 있는 사람이 되겠다.","지난 토요일 학교 강당에서 학부모 및학생이 함께 이 연극을 보았다."],"title":"하린이 쓴 연극 감상문 초고 「종이배 이야기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_d#10','kor',6,1,'u2','','g6_1_kor_u2_review_d','unit_review','K6-1-u2-C13',2,'ox','auto','「할머니가 말했다」는 뜻이 통하니까 고칠 필요가 없어요.',ARRAY['K6-1-u2-X17']::text[],false,'{"seq":10,"concept":"K6-1-u2-C13","difficulty":2,"kind":"ox","stem":"「할머니가 말했다」는 뜻이 통하니까 고칠 필요가 없어요.","answer":"X","reason_options":[{"t":"뜻이 통해도 높임 호응이 어긋나면 바른 문장이 아니기 때문에","correct":true},{"t":"할머니는 높일 필요가 없기 때문에","mis":"K6-1-u2-X17"}],"mis":"K6-1-u2-X17","explanation":["내용과 형식을 함께 봐요.","웃어른에게는 높임이 어울려요.","「할머니께서 말씀하셨다」로 고쳐요."],"asset":{"type":"passage","lines":["가장 오래 남은 장면은 할머니가 손녀에게 종이배 접는 법을 가르치는 장면이다.","손녀는 몇 번이나 배를 찢었지만 할머니는 한 번도 서두르지 않았다.","우리 동네 놀이터에는 새 미끄럼틀이 생겼다.","할머니가 「천천히 접으면 물에 오래 뜬단다.」 하고 말했다. 나는 그 장면이 전혀 지루했다.","배 두척을 강물에 띄우는 마지막 장면도 기억에 남는다.","나도 동생에게 무엇을 가르쳐 줄 때 기다려 줄수 있는 사람이 되겠다.","지난 토요일 학교 강당에서 학부모 및학생이 함께 이 연극을 보았다."],"title":"하린이 쓴 연극 감상문 초고 「종이배 이야기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_d#11','kor',6,1,'u2','','g6_1_kor_u2_review_d','unit_review','K6-1-u2-C17',2,'ox','auto','「배 두척」은 세는 말 「척」을 앞의 수와 띄어 「배 두 척」으로 써야 해요.',ARRAY['K6-1-u2-X25']::text[],false,'{"seq":11,"concept":"K6-1-u2-C17","difficulty":2,"kind":"ox","stem":"「배 두척」은 세는 말 「척」을 앞의 수와 띄어 「배 두 척」으로 써야 해요.","answer":"O","reason_options":[{"t":"척은 배를 세는 말이고 세는 말은 앞의 수와 띄어 쓰기 때문에","correct":true},{"t":"배와 두를 붙여 써야 하기 때문에","mis":"K6-1-u2-X25"}],"mis":"K6-1-u2-X25","explanation":["척은 배를 세는 말이에요.","수와 세는 말은 띄어요.","「배 두 척」으로 써요."],"asset":{"type":"passage","lines":["가장 오래 남은 장면은 할머니가 손녀에게 종이배 접는 법을 가르치는 장면이다.","손녀는 몇 번이나 배를 찢었지만 할머니는 한 번도 서두르지 않았다.","우리 동네 놀이터에는 새 미끄럼틀이 생겼다.","할머니가 「천천히 접으면 물에 오래 뜬단다.」 하고 말했다. 나는 그 장면이 전혀 지루했다.","배 두척을 강물에 띄우는 마지막 장면도 기억에 남는다.","나도 동생에게 무엇을 가르쳐 줄 때 기다려 줄수 있는 사람이 되겠다.","지난 토요일 학교 강당에서 학부모 및학생이 함께 이 연극을 보았다."],"title":"하린이 쓴 연극 감상문 초고 「종이배 이야기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_d#12','kor',6,1,'u2','','g6_1_kor_u2_review_d','unit_review','K6-1-u2-C7',2,'mc','auto','채아의 댓글 「잘 썼네. 고칠 곳 하나도 없어.」를 고친 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u2-X07','K6-1-u2-X06','K6-1-u2-X08']::text[],false,'{"seq":12,"concept":"K6-1-u2-C7","difficulty":2,"kind":"mc","stem":"채아의 댓글 「잘 썼네. 고칠 곳 하나도 없어.」를 고친 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「할머니 장면이 자세해서 좋았어. 「전혀 지루했다」는 「지루하지 않았다」로 고치면 좋겠어.」","correct":true},{"t":"「정말 정말 잘 썼어.」","mis":"K6-1-u2-X07"},{"t":"「틀린 데 많아.」","mis":"K6-1-u2-X06"},{"t":"「전혀 지루했다 고쳐.」","mis":"K6-1-u2-X08"}],"explanation":["막연한 칭찬은 쓸모가 적어요.","고칠 곳만 말하면 위축돼요.","어디가 왜 좋은지, 무엇을 고칠지 말해요."],"asset":{"type":"speech","turns":[{"who":"도윤","text":"틀린 데가 너무 많아. 처음부터 다시 써."},{"who":"채아","text":"잘 썼네. 고칠 곳 하나도 없어."},{"who":"서준","text":"할머니가 서두르지 않는 장면이 눈에 그려졌어. 놀이터 문장은 연극 이야기와 멀어 보여서 빼면 좋겠어."},{"who":"보미","text":"연극을 보게 된 이야기가 맨 끝에 있어서 조금 헷갈렸어. 맨 앞으로 옮기면 어때?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_d#13','kor',6,1,'u2','','g6_1_kor_u2_review_d','unit_review','K6-1-u2-C34',2,'ox','auto','맞춤법 검사기를 쓰면 내가 자주 틀리는 곳을 알 수 있어요.',ARRAY['K6-1-u2-X42']::text[],false,'{"seq":13,"concept":"K6-1-u2-C34","difficulty":2,"kind":"ox","stem":"맞춤법 검사기를 쓰면 내가 자주 틀리는 곳을 알 수 있어요.","answer":"O","reason_options":[{"t":"검사기가 띄어쓰기와 맞춤법을 짚어 주어 내 버릇을 알게 해 주기 때문에","correct":true},{"t":"검사기가 글을 다 써 주기 때문에","mis":"K6-1-u2-X42"}],"mis":"K6-1-u2-X42","explanation":["검사기는 빠르게 짚어 줘요.","자주 틀리는 곳이 보여요.","고칠지 말지는 내가 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_d#14','kor',6,1,'u2','','g6_1_kor_u2_review_d','unit_review','K6-1-u2-C15',2,'mc','auto','로운의 글에서 빼야 할 문장은 어느 것인가요?',ARRAY['K6-1-u2-X16','K6-1-u2-X15']::text[],false,'{"seq":14,"concept":"K6-1-u2-C15","difficulty":2,"kind":"mc","stem":"로운의 글에서 빼야 할 문장은 어느 것인가요?","options":[{"t":"텃밭 옆 체육 창고 문은 지난달에 새로 칠했습니다.","correct":true},{"t":"당번은 아침마다 텃밭에 줍니다.","mis":"K6-1-u2-X16"},{"t":"상추는 물을 많이 주면 뿌리가 썩는다고 누가 그랬다.","mis":"K6-1-u2-X16"},{"t":"그래서 순서를 지켜야 한다.","mis":"K6-1-u2-X15"}],"explanation":["물 주기와 관련된 문장은 고쳐 써요.","창고 문 이야기는 상관없어요.","벗어난 문장은 빼요."],"asset":{"type":"passage","lines":["우리 학교 텃밭에는 물 주는 순서가 있는데 그 순서는 반마다 정해 놓은","순서이고 순서를 지키면 채소가 잘 자라는데 순서를 안 지키면 물을 두 번","주게 되고 그래서 순서를 지켜야 한다.","당번은 아침마다 텃밭에 줍니다.","상추는 물을 많이 주면 뿌리가 썩는다고 누가 그랬다.","텃밭 옆 체육 창고 문은 지난달에 새로 칠했습니다."],"title":"로운이 쓴 설명하는 글 초고 「텃밭 물 주기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_d#15','kor',6,1,'u2','','g6_1_kor_u2_review_d','unit_review','K6-1-u2-C31',2,'match','auto','「텃밭 물 주기」를 읽은 친구들의 말과 의견의 갈래를 이으세요.','{}'::text[],false,'{"seq":15,"concept":"K6-1-u2-C31","difficulty":2,"kind":"match","stem":"「텃밭 물 주기」를 읽은 친구들의 말과 의견의 갈래를 이으세요.","pairs":[{"l":"텃밭에 순서가 있는 줄 몰랐어","r":"새롭게 안 점"},{"l":"비 오는 날은 어떻게 하는지 궁금해","r":"궁금한 점"},{"l":"창고 문장은 빼면 좋겠어, 물 주기와 멀어서","r":"고쳤으면 하는 점"}],"mis":"K6-1-u2-X39","explanation":["몰랐던 것을 알게 됐어요.","더 알고 싶은 것이에요.","고칠 곳과 까닭이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_d#16','kor',6,1,'u2','','g6_1_kor_u2_review_d','unit_review','K6-1-u2-C30',2,'ox','auto','줄임말이나 은어는 친구들이 아는 말이니 설명하는 글에 써도 돼요.',ARRAY['K6-1-u2-X09']::text[],false,'{"seq":16,"concept":"K6-1-u2-C30","difficulty":2,"kind":"ox","stem":"줄임말이나 은어는 친구들이 아는 말이니 설명하는 글에 써도 돼요.","answer":"X","reason_options":[{"t":"읽는 사람이 아는 말로 풀어 써야 하고 줄임말 · 은어는 뜻이 흐려지기 때문에","correct":true},{"t":"줄임말이 더 짧아 좋기 때문에","mis":"K6-1-u2-X09"}],"mis":"K6-1-u2-X09","explanation":["모든 읽는 사람이 아는 말이 아니에요.","뜻이 흐려질 수 있어요.","읽는 사람이 아는 말로 풀어 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_d#17','kor',6,1,'u2','','g6_1_kor_u2_review_d','unit_review','K6-1-u2-C3',3,'mc','auto','하린의 초고에서 「연극을 본 이야기가 맨 끝에 있다」는 문제를 찾으려면 어떻게 읽어야 하나요?',ARRAY['K6-1-u2-X04','K6-1-u2-X05']::text[],false,'{"seq":17,"concept":"K6-1-u2-C3","difficulty":3,"kind":"mc","stem":"하린의 초고에서 「연극을 본 이야기가 맨 끝에 있다」는 문제를 찾으려면 어떻게 읽어야 하나요?","options":[{"t":"글 전체의 처음 · 가운데 · 끝 흐름을 살핀다","correct":true},{"t":"한 문장씩 서술어만 살핀다","mis":"K6-1-u2-X04"},{"t":"띄어쓰기만 살핀다","mis":"K6-1-u2-X05"},{"t":"낱말 뜻만 살핀다","mis":"K6-1-u2-X04"}],"explanation":["한 문장만 보면 차례가 안 보여요.","띄어쓰기와 상관없어요.","글 수준에서 흐름을 봐요."],"asset":{"type":"passage","lines":["가장 오래 남은 장면은 할머니가 손녀에게 종이배 접는 법을 가르치는 장면이다.","손녀는 몇 번이나 배를 찢었지만 할머니는 한 번도 서두르지 않았다.","우리 동네 놀이터에는 새 미끄럼틀이 생겼다.","할머니가 「천천히 접으면 물에 오래 뜬단다.」 하고 말했다. 나는 그 장면이 전혀 지루했다.","배 두척을 강물에 띄우는 마지막 장면도 기억에 남는다.","나도 동생에게 무엇을 가르쳐 줄 때 기다려 줄수 있는 사람이 되겠다.","지난 토요일 학교 강당에서 학부모 및학생이 함께 이 연극을 보았다."],"title":"하린이 쓴 연극 감상문 초고 「종이배 이야기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_d#18','kor',6,1,'u2','','g6_1_kor_u2_review_d','unit_review','K6-1-u2-C7',3,'mc','auto','하린이 「고칠 곳이 이렇게 많으니 나는 글을 못 쓰나 봐.」라고 했어요. 알맞은 말은 어느 것인가요?',ARRAY['K6-1-u2-X01','K6-1-u2-X02','K6-1-u2-X10']::text[],false,'{"seq":18,"concept":"K6-1-u2-C7","difficulty":3,"kind":"mc","stem":"하린이 「고칠 곳이 이렇게 많으니 나는 글을 못 쓰나 봐.」라고 했어요. 알맞은 말은 어느 것인가요?","options":[{"t":"「여기 몇 군데만 손보면 네가 하고 싶은 말이 더 잘 전해질 거야.」","correct":true},{"t":"「맞아, 처음부터 새로 써.」","mis":"K6-1-u2-X01"},{"t":"「완벽하게 못 고칠 거면 그만둬.」","mis":"K6-1-u2-X02"},{"t":"「고칠 곳이 많으면 올리지 마.」","mis":"K6-1-u2-X10"}],"explanation":["고쳐 쓰라는 말은 혼내는 말이 아니에요.","완벽할 필요가 없어요.","필요한 곳만 손보면 나아져요."],"asset":{"type":"passage","lines":["가장 오래 남은 장면은 할머니가 손녀에게 종이배 접는 법을 가르치는 장면이다.","손녀는 몇 번이나 배를 찢었지만 할머니는 한 번도 서두르지 않았다.","우리 동네 놀이터에는 새 미끄럼틀이 생겼다.","할머니가 「천천히 접으면 물에 오래 뜬단다.」 하고 말했다. 나는 그 장면이 전혀 지루했다.","배 두척을 강물에 띄우는 마지막 장면도 기억에 남는다.","나도 동생에게 무엇을 가르쳐 줄 때 기다려 줄수 있는 사람이 되겠다.","지난 토요일 학교 강당에서 학부모 및학생이 함께 이 연극을 보았다."],"title":"하린이 쓴 연극 감상문 초고 「종이배 이야기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_d#19','kor',6,1,'u2','','g6_1_kor_u2_review_d','unit_review','K6-1-u2-C12',3,'mc','auto','로운의 글에서 「당번은 아침마다 텃밭에 줍니다.」는 어떻게 하는 것이 알맞은가요?',ARRAY['K6-1-u2-X16','K6-1-u2-X03','K6-1-u2-X34']::text[],false,'{"seq":19,"concept":"K6-1-u2-C12","difficulty":3,"kind":"mc","stem":"로운의 글에서 「당번은 아침마다 텃밭에 줍니다.」는 어떻게 하는 것이 알맞은가요?","options":[{"t":"빼지 않고 「당번은 아침마다 텃밭에 물을 줍니다.」로 고친다","correct":true},{"t":"물 주기와 상관없으니 뺀다","mis":"K6-1-u2-X16"},{"t":"창고 문장 뒤로 옮긴다","mis":"K6-1-u2-X03"},{"t":"그대로 둔다","mis":"K6-1-u2-X34"}],"explanation":["물 주기와 관련 있는 문장이에요.","목적어가 빠졌을 뿐이에요.","지우지 말고 고쳐 써요."],"asset":{"type":"passage","lines":["우리 학교 텃밭에는 물 주는 순서가 있는데 그 순서는 반마다 정해 놓은","순서이고 순서를 지키면 채소가 잘 자라는데 순서를 안 지키면 물을 두 번","주게 되고 그래서 순서를 지켜야 한다.","당번은 아침마다 텃밭에 줍니다.","상추는 물을 많이 주면 뿌리가 썩는다고 누가 그랬다.","텃밭 옆 체육 창고 문은 지난달에 새로 칠했습니다."],"title":"로운이 쓴 설명하는 글 초고 「텃밭 물 주기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_d#20','kor',6,1,'u2','','g6_1_kor_u2_review_d','unit_review','K6-1-u2-C26',3,'ox','auto','「당번은 아침마다 텃밭에 줍니다.」는 말로 하면 통하지만 글에서는 「물을」을 넣어야 해요.',ARRAY['K6-1-u2-X34']::text[],false,'{"seq":20,"concept":"K6-1-u2-C26","difficulty":3,"kind":"ox","stem":"「당번은 아침마다 텃밭에 줍니다.」는 말로 하면 통하지만 글에서는 「물을」을 넣어야 해요.","answer":"O","reason_options":[{"t":"읽는 사람은 그 자리에 없어 무엇을 주는지 알 수 없기 때문에","correct":true},{"t":"글은 말보다 길어야 하기 때문에","mis":"K6-1-u2-X34"}],"mis":"K6-1-u2-X34","explanation":["말할 때는 서로 알아서 빼도 통해요.","읽는 사람은 그 자리에 없었어요.","필수 성분을 갖춰요."],"asset":{"type":"passage","lines":["우리 학교 텃밭에는 물 주는 순서가 있는데 그 순서는 반마다 정해 놓은","순서이고 순서를 지키면 채소가 잘 자라는데 순서를 안 지키면 물을 두 번","주게 되고 그래서 순서를 지켜야 한다.","당번은 아침마다 텃밭에 줍니다.","상추는 물을 많이 주면 뿌리가 썩는다고 누가 그랬다.","텃밭 옆 체육 창고 문은 지난달에 새로 칠했습니다."],"title":"로운이 쓴 설명하는 글 초고 「텃밭 물 주기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_d#21','kor',6,1,'u2','','g6_1_kor_u2_review_d','unit_review','K6-1-u2-C19',3,'mc','auto','「나도 동생에게 무엇을 가르쳐 줄 때 기다려 줄 수 있는 사람이 되겠다.」에서 띄어 쓴 「수」에 대한 설명으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u2-X27','K6-1-u2-X25','K6-1-u2-X24']::text[],false,'{"seq":21,"concept":"K6-1-u2-C19","difficulty":3,"kind":"mc","stem":"「나도 동생에게 무엇을 가르쳐 줄 때 기다려 줄 수 있는 사람이 되겠다.」에서 띄어 쓴 「수」에 대한 설명으로 알맞은 것은 어느 것인가요?","options":[{"t":"홀로 못 쓰는 이름씨라 앞말과 띄어 쓴다","correct":true},{"t":"조사라서 앞말에 붙여 써야 한다","mis":"K6-1-u2-X27"},{"t":"세는 말이라 수와 붙여 쓴다","mis":"K6-1-u2-X25"},{"t":"띄어쓰기는 뜻과 상관없어 아무렇게나 써도 된다","mis":"K6-1-u2-X24"}],"explanation":["「수」는 조사가 아니에요.","세는 말도 아니에요.","홀로 못 쓰는 이름씨라 띄어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_d#22','kor',6,1,'u2','','g6_1_kor_u2_review_d','unit_review','K6-1-u2-C4',3,'mc','auto','세아와 민석이의 말을 함께 볼 때 글을 공유하는 일의 좋은 점으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u2-X10']::text[],false,'{"seq":22,"concept":"K6-1-u2-C4","difficulty":3,"kind":"mc","stem":"세아와 민석이의 말을 함께 볼 때 글을 공유하는 일의 좋은 점으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"내가 못 본 곳을 친구가 짚어 주고, 읽는 사람을 떠올리며 더 꼼꼼히 고치게 된다","correct":true},{"t":"친구가 대신 글을 써 준다","mis":"K6-1-u2-X10"},{"t":"공유하면 더 고칠 필요가 없다","mis":"K6-1-u2-X10"},{"t":"칭찬을 많이 받아 기분이 좋다","mis":"K6-1-u2-X10"}],"explanation":["친구는 대신 쓰지 않아요.","공유한 뒤에도 고쳐요.","못 본 곳과 읽는 사람을 알게 돼요."],"asset":{"type":"speech","turns":[{"who":"세아","text":"학급 게시판에 올린 내 글에 댓글이 세 개 달렸어. 내가 못 본 곳을 친구가 짚어 줬어."},{"who":"민석","text":"나도 올려 봤는데, 읽는 사람이 있다고 생각하니까 문장을 더 꼼꼼히 보게 되더라."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_d#23','kor',6,1,'u2','','g6_1_kor_u2_review_d','unit_review','K6-1-u2-C37',4,'mc','auto','하린의 감상문을 학급 게시판에 소개하는 글로 바꿀 때 가장 알맞은 문장은 어느 것인가요?',ARRAY['K6-1-u2-X44','K6-1-u2-X45','K6-1-u2-X09']::text[],false,'{"seq":23,"concept":"K6-1-u2-C37","difficulty":4,"kind":"mc","stem":"하린의 감상문을 학급 게시판에 소개하는 글로 바꿀 때 가장 알맞은 문장은 어느 것인가요?","options":[{"t":"할머니가 손녀에게 종이배 접는 법을 서두르지 않고 가르치는 장면에서, 기다려 주는 것도 가르침이라는 걸 알게 되었습니다.","correct":true},{"t":"이 연극은 최고예요. 무조건 보세요.","mis":"K6-1-u2-X44"},{"t":"연극은 배우가 무대에서 하는 공연입니다.","mis":"K6-1-u2-X45"},{"t":"ㄹㅇ 꿀잼 연극 강추","mis":"K6-1-u2-X09"}],"explanation":["자랑은 알 수 있는 것이 없어요.","누구에게나 있는 말은 소개가 아니에요.","줄임말 없이 그려 볼 수 있게 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_d#24','kor',6,1,'u2','','g6_1_kor_u2_review_d','unit_review','K6-1-u2-C32',4,'essay','teacher','하린이 친구들의 의견을 어떻게 골라 받아들였는지 쓰고, 의견을 고르는 기준이 왜 필요한지 내 생각을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K6-1-u2-C32","difficulty":4,"kind":"essay","stem":"하린이 친구들의 의견을 어떻게 골라 받아들였는지 쓰고, 의견을 고르는 기준이 왜 필요한지 내 생각을 쓰세요.","answer_guide":{"answer":"예: 하린은 연극을 본 이야기를 맨 앞으로 옮기자는 보미의 의견과 놀이터 문장을 빼자는 서준의 의견을 받아들였다. 다른 연극 이름을 다 적자는 지호의 의견은 「종이배」 감상문과 멀어서 넣지 않았다. 의견을 모두 따르면 글이 하려던 말과 멀어질 수 있다. 그래서 「이 의견을 따르면 내가 하려던 말이 더 잘 전해지는가?」라는 기준으로 골라야 내 글이 나아진다.","scoring_points":["받아들인 의견과 받아들이지 않은 의견을 썼는가","받아들이지 않은 까닭을 썼는가","기준이 필요한 까닭을 썼는가"]},"explanation":["세 친구의 의견을 나눠 봐요.","넣지 않은 까닭을 써요.","기준이 왜 필요한지 써요."],"asset":{"type":"speech","turns":[{"who":"지호","text":"하린아, 끝에 네가 좋아하는 다른 연극 이름도 다 적으면 어때?"},{"who":"하린","text":"고맙지만 이 글은 「종이배」 감상문이라 그건 넣지 않을래."},{"who":"하린","text":"보미 말대로 연극을 본 이야기는 맨 앞으로 옮겼어. 서준이 말대로 놀이터 문장은 뺐고."},{"who":"하린","text":"띄어쓰기는 검사기를 돌려 봤는데, 왜 그렇게 고쳤는지 하나씩 확인하고 받아들였어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u2_review_d#25','kor',6,1,'u2','','g6_1_kor_u2_review_d','unit_review','K6-1-u2-C39',4,'essay','teacher','「닫다 · 닫히다」 또는 「놓다 · 놓이다」를 골라 두 말을 넣은 문장을 하나씩 만들고, 두 말이 어떻게 다른지 설명하세요.','{}'::text[],false,'{"seq":25,"concept":"K6-1-u2-C39","difficulty":4,"kind":"essay","stem":"「닫다 · 닫히다」 또는 「놓다 · 놓이다」를 골라 두 말을 넣은 문장을 하나씩 만들고, 두 말이 어떻게 다른지 설명하세요.","answer_guide":{"answer":"예: 나는 책상 위에 책을 놓았다. / 책상 위에 책이 놓여 있었다. 「놓다」는 내가 스스로 하는 일을 나타내는 말이고, 「놓이다」는 다른 힘에 의해 그렇게 된 일을 나타내는 말이다. 스스로 하는 일에는 「-이-」를 붙이지 않는다.","scoring_points":["두 말을 넣은 문장을 하나씩 바르게 만들었는가","스스로 하는 일과 그리 되는 일로 차이를 설명했는가","-히- · -리- · -이-를 붙이는 경우를 바르게 썼는가"]},"explanation":["두 말을 골라요.","문장을 하나씩 만들어요.","스스로 하는가, 그리 되는가로 견주어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
